function normalizeCleanupText(value = "") {
  return String(value || "").trim().toLowerCase().replace(/[\s-]+/g, "_");
}

function cleanupRawPayloadFlagExplicitFalse(source = {}, keys = [], { allowMissing = false } = {}) {
  const presentKey = keys.find((key) => Object.hasOwn(source, key));
  if (!presentKey) return allowMissing;
  return source[presentKey] === false;
}

function cleanupItemsOutsideExpectedScope(items = [], expected = {}) {
  const allowedRefs = new Set([
    expected.worktreePath ? `worktree:${expected.worktreePath}` : "",
    expected.localBranch ? `local-branch:${expected.localBranch}` : "",
    expected.remoteBranch ? `remote-branch:${expected.remoteBranch}` : "",
    "assignment-state:already-closed",
    "assignment-state:closed",
    "worktree:already-absent",
    "branches:already-absent",
    "local-branch:already-absent",
    "remote-branch:already-absent",
  ].filter(Boolean));
  return items.filter((item) => !allowedRefs.has(item));
}

export function buildLedgerReadiness(options = {}, context = {}) {
  const runId = resolveManagerRunId(options, context);
  const paths = managerRunPaths(runId, options, context);
  const files = {};
  const schemaGaps = [];
  const jsonFiles = [
    ["mission", paths.mission],
    ["workers", paths.workers],
    ["dispatcherSummary", paths.dispatcherSummary],
    ["checkpoints", paths.checkpoints],
  ];
  const ndjsonFiles = [
    ["events", paths.events],
    ["questions", paths.questions],
    ["resourceSnapshots", paths.resourceSnapshots],
    ["usageSnapshots", paths.usageSnapshots],
  ];
  const jsonData = {};
  const ndjsonData = {};

  for (const [key, path] of jsonFiles) {
    const result = readJsonStrict(path);
    files[key] = result.status;
    if (result.status !== "ready") {
      schemaGaps.push({ code: `ledger-file-${result.status}`, file: key, path, message: result.message });
    } else {
      jsonData[key] = result.value;
    }
  }

  if (files.workers === "ready" && !Array.isArray(jsonData.workers)) {
    files.workers = "malformed";
    schemaGaps.push({ code: "ledger-file-malformed", file: "workers", path: paths.workers, message: "workers.json must contain an array." });
  }
  if (files.mission === "ready" && !isPlainObject(jsonData.mission)) {
    files.mission = "malformed";
    schemaGaps.push({ code: "ledger-file-malformed", file: "mission", path: paths.mission, message: "mission.json must contain an object." });
  }
  if (files.checkpoints === "ready" && !Array.isArray(jsonData.checkpoints)) {
    files.checkpoints = "malformed";
    schemaGaps.push({ code: "ledger-file-malformed", file: "checkpoints", path: paths.checkpoints, message: "checkpoints.json must contain an array." });
  }
  if (files.dispatcherSummary === "ready" && !isPlainObject(jsonData.dispatcherSummary)) {
    files.dispatcherSummary = "malformed";
    schemaGaps.push({ code: "ledger-file-malformed", file: "dispatcherSummary", path: paths.dispatcherSummary, message: "dispatcher-summary.json must contain an object." });
  }
  if (files.workers === "ready" && jsonData.workers.some((record) => !isPlainObject(record))) {
    files.workers = "malformed";
    schemaGaps.push({ code: "ledger-file-malformed", file: "workers", path: paths.workers, message: "workers.json must contain only object records." });
  }
  if (files.checkpoints === "ready" && jsonData.checkpoints.some((record) => !isPlainObject(record))) {
    files.checkpoints = "malformed";
    schemaGaps.push({ code: "ledger-file-malformed", file: "checkpoints", path: paths.checkpoints, message: "checkpoints.json must contain only object records." });
  }

  for (const [key, path] of ndjsonFiles) {
    const result = readNdjsonStrict(path);
    files[key] = result.status;
    if (result.status !== "ready") {
      schemaGaps.push({ code: `ledger-file-${result.status}`, file: key, path, message: result.message });
    } else {
      ndjsonData[key] = result.value;
    }
  }
  for (const [key, path] of ndjsonFiles) {
    if (files[key] === "ready" && ndjsonData[key].some((record) => !isPlainObject(record))) {
      files[key] = "malformed";
      schemaGaps.push({ code: "ledger-file-malformed", file: key, path, message: `${key} must contain only object records.` });
    }
  }
  if (files.events === "ready") {
    const invalidEvent = ndjsonData.events.find((record) => validateRuntimeLedgerEventRecord(record) !== null);
    if (invalidEvent) {
      files.events = "malformed";
      schemaGaps.push({
        code: "ledger-event-schema-invalid",
        file: "events",
        path: paths.events,
        message: validateRuntimeLedgerEventRecord(invalidEvent),
      });
    }
  }
  if (files.questions === "ready") {
    const invalidQuestion = ndjsonData.questions.find((record) => validateRuntimeLedgerEventRecord(record) !== null);
    if (invalidQuestion) {
      files.questions = "malformed";
      schemaGaps.push({
        code: "ledger-event-schema-invalid",
        file: "questions",
        path: paths.questions,
        message: validateRuntimeLedgerEventRecord(invalidQuestion),
      });
    }
  }
  if (files.resourceSnapshots === "ready") {
    const invalidResource = ndjsonData.resourceSnapshots.find((record) => validateRuntimeLedgerEventRecord(record) !== null);
    if (invalidResource) {
      files.resourceSnapshots = "malformed";
      schemaGaps.push({
        code: "ledger-event-schema-invalid",
        file: "resourceSnapshots",
        path: paths.resourceSnapshots,
        message: validateRuntimeLedgerEventRecord(invalidResource),
      });
    }
  }
  if (files.usageSnapshots === "ready") {
    const invalidUsage = ndjsonData.usageSnapshots.find((record) => validateRuntimeLedgerEventRecord(record) !== null);
    if (invalidUsage) {
      files.usageSnapshots = "malformed";
      schemaGaps.push({
        code: "ledger-event-schema-invalid",
        file: "usageSnapshots",
        path: paths.usageSnapshots,
        message: validateRuntimeLedgerEventRecord(invalidUsage),
      });
    }
  }
  if (files.checkpoints === "ready") {
    const invalidCheckpoint = jsonData.checkpoints.find((record) => validateRuntimeLedgerEventRecord(record) !== null);
    if (invalidCheckpoint) {
      files.checkpoints = "malformed";
      schemaGaps.push({
        code: "ledger-event-schema-invalid",
        file: "checkpoints",
        path: paths.checkpoints,
        message: validateRuntimeLedgerEventRecord(invalidCheckpoint),
      });
    }
  }

  return packet({
    ok: schemaGaps.length === 0,
    status: schemaGaps.length === 0 ? "ready" : "blocked",
    summary: {
      runId,
      stateRoot: paths.proof.state.root,
      root: paths.root,
      files,
      mission: jsonData.mission
        ? {
            runId: jsonData.mission.runId || null,
            runState: jsonData.mission.runState || "unknown",
            authorityProfile: jsonData.mission.authorityProfile || "unknown",
            updatedAt: jsonData.mission.updatedAt || null,
          }
        : null,
      workerCount: Array.isArray(jsonData.workers) ? jsonData.workers.length : 0,
      checkpointCount: Array.isArray(jsonData.checkpoints) ? jsonData.checkpoints.length : 0,
      dispatcherSummary: jsonData.dispatcherSummary || null,
      eventCount: ndjsonData.events?.length || 0,
      questionCount: ndjsonData.questions?.length || 0,
      resourceSnapshotCount: ndjsonData.resourceSnapshots?.length || 0,
      usageSnapshotCount: ndjsonData.usageSnapshots?.length || 0,
      schemaGaps,
    },
    blockers: schemaGaps.map((gap) => ({
      code: gap.code,
      message: `${gap.file}: ${gap.message}`,
      nextAction: "Repair or initialize manager ledger before resuming mutation.",
    })),
  });
}

export function buildResumeState(options = {}, context = {}) {
  const runOptions = { ...options, runId: resolveManagerRunId(options, context) };
  const workspace = getWorkspaceProof(runOptions, context);
  const ledger = buildLedgerReadiness(runOptions, context);
  const assignment = buildAssignmentResume(runOptions, context);
  const tmux = buildTmuxOrientationStatus(runOptions, context.tmuxContext || {});
  const takeoverInspection = buildTakeoverInspectionPlan(assignment.summary);
  const blockers = [];

  if (!workspace.ok) {
    blockers.push({ code: "workspace-state-unsafe", message: workspace.error, nextAction: "Choose a safe workspace state root." });
  }
  blockers.push(...(ledger.blockers || []));
  blockers.push(...(assignment.blockers || []));
  if (!tmux.summary.available) {
    blockers.push({
      code: "tmux-orientation-unavailable",
      message: tmux.summary.error || "tmux orientation unavailable",
      nextAction: "Restore tmux orientation or keep worker mutation disabled.",
    });
  }
  for (const blocker of tmuxOrientationBlockers(tmux.summary)) {
    blockers.push(blocker);
  }

  return packet({
    ok: blockers.length === 0,
    status: blockers.length === 0 ? "ready" : "blocked",
    summary: {
      runId: runOptions.runId,
      ledger: ledger.summary,
      assignment: assignment.summary,
      tmux: tmux.summary,
      takeoverInspection,
      workspace: {
        ok: workspace.ok,
        stateRoot: workspace.state.root,
        proof: workspace.proof || null,
      },
      schemaGaps: ledger.summary.schemaGaps,
      resumeActions: blockers.length === 0 ? [{ code: "resume-safe", summary: "Resume evidence is consistent for read-only continuation." }] : [],
    },
    blockers,
    warnings: [...(tmux.warnings || []), ...(assignment.warnings || [])],
    nextActions: blockers.length === 0 ? [{ code: "resume-ready", summary: "Resume from compact manager state." }] : [],
  });
}

export function buildAssignmentResume(options = {}, context = {}) {
  const assignmentArgs = ["assignment-report", "--summary-json"];
  if (options.stateRoot) assignmentArgs.push("--state-root", options.stateRoot);
  const assignment = context.assignmentSummary || runWorkspaceJson(assignmentArgs, context);
  if (assignment?.ok === false) {
    return packet({
      ok: false,
      status: "blocked",
      summary: { available: false, source: "assignment-report", statusCounts: {}, counts: {} },
      blockers: [
        {
          code: "assignment-report-unavailable",
          message: assignment.error || "assignment report unavailable",
          nextAction: "Restore assignment inventory before resuming manager mutation.",
        },
      ],
    });
  }
  const report = assignment?.summary || assignment || {};
  const statusCounts = {
    backlog: report.backlogStatusCounts || {},
    laneAssignments: report.laneAssignmentStatusCounts || {},
    workspaceAssignments: report.workspaceAssignmentStatusCounts || {},
  };
  const ambiguous = ambiguousAssignmentStatusCounts(statusCounts);
  return packet({
    ok: ambiguous.length === 0,
    status: ambiguous.length === 0 ? "ready" : "blocked",
    summary: {
      available: true,
      source: "assignment-report",
      stateRoot: report.stateRoot || null,
      counts: report.counts || {},
      statusCounts,
      truncated: {
        backlogCandidates: Boolean(report.backlogCandidatesTruncated),
        laneAssignments: Boolean(report.laneAssignmentsTruncated),
        workspaceAssignments: Boolean(report.workspaceAssignmentsTruncated),
      },
      blockedLaneAssignments: Array.isArray(report.blockedLaneAssignments) ? report.blockedLaneAssignments : [],
      blockedWorkspaceAssignments: Array.isArray(report.blockedWorkspaceAssignments) ? report.blockedWorkspaceAssignments : [],
      ambiguousStatusCounts: ambiguous,
    },
    blockers: ambiguous.map((item) => ({
      code: "assignment-ambiguous-status",
      message: `${item.bucket} has ${item.count} ${item.status} item(s).`,
      nextAction: "node ./scripts/manager-stale-owner-inspection.mjs --summary-json",
    })),
  });
}

function buildTakeoverInspectionPlan(assignmentSummary = {}) {
  const laneAssignments = Array.isArray(assignmentSummary?.blockedLaneAssignments) ? assignmentSummary.blockedLaneAssignments : [];
  const workspaceAssignments = Array.isArray(assignmentSummary?.blockedWorkspaceAssignments) ? assignmentSummary.blockedWorkspaceAssignments : [];
  const laneTargets = laneAssignments.map((assignment) => buildTakeoverInspectionTarget("lane_assignment", assignment.assignmentId || assignment.assignment_id, assignment));
  const workspaceTargets = workspaceAssignments.map((assignment) => buildTakeoverInspectionTarget("workspace_assignment", assignment.taskId || assignment.task_id, assignment));
  const targets = [...laneTargets, ...workspaceTargets].filter(Boolean).slice(0, 12);
  return {
    needed: targets.length > 0,
    mutationMode: "dry_run_only",
    targetCount: targets.length,
    targets,
    stopLines: [
      "do_not_apply_takeover_without_explicit_operator_approval",
      "do_not_launch_workers",
      "do_not_kill_workers",
      "do_not_mutate_unknown_or_non_manager_owned_processes",
    ],
  };
}

function takeoverInspectionNextActions(takeoverInspection = {}) {
  if (!takeoverInspection?.needed || !Array.isArray(takeoverInspection.targets) || takeoverInspection.targets.length === 0) return [];
  return [
    {
      code: "takeover-inspection-required",
      summary: `Prepare dry-run takeover evidence for ${takeoverInspection.targetCount} stale owner target(s).`,
      nextAction: "node ./scripts/manager-stale-owner-inspection.mjs --summary-json",
    },
  ];
}

function buildTakeoverInspectionTarget(kind, rawId, assignment = {}) {
  const id = sanitizeLedgerField(rawId || "", "", 140);
  if (!id) return null;
  const reason = `manager dogfood stale owner inspection for ${id}`;
  return {
    kind,
    id,
    owner: sanitizeLedgerField(assignment.owner || "", "", 120),
    branch: sanitizeLedgerField(assignment.branch || "", "", 140),
    phase: sanitizeLedgerField(assignment.phase || "", "", 80),
    heartbeat: sanitizeLedgerField(assignment.heartbeat || assignment.lastHeartbeatAt || "", "", 80),
    staleReason: sanitizeLedgerField(assignment.reason || "", "", 180),
    nextAction: "Run the dry-run takeover inspection command and ask the operator before any apply.",
    dryRunCommand: `node ./scripts/codex-workspace.mjs takeover ${shellSingleQuote(id)} --dry-run --summary-json --takeover-reason ${shellSingleQuote(reason)}`,
    mutationMode: "dry_run_only",
  };
}

export function buildStaleOwnerInspection(options = {}, context = {}) {
  const runOptions = { ...options, runId: resolveManagerRunId(options, context) };
  const resume = context.resumeState || buildResumeState(runOptions, context);
  const targets = Array.isArray(resume.summary?.takeoverInspection?.targets) ? resume.summary.takeoverInspection.targets : [];
  const limit = runOptions.limit === null || runOptions.limit === undefined ? targets.length : Math.max(0, Number(runOptions.limit) || 0);
  const inspections = targets.slice(0, limit).map((target) => inspectStaleOwnerTarget(target, context, runOptions));
  const failed = inspections.filter((inspection) => !inspection.ok);
  const cleanupCandidates = inspections.filter((inspection) => inspection.classification === "stale_record_cleanup_candidate");
  const dirtyWorkspaces = inspections.filter((inspection) => inspection.classification === "dirty_workspace_preservation_required");
  const approvalCandidates = inspections.filter((inspection) => inspection.classification === "takeover_apply_candidate_with_approval");
  const blockers = failed.map((inspection) => ({
    code: "stale-owner-inspection-failed",
    message: inspection.error || `Failed stale-owner inspection for ${inspection.id || "(missing id)"}.`,
    nextAction: inspection.nextAction || "Refresh manager resume state and rerun stale-owner inspection.",
  }));
  return packet({
    ok: blockers.length === 0,
    status: blockers.length > 0 ? "blocked" : inspections.length > 0 ? "attention" : "ready",
    summary: {
      runId: resume.summary?.ledger?.runId || runOptions.runId,
      targetCount: targets.length,
      inspectedCount: inspections.length,
      cleanupCandidateCount: cleanupCandidates.length,
      dirtyWorkspaceCount: dirtyWorkspaces.length,
      takeoverApprovalCandidateCount: approvalCandidates.length,
      inspections,
      mutation: "none; dry-run takeover evidence only",
      retention: "metadata_only_stale_owner_inspection",
    },
    blockers,
    warnings: [
      ...(cleanupCandidates.length > 0 ? [{ code: "stale-owner-cleanup-candidates", message: `${cleanupCandidates.length} stale owner target(s) look like abandoned records rather than takeover work.` }] : []),
      ...(dirtyWorkspaces.length > 0 ? [{ code: "dirty-stale-owner-workspaces", message: `${dirtyWorkspaces.length} stale owner workspace(s) have dirty worktree evidence that must be preserved before apply or cleanup.` }] : []),
    ],
    nextActions: staleOwnerInspectionNextActions({ cleanupCandidates, dirtyWorkspaces, approvalCandidates, inspections }),
  });
}

function inspectStaleOwnerTarget(target = {}, context = {}, options = {}) {
  const id = sanitizeLedgerField(target.id || "", "", 140);
  if (!id) {
    return { ok: false, id: "", classification: "invalid_target", error: "stale owner target id is missing", nextAction: "Refresh manager resume state." };
  }
  const reason = `manager dogfood stale owner inspection for ${id}`;
  const takeoverArgs = workspaceJsonArgs(["takeover", id, "--dry-run", "--summary-json", "--takeover-reason", reason], options);
  const result = context.takeoverResults?.[id] || runWorkspaceJson(takeoverArgs, context);
  if (!result || result.ok === false || result.error) {
    return {
      ok: false,
      kind: target.kind,
      id,
      classification: "inspection_failed",
      error: result?.error || "takeover dry-run did not return a usable packet",
      nextAction: target.dryRunCommand || appendWorkspaceCommandScope(`node ./scripts/codex-workspace.mjs takeover ${shellSingleQuote(id)} --dry-run --summary-json --takeover-reason ${shellSingleQuote(reason)}`, options),
    };
  }
  const classification = classifyStaleOwnerTakeoverResult(result);
  return {
    ok: true,
    kind: target.kind,
    id,
    owner: target.owner || result.previousOwner || "",
    branch: result.branch?.branch || target.branch || "",
    decision: sanitizeLedgerField(result.decision || "", "", 80),
    allowed: result.allowed === true,
    classification,
    worktreePath: sanitizeLedgerField(result.worktree?.path || "", "", 260),
    worktreeStatus: sanitizeLedgerField(result.worktree?.status || "", "", 80),
    worktreeExists: result.worktree?.exists === true,
    branchStatus: sanitizeLedgerField(result.branch?.status || "", "", 80),
    localSha: result.branch?.localSha || null,
    remoteSha: result.branch?.remoteSha || null,
    prStatus: sanitizeLedgerField(result.pr?.status || "", "", 80),
    dirty: result.dirtyState?.dirty === true,
    blockers: Array.isArray(result.blockers) ? result.blockers.slice(0, 6) : [],
    nextAction: staleOwnerTargetNextAction(classification, id),
    mutation: "none; dry-run summary only",
  };
}

function classifyStaleOwnerTakeoverResult(result = {}) {
  const worktreeMissing = result.worktree?.status === "missing" || result.worktree?.exists === false;
  const branchMissing = !result.branch?.localSha && !result.branch?.remoteSha;
  const noPr = !result.pr?.pr_number && !result.pr?.pr_url && (!result.pr?.status || result.pr.status === "none");
  if (worktreeMissing && branchMissing && noPr) return "stale_record_cleanup_candidate";
  if (result.dirtyState?.dirty === true || result.worktree?.status === "dirty") return "dirty_workspace_preservation_required";
  if (result.allowed === true) return "takeover_apply_candidate_with_approval";
  return "takeover_blocked_needs_operator_or_evidence";
}

function staleOwnerTargetNextAction(classification, id) {
  if (classification === "stale_record_cleanup_candidate") {
    return `Prepare cleanup/close evidence for stale assignment ${id}; do not request takeover apply for a missing worktree/branch record.`;
  }
  if (classification === "dirty_workspace_preservation_required") {
    return `Preserve bounded dirty-worktree evidence for ${id} before any takeover apply or cleanup decision.`;
  }
  if (classification === "takeover_apply_candidate_with_approval") {
    return `Ask operator for explicit takeover apply approval for ${id} only if the dry-run evidence is still needed.`;
  }
  return `Keep ${id} blocked until missing approval or evidence is resolved.`;
}

function staleOwnerInspectionNextActions({ cleanupCandidates = [], dirtyWorkspaces = [], approvalCandidates = [], inspections = [] } = {}) {
  if (cleanupCandidates.length > 0) {
    return [{
      code: "stale-owner-cleanup-inspection",
      summary: `${cleanupCandidates.length} stale owner target(s) appear to be cleanup candidates, not takeover candidates.`,
      nextAction: "node ./scripts/manager-cleanup-plan.mjs --summary-json",
    }];
  }
  if (dirtyWorkspaces.length > 0) {
    return [{
      code: "stale-owner-dirty-workspace-inspection",
      summary: `${dirtyWorkspaces.length} stale owner workspace(s) need dirty-worktree preservation before apply.`,
      nextAction: "Preserve bounded dirty-worktree evidence, then rerun node ./scripts/manager-stale-owner-inspection.mjs --summary-json.",
    }];
  }
  if (approvalCandidates.length > 0) {
    return [{
      code: "stale-owner-takeover-approval-needed",
      summary: `${approvalCandidates.length} stale owner target(s) passed dry-run takeover gates but still need explicit operator approval.`,
      nextAction: "Ask operator for explicit takeover apply approval for the exact target ids.",
    }];
  }
  return [{
    code: inspections.length > 0 ? "stale-owner-inspection-complete" : "stale-owner-inspection-not-needed",
    summary: inspections.length > 0 ? "Stale owner inspection found no cleanup, dirty workspace, or apply-ready target." : "No stale owner target requires inspection.",
    nextAction: "Continue active worker monitoring.",
  }];
}

function shellSingleQuote(value = "") {
  return `'${String(value).replaceAll("'", "'\"'\"'")}'`;
}

function appendManagerCommandScope(command = "", options = {}) {
  let next = String(command || "").trim();
  const runId = sanitizeLedgerField(options.runId || "", "", 120);
  if (runId && !/\s--run-id(?:=|\s)/.test(next)) {
    next += ` --run-id ${shellSingleQuote(runId)}`;
  }
  return appendWorkspaceCommandScope(next, options);
}

function appendWorkspaceCommandScope(command = "", options = {}) {
  let next = String(command || "").trim();
  const stateRoot = sanitizeLedgerField(options.stateRoot || "", "", 260);
  if (stateRoot && !/\s--state-root(?:=|\s)/.test(next)) {
    next += ` --state-root ${shellSingleQuote(stateRoot)}`;
  }
  return next;
}

function cycleRunScope(cycle = {}) {
  return {
    runId: cycle.summary?.run?.runId || "",
    stateRoot: cycle.summary?.run?.stateRoot || "",
  };
}

export function classifyAutoApply(operation, context = {}) {
  const lowRiskOperations = new Set(["ledger.append", "worker.heartbeat", "worker-target.update", "refill.metadata", "dispatch.apply", "cleanup.merged-lane"]);
  const existingGateOperations = new Set(["dispatch.apply", "cleanup.merged-lane"]);
  const resourceState = context.resourceState || "unknown";
  const usageState = context.usageState || "unknown";
  const weeklyUsage = normalizeWeeklyUsagePressure(context.weeklyUsage || context.weeklyUsageContext);
  const missingProof = autoApplyMissingProof(operation, context, { existingGateOperations });
  if (isBlockedRisk(context.risk) || isBlockedOwnership(context.ownershipEvidence)) {
    return {
      operation,
      posture: "blocked",
      authorityBasis: context.authorityBasis || "blocked-risk-or-ownership",
      sourceEvidence: context.sourceEvidence || "missing",
      ownershipEvidence: context.ownershipEvidence || "missing",
      resourceState,
      usageState,
      weeklyUsage,
      recoveryPath: context.recoveryPath || "stop and request operator approval before high-risk or outside-owner action",
      reason: "Auto-apply is blocked for high-risk or outside-manager-owned operations.",
    };
  }
  if (resourceState === "critical" || usageState === "manager_only") {
    return {
      operation,
      posture: "blocked",
      authorityBasis: context.authorityBasis || "resource-or-usage-stop-line",
      sourceEvidence: context.sourceEvidence || "manager-runtime-state",
      ownershipEvidence: context.ownershipEvidence || "manager-run-owner",
      resourceState,
      usageState,
      weeklyUsage,
      recoveryPath: context.recoveryPath || "wait for reset or reduce host pressure before applying manager-owned mutation",
      reason: "Manager-owned mutation is blocked while usage or host pressure is at a stop-line state.",
    };
  }
  if (["dispatch.apply", "worker-target.update"].includes(operation) && weeklyUsage.state === "pressured") {
    return {
      operation,
      posture: "dry_run_required",
      authorityBasis: context.authorityBasis || "weekly-usage-pressure",
      sourceEvidence: context.sourceEvidence || "manager-runtime-state",
      ownershipEvidence: context.ownershipEvidence || "manager-run-owner",
      resourceState,
      usageState,
      weeklyUsage,
      recoveryPath: context.recoveryPath || "defer new dispatch or optional work until weekly pressure recovers",
      reason: "Reliable weekly usage pressure reduces new lease issuance before model quality changes.",
      missingProof: [...new Set([...missingProof, "weeklyUsageDispatchPosture"])],
    };
  }
  if (!lowRiskOperations.has(operation)) {
    return {
      operation,
      posture: "dry_run_required",
      authorityBasis: context.authorityBasis || "operation-not-low-risk-allowlisted",
      sourceEvidence: context.sourceEvidence || "required",
      ownershipEvidence: context.ownershipEvidence || "required",
      resourceState,
      usageState,
      weeklyUsage,
      recoveryPath: context.recoveryPath || "prove low-risk operation class or request operator approval",
      reason: "Auto-apply requires a known low-risk manager-owned operation class.",
      missingProof: ["lowRiskOperationClass"],
    };
  }
  if (missingProof.length > 0) {
    return {
      operation,
      posture: "dry_run_required",
      authorityBasis: context.authorityBasis || "missing-auto-apply-proof",
      sourceEvidence: context.sourceEvidence || "required",
      ownershipEvidence: context.ownershipEvidence || "required",
      resourceState,
      usageState,
      weeklyUsage,
      recoveryPath: context.recoveryPath || `Provide missing proof: ${missingProof.join(", ")}.`,
      reason: `Auto-apply requires missing proof: ${missingProof.join(", ")}.`,
      missingProof,
    };
  }
  return {
    operation,
    posture: "auto_apply_allowed",
    authorityBasis: context.authorityBasis,
    sourceEvidence: context.sourceEvidence,
    ownershipEvidence: context.ownershipEvidence,
    resourceState,
    usageState,
    weeklyUsage,
    recoveryPath: context.recoveryPath,
    reason: "Operation is manager-owned and low risk.",
    missingProof: [],
  };
}

function autoApplyMissingProof(operation, context = {}, policy = {}) {
  const missing = [];
  if (!validProofValue(context.authorityBasis, ["manager-owned-low-risk-mvp", "source-owned-refill-planning", "codex-workspace-existing-gates", "merged-lane-cleanup-gates"])) missing.push("authorityBasis");
  if (!validProofValue(context.ownershipEvidence, ["manager-run-owner", "manager-owned-worker", "manager-owned-lane"])) missing.push("ownershipEvidence");
  if (!validSourceEvidence(operation, context.sourceEvidence)) missing.push("sourceEvidence");
  if (!validRecoveryPath(context.recoveryPath)) missing.push("recoveryPath");
  if (!["normal", "warm"].includes(context.resourceState || "")) missing.push("resourceState");
  if (!["normal", "conserve"].includes(context.usageState || "")) missing.push("usageState");
  if (operation === "dispatch.apply" && context.usageState !== "normal") missing.push("dispatchPosture");
  if (policy.existingGateOperations?.has(operation) && context.operationGate !== "existing-gates-proven") missing.push("existingGateProof");
  return missing;
}

function validProofValue(value, allowed = []) {
  const text = String(value || "").trim();
  if (!text || /^(unknown|missing|ambiguous|none|required|outside|external)/i.test(text)) return false;
  return allowed.includes(text);
}

function validSourceEvidence(operation, value) {
  const text = String(value || "").trim();
  if (!text || /^(unknown|missing|ambiguous|none|required|chat-only)/i.test(text)) return false;
  if (operation === "refill.metadata") return text === "source-owned-refill-plan";
  if (operation === "dispatch.apply") return text === "codex-workspace-existing-gates";
  if (operation === "cleanup.merged-lane") return text === "merged-pr-cleanup-proof";
  return text === "manager-runtime-state";
}

function validRecoveryPath(value) {
  const text = String(value || "").trim();
  return Boolean(text) && !/^(unknown|missing|ambiguous|none|required)$/i.test(text);
}

function isBlockedRisk(value) {
  return /^(high|ambiguous|unsafe|broad)$/i.test(String(value || "").trim());
}

function isBlockedOwnership(value) {
  return /^(outside-manager-owner|outside|external|ambiguous|unknown)$/i.test(String(value || "").trim());
}

export function buildPreflight(options = {}, context = {}) {
  const runOptions = { ...options, runId: resolveManagerRunId(options, context), apply: false };
  const workspace = getWorkspaceProof(runOptions, context);
  const repo = buildRepoPreflightStatus(context);
  const branch = buildBranchPreflightStatus(context);
  const githubCli = buildGithubCliPreflightStatus(context);
  const workspaceProtocol = buildWorkspaceProtocolPreflightStatus(workspace);
  const ledger = buildLedgerReadiness(runOptions, context);
  const tmux = buildTmuxOrientationStatus(runOptions, context.tmuxContext || {});
  const resource = buildResourceStatus(context.resourceContext || {});
  const usage = buildUsageStatus(context.usageContext || {});
  const dispatchPreview = context.dispatchPreview ? normalizeDispatchPreviewContext(context.dispatchPreview) : buildDispatchPreview(runOptions, context);
  const dispatcher = buildDispatcherPreflightStatus(dispatchPreview, ledger);
  const workers = buildWorkerStatus(runOptions, { ...context, usageContext: usage, resourceContext: resource, dispatchPreview });
  const refill = buildRefillPlan(runOptions, { ...context, dispatchPreview, discoverDefaultSources: true });
  const cleanup = buildCleanupPlan(runOptions, context);
  const blockerList = [];
  if (!workspace.ok) {
    blockerList.push({ code: "workspace-state-unsafe", message: workspace.error, nextAction: "Choose a safe workspace state root." });
  }
  if (dispatcher.status !== "ready") {
    const dispatcherBlockers = Array.isArray(dispatcher.blockers) && dispatcher.blockers.length > 0
      ? dispatcher.blockers
      : [`Dispatcher preflight is ${dispatcher.status || "not ready"}.`];
    blockerList.push(
      ...dispatcherBlockers.map((message, index) => ({
        code: index === 0 ? `preflight-dispatcher-${dispatcher.status || "not-ready"}` : `preflight-dispatcher-${dispatcher.status || "not-ready"}-${index + 1}`,
        message: sanitizeLedgerField(message, "Dispatcher preflight is not ready.", 220),
        nextAction: "Resolve dispatcher blockers before manager mutation.",
      })),
    );
  }
  blockerList.push(...(ledger.blockers || []));
  blockerList.push(...(refill.blockers || []));
  const warnings = uniqueWarnings([
    ...(repo.warnings || []),
    ...(branch.warnings || []),
    ...(githubCli.warnings || []),
    ...(workspaceProtocol.warnings || []),
    ...(dispatcher.warnings || []),
    ...(tmux.warnings || []),
    ...(usage.warnings || []),
    ...(resource.warnings || []),
    ...(workers.warnings || []),
    ...(refill.warnings || []),
  ]);
  const nextActions = uniqueActions([
    ...(blockerList.length > 0
      ? blockerList.map((blocker) => ({
          code: blocker.code ? `${blocker.code}-preflight-action` : "preflight-blocker-action",
          summary: blocker.message || "Preflight blocker.",
          nextAction: blocker.nextAction || "Resolve preflight blocker before manager mutation.",
        }))
      : []),
    ...(dispatcher.nextActions || []),
    ...(refill.nextActions || []),
    ...(usage.nextActions || []),
  ]);
  const recommendedNextAction = nextActions[0]?.nextAction || (blockerList.length > 0 ? "Resolve preflight blockers before manager mutation." : "Preflight ready; continue with bounded manager cycle.");
  return packet({
    ok: blockerList.length === 0,
    status: blockerList.length > 0 ? "blocked" : "ready",
    summary: {
      repoRoot,
      repo,
      branch,
      githubCli,
      workspaceProtocol,
      workspace: {
        ok: workspace.ok,
        stateRoot: workspace.state.root,
        proof: workspace.proof || null,
      },
      tmux: tmux.summary,
      usage: usage.summary,
      resources: resource.summary,
      runway: refill.summary,
      dispatcher,
      workers: workers.summary.workerCounts,
      cleanup: cleanup.summary,
      ledger: {
        status: ledger.status,
        root: ledger.summary.root,
        files: ledger.summary.files,
        schemaGapCount: ledger.summary.schemaGaps.length,
        dispatcherSummary: summarizeLedgerDispatcherSummary(ledger.summary.dispatcherSummary),
      },
      recommendedNextAction,
      mutation: "none; read-only preflight summary",
      rawPayloadRetained: false,
    },
    blockers: blockerList,
    warnings,
    nextActions,
  });
}

function buildRepoPreflightStatus(context = {}) {
  const result = runReadOnlyTool(context.gitRunner || spawnSync, "git", ["rev-parse", "--show-toplevel"], context);
  if (!result.ok) {
    return {
      status: "warning",
      root: repoRoot,
      mutation: "none; git metadata only",
      warnings: [{ code: "preflight-repo-root-unavailable", message: result.error || "Unable to read git repository root." }],
    };
  }
  return {
    status: "ready",
    root: sanitizeLedgerField(result.stdout || repoRoot, repoRoot, 240),
    mutation: "none; git metadata only",
    warnings: [],
  };
}

function buildBranchPreflightStatus(context = {}) {
  const runner = context.gitRunner || spawnSync;
  const branch = runReadOnlyTool(runner, "git", ["rev-parse", "--abbrev-ref", "HEAD"], context);
  const head = runReadOnlyTool(runner, "git", ["rev-parse", "HEAD"], context);
  const status = runReadOnlyTool(runner, "git", ["status", "--short", "--branch"], context);
  const statusLines = String(status.stdout || "").split(/\r?\n/).filter(Boolean);
  const branchLine = statusLines.find((line) => line.startsWith("##")) || "";
  const dirtyLines = statusLines.filter((line) => !line.startsWith("##"));
  const warnings = [];
  for (const [code, result] of [
    ["preflight-branch-name-unavailable", branch],
    ["preflight-head-sha-unavailable", head],
    ["preflight-git-status-unavailable", status],
  ]) {
    if (!result.ok) warnings.push({ code, message: result.error || "Unable to read git branch metadata." });
  }
  return {
    status: warnings.length > 0 ? "warning" : "ready",
    current: sanitizeLedgerField(branch.stdout || "unknown", "unknown", 120),
    headSha: sanitizeLedgerField(head.stdout || "", "", 80),
    upstream: sanitizeLedgerField(branchLine.includes("...") ? branchLine.split("...")[1]?.split(" ")[0] || "" : "", "", 120),
    dirty: dirtyLines.length > 0,
    dirtyFileCount: dirtyLines.length,
    mutation: "none; git metadata only",
    warnings,
  };
}

function buildGithubCliPreflightStatus(context = {}) {
  const result = runReadOnlyTool(context.ghRunner || spawnSync, "gh", ["--version"], context);
  if (!result.ok) {
    return {
      status: "warning",
      available: false,
      version: "",
      mutation: "none; gh availability check only",
      warnings: [{ code: "preflight-github-cli-unavailable", message: result.error || "GitHub CLI is unavailable." }],
    };
  }
  return {
    status: "ready",
    available: true,
    version: sanitizeLedgerField(String(result.stdout || "").split(/\r?\n/)[0] || "gh available", "gh available", 120),
    mutation: "none; gh availability check only",
    warnings: [],
  };
}

function buildWorkspaceProtocolPreflightStatus(workspace = {}) {
  const warnings = workspace.ok ? [] : [{ code: "preflight-workspace-state-unsafe", message: workspace.error || "Workspace state root is unsafe." }];
  return {
    status: workspace.ok ? "ready" : "blocked",
    protocol: "codex-workspace-state",
    stateRoot: workspace.state?.root || "",
    storageProof: workspace.proof || null,
    mutation: "none; workspace protocol proof only",
    warnings,
  };
}

function buildDispatcherPreflightStatus(dispatchPreview = {}, ledger = {}) {
  const summary = dispatchPreview.summary || dispatchPreview;
  const counts = summary.counts || {};
  const dispatch = summary.dispatch || {};
  const ledgerDispatcher = ledger.summary?.dispatcherSummary || {};
  const dispatchBlockers = [
    ...(Array.isArray(dispatch.blockers) ? dispatch.blockers : []),
    ...(Array.isArray(summary.blockers) ? summary.blockers : []),
    ...(Array.isArray(dispatchPreview.blockers) ? dispatchPreview.blockers : []),
  ];
  const allowed = dispatch.allowed ?? summary.allowed ?? dispatchPreview.allowed;
  const candidateStateCounts = summary.candidateStateCounts || summary.candidate_state_counts || {};
  const dispatchableLanes = Number(counts.dispatchable ?? summary.dispatchableLanes ?? 0) || 0;
  const activeLanes = Number(counts.active ?? candidateStateCounts.active ?? summary.activeLanes ?? 0) || 0;
  const noNewDispatchButActive =
    activeLanes > 0 &&
    dispatchBlockers.length > 0 &&
    dispatchBlockers.every((blocker) => isNoDispatchableLaneBlocker(blocker));
  const effectiveDispatchBlockers = noNewDispatchButActive ? [] : dispatchBlockers;
  const previewHasDispatcherTruth = Boolean(
    isPlainObject(summary) &&
    (
      Object.keys(counts).length > 0 ||
      isPlainObject(candidateStateCounts) ||
      isPlainObject(dispatch) ||
      summary.generatedAt ||
      dispatch.generatedAt
    )
  );
  const dispatcherSummaryUnavailable =
    !isPlainObject(ledgerDispatcher) ||
    ledgerDispatcher.stateSource === "dispatcher_summary_unavailable" ||
    ["unknown", "stale"].includes(String(ledgerDispatcher.freshness || "").toLowerCase());
  const placeholderSummaryUnavailable =
    dispatcherSummaryUnavailable &&
    (!isPlainObject(ledgerDispatcher) || ledgerDispatcher.stateSource === "dispatcher_summary_unavailable" || String(ledgerDispatcher.freshness || "").toLowerCase() === "unknown");
  const previewBacked = placeholderSummaryUnavailable && previewHasDispatcherTruth && effectiveDispatchBlockers.length === 0;
  const status = effectiveDispatchBlockers.length > 0 || (allowed === false && effectiveDispatchBlockers.length > 0) ? "blocked" : dispatcherSummaryUnavailable && !previewBacked ? "blocked" : dispatchableLanes > 0 || activeLanes > 0 ? "ready" : "ready";
  const warnings = dispatcherSummaryUnavailable && !previewBacked
    ? [{ code: "preflight-dispatcher-summary-unknown", message: "Dispatcher summary is unavailable or stale; refresh dispatcher state before inferring active work." }]
    : [];
  const nextActions = dispatcherSummaryUnavailable && !previewBacked
    ? [{ code: "preflight-dispatcher-summary-refresh", summary: "Refresh dispatcher summary before manager mutation.", nextAction: "Run manager assignment/dispatch summary refresh before inferring active work." }]
    : [];
  const blockers = effectiveDispatchBlockers.map((blocker) => sanitizeLedgerField(blocker?.message || blocker, "dispatcher blocker", 180));
  if (dispatcherSummaryUnavailable && !previewBacked) {
    blockers.push("Dispatcher summary is unavailable or stale; refresh dispatcher state before manager mutation.");
  }
  return {
    status,
    dispatchableLanes,
    activeLanes,
    blockedLanes: Number(counts.blocked ?? 0) || 0,
    dispatcherSummaryState: sanitizeLedgerField(previewBacked ? "dispatch_preview_live" : ledgerDispatcher.stateSource || "dispatcher_summary_unavailable", "dispatcher_summary_unavailable", 80),
    freshness: sanitizeLedgerField(previewBacked ? "fresh" : ledgerDispatcher.freshness || "unknown", "unknown", 40),
    blockers,
    mutation: "none; dispatcher readiness summary only",
    warnings,
    nextActions,
  };
}

function isNoDispatchableLaneBlocker(blocker = "") {
  const text = String(blocker?.message || blocker?.code || blocker || "").toLowerCase();
  return /no dispatchable|no .*safe backlog|no .*ready.*preview|no generated lane/.test(text);
}

function buildRecoveryNotRequestedPlan(options = {}, context = {}) {
  const runId = safeRunId(options.runId || context.runId || defaultRunId());
  return packet({
    status: "ready",
    summary: {
      runId,
      reconciliation: {
        status: "ready",
        action: "not_requested",
        recoveryStatus: "not_requested",
        latestSafeCheckpoint: null,
        nextAction: "continue_current_cycle",
        operatorAttentionRequired: false,
        recoveryAttemptCount: 0,
        lastRecoveryAt: null,
        evidenceFreshness: {},
        surfaces: {},
        disagreements: [],
        missingEvidence: [],
        policy: "reconcile_when_evidence_or_recovery_signal_exists",
        rawPayloadRetained: false,
      },
      autoRepair: {
        posture: "not_requested",
        action: "none",
        rawPayloadRetained: false,
      },
      retryRoutes: [],
      mutationMode: "none_recovery_not_requested",
      rawPayloadRetained: false,
    },
    blockers: [],
    warnings: [],
    nextActions: [],
  });
}

const PIPELINE_OPERATIONAL_ACTION_SCHEMA_VERSION = "pipeline-operational-action/v0";
const PIPELINE_OPERATIONAL_RUNTIME_READINESS_SCHEMA_VERSION = "pipeline-operational-runtime-readiness/v0";
const OPERATIONAL_ACTION_READINESS_TTL_MS = 5 * 60 * 1000;
const OPERATIONAL_ACTION_READINESS_ALLOWED_FUTURE_SKEW_MS = 60 * 1000;
const PIPELINE_OPERATIONAL_ACTION_IDS = [
  "inspect",
  "refresh_projection",
  "dispatch_apply",
  "mark_viewed",
  "retry_verification",
  "requeue",
  "mark_tested",
  "kill_worker",
  "mutate_source",
  "push_branch",
  "open_pr",
  "merge",
  "delete_branch",
  "cleanup",
  "credential_or_provider_change",
];
const FORBIDDEN_OPERATIONAL_ACTION_METADATA =
  /\b(?:raw[\s_-]*(?:prompts?|completions?|transcripts?|logs?|sources?)|reasoning[\s_-]*traces?|provider[\s_-]*payloads?|source[\s_-]*(?:dumps?|copies?|snapshots?)|stack[\s_-]*dumps?|console[\s_-]*logs?|secrets?(?:[\s_-]*(?:key|token|value|id))?|credentials?(?:[\s_-]*(?:key|token|value|id))?|passwords?|api[\s_-]*keys?|access[\s_-]*tokens?|auth[\s_-]*tokens?|private[\s_-]*keys?|passphrases?|(?:terminal|tmux|pane)[\s_-]*(?:scrollbacks?|texts?|outputs?|stdouts?|stderrs?))\b/i;
const SECRET_LIKE_OPERATIONAL_ACTION_REF =
  /\b(?:sk-[A-Za-z0-9_-]{8,}|(?:ghp|gho|ghu|ghs|ghr)_[A-Za-z0-9_]{20,}|github_pat_[A-Za-z0-9_]{20,}|xox[baprs]-[A-Za-z0-9-]{10,}|eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}|(?:api|secret|token|credential)[_-]?(?:key|token|secret)?[:=])/i;
const OPERATIONAL_ACTION_EVIDENCE_REF =
  /^(?:manager-cycle|preflight|usage|resources|operational-action|verification|evidence|story|assignment|task|source|prd|check|checkpoint|command|test|artifact):[A-Za-z0-9._/@:-]{1,160}$/;
const OPERATIONAL_ACTION_IDENTIFIER =
  /^[a-z0-9](?:[a-z0-9._/@:,-]{0,198}[a-z0-9])?$/;
const OPERATIONAL_ACTION_IDENTIFIER_REPEATED_SEPARATOR = /[._/@:,-]{2,}/;
const OPERATIONAL_ACTION_IDENTIFIER_PATH_SEGMENT = /(?:^|[/\\])\.{1,2}(?:[/\\]|$)/;
const TRUSTED_OPERATIONAL_READINESS = Symbol("trustedOperationalReadiness");
const TRUSTED_DISPATCH_PREVIEW_AUTHORITY = Symbol("trustedDispatchPreviewAuthority");
const TRUSTED_DISPATCH_PREVIEW_AUTHORITY_RECORDS = new WeakSet();

function buildOperationalActionReadinessProjection({ runOptions = {}, usage = {}, resources = {}, preflight = {}, workers = {}, delivery = {}, cleanup = {}, context = {} } = {}) {
  const safeRunOptions = safePlainObjectSnapshot(runOptions) || {};
  const safeContext = safePlainObjectSnapshot(context) || {};
  const safeUsage = safeProjectionPacket(usage);
  const safeResources = safeProjectionPacket(resources);
  const safePreflight = safeProjectionPacket(preflight);
  const safeWorkers = safeProjectionPacket(workers);
  const safeDelivery = safeProjectionPacket(delivery);
  const safeCleanup = safeProjectionPacket(cleanup);
  const contextNow = safeReadProperty(safeContext, "now", undefined);
  const runOptionsNow = safeReadProperty(safeRunOptions, "now", undefined);
  const suppliedCheckedAt = contextNow !== undefined || runOptionsNow !== undefined;
  const requestedCheckedAtInput = operationalTimestampInput(contextNow ?? runOptionsNow ?? new Date().toISOString(), new Date().toISOString());
  const requestedCheckedAt = requestedCheckedAtInput.value;
  const requestedCheckedAtMs = Date.parse(requestedCheckedAt);
  const nowMs = Date.now();
  const requestedTimestampUnparseable = suppliedCheckedAt && (!requestedCheckedAtInput.readable || !Number.isFinite(requestedCheckedAtMs));
  const requestedTimestampStale = Number.isFinite(requestedCheckedAtMs) && requestedCheckedAtMs + OPERATIONAL_ACTION_READINESS_TTL_MS <= nowMs;
  const requestedTimestampFuture = Number.isFinite(requestedCheckedAtMs) && requestedCheckedAtMs > nowMs + OPERATIONAL_ACTION_READINESS_ALLOWED_FUTURE_SKEW_MS;
  const requestedTimestampInvalid = requestedTimestampUnparseable || requestedTimestampStale || requestedTimestampFuture;
  const checkedAtMs = requestedTimestampUnparseable
    ? nowMs - OPERATIONAL_ACTION_READINESS_TTL_MS - 1
    : Number.isFinite(requestedCheckedAtMs)
      ? requestedCheckedAtMs
      : nowMs;
  const checkedAt = new Date(checkedAtMs).toISOString();
  const expiresAt = new Date(checkedAtMs + OPERATIONAL_ACTION_READINESS_TTL_MS).toISOString();
  const evidenceRefs = [
    `manager-cycle:${operationalActionEvidenceToken(safeReadProperty(safeRunOptions, "runId", "unknown"), "unknown", 100)}`,
    `preflight:${operationalActionEvidenceToken(safeReadProperty(safePreflight, "status", "unknown"), "unknown", 40)}`,
    `usage:${operationalActionEvidenceToken(safeReadProperty(safeUsage, "status", "unknown"), "unknown", 40)}`,
    `resources:${operationalActionEvidenceToken(safeReadProperty(safeResources, "status", "unknown"), "unknown", 40)}`,
  ];
  const actionEvidence = (actionId) => [`operational-action:${actionId}`, ...evidenceRefs];
  const preflightStatus = safeReadProperty(safePreflight, "status", "unknown");
  const usageStatus = safeString(safeReadProperty(safeUsage, "status", ""), "");
  const resourceStatus = safeString(safeReadProperty(safeResources, "status", ""), "");
  const preflightReady = preflightStatus === "ready" && !hasOperationalActionReadinessBlockers(safePreflight);
  const usageReady = ["normal", "ready"].includes(usageStatus) && !hasOperationalActionReadinessBlockers(safeUsage);
  const resourceReady = ["normal", "ready"].includes(resourceStatus) && !hasOperationalActionReadinessBlockers(safeResources);
  const readOnlyReady = preflightReady && usageReady && resourceReady && !requestedTimestampInvalid;
  const workerReady = safeReadProperty(safeWorkers, "status", "unknown") === "ready" && !hasOperationalActionReadinessBlockers(safeWorkers);
  const deliveryReady = safeReadProperty(safeDelivery, "status", "unknown") === "ready" && !hasOperationalActionReadinessBlockers(safeDelivery);
  const cleanupReady = safeReadProperty(safeCleanup, "status", "unknown") === "ready" && !hasOperationalActionReadinessBlockers(safeCleanup);
  const workerMutationGate = workerReady && readOnlyReady ? "needs_authority_approval" : "blocked";
  const deliveryGate = deliveryReady && readOnlyReady ? "needs_authority_approval" : "blocked";
  const cleanupGate = cleanupReady && readOnlyReady ? "needs_safety_approval" : "blocked";
  const mergeGate = deliveryReady && readOnlyReady ? "needs_safety_approval" : "blocked";
  const typedReason = readOnlyReady ? null : requestedTimestampInvalid ? "projection_stale" : "runtime_unavailable";
  const refreshProjectionTypedReason = readOnlyReady ? null : requestedTimestampInvalid ? "projection_stale" : "runtime_unavailable";

  return {
    schemaVersion: PIPELINE_OPERATIONAL_RUNTIME_READINESS_SCHEMA_VERSION,
    actionSchemaVersion: PIPELINE_OPERATIONAL_ACTION_SCHEMA_VERSION,
    readinessState: readOnlyReady ? "ready" : "degraded",
    operationalMode: "read_only",
    freshnessState: requestedTimestampInvalid ? "stale" : "live",
    capabilityState: readOnlyReady ? "available" : "gated",
    typedReason,
    checkedAt,
    expiresAt,
    summary: readOnlyReady
      ? "Read-only operational action capability projection is available for manager-cycle dogfooding."
      : requestedTimestampInvalid
        ? "Operational action projection is degraded because supplied cycle time was outside the freshness window; action execution remains gated."
        : "Operational action projection is degraded; action execution remains gated by existing manager-control-plane blockers.",
    actionCapabilities: [
      operationalActionCapability("inspect", "manager_run", "available", "allowed", "low", null, "Inspect compact manager cycle state without mutation.", actionEvidence("inspect")),
      operationalActionCapability("refresh_projection", "projection", readOnlyReady ? "available" : "gated", readOnlyReady ? "allowed" : "blocked", "low", refreshProjectionTypedReason, "Refresh compact read-only manager projection evidence.", actionEvidence("refresh_projection")),
      operationalActionCapability("dispatch_apply", "work_item", "gated", "needs_authority_approval", "high", "blocked_by_approval", "Apply dispatch decisions only through explicit manager-control-plane authority gates.", actionEvidence("dispatch_apply")),
      operationalActionCapability("mark_viewed", "work_packet", "simulated", "needs_product_approval", "low", "blocked_by_approval", "Record viewed state only after backend ownership exists.", actionEvidence("mark_viewed")),
      operationalActionCapability("retry_verification", "execution_attempt", "gated", "needs_authority_approval", "medium", "blocked_by_approval", "Retry verification only through explicit authority and evidence gates.", actionEvidence("retry_verification")),
      operationalActionCapability("requeue", "work_item", "gated", "needs_authority_approval", "medium", "blocked_by_approval", "Requeue only through manager-control-plane authority gates.", actionEvidence("requeue")),
      operationalActionCapability("mark_tested", "work_packet", "gated", "needs_product_approval", "medium", "blocked_by_approval", "Mark tested only through operator test result evidence.", actionEvidence("mark_tested")),
      operationalActionCapability("kill_worker", "worker", "gated", workerMutationGate, "high", workerMutationGate === "blocked" ? "runtime_unavailable" : "blocked_by_approval", "Worker termination remains blocked without explicit safety evidence.", actionEvidence("kill_worker")),
      operationalActionCapability("mutate_source", "work_packet", "gated", "needs_authority_approval", "high", "blocked_by_policy", "Source mutation is not available from the continuous cycle projection.", actionEvidence("mutate_source")),
      operationalActionCapability("push_branch", "branch", "gated", deliveryGate, "high", deliveryGate === "blocked" ? "delivery_blocked" : "blocked_by_approval", "Branch push remains behind delivery gates.", actionEvidence("push_branch")),
      operationalActionCapability("open_pr", "branch", "gated", deliveryGate, "high", deliveryGate === "blocked" ? "delivery_blocked" : "blocked_by_approval", "PR creation remains behind delivery gates.", actionEvidence("open_pr")),
      operationalActionCapability("merge", "branch", "gated", mergeGate, "extreme", mergeGate === "blocked" ? "delivery_blocked" : "blocked_by_approval", "Merge requires exact-head delivery evidence and is not continuous-cycle executable.", actionEvidence("merge")),
      operationalActionCapability("delete_branch", "branch", "gated", cleanupGate, "extreme", cleanupGate === "blocked" ? "blocked_by_policy" : "blocked_by_approval", "Branch deletion remains behind cleanup gates.", actionEvidence("delete_branch")),
      operationalActionCapability("cleanup", "workspace", "gated", cleanupGate, "extreme", cleanupGate === "blocked" ? "blocked_by_policy" : "blocked_by_approval", "Cleanup remains behind merged-lane cleanup evidence.", actionEvidence("cleanup")),
      operationalActionCapability("credential_or_provider_change", "runtime", "unavailable", "blocked", "extreme", "blocked_by_policy", "Provider account changes are outside continuous manager authority.", actionEvidence("credential_or_provider_change")),
    ],
    evidenceRefs,
    metadataOnly: true,
    rawPayloadRetained: false,
  };
}

function operationalTimestampInput(value, fallback) {
  try {
    const text = String(value ?? fallback ?? "");
    return { readable: true, value: sanitizeLedgerField(text, fallback, 80) };
  } catch {
    return { readable: false, value: fallback };
  }
}

function hasOperationalActionReadinessBlockers(packet = {}) {
  const safePacket = safeProjectionPacket(packet);
  const summary = safePlainObjectSnapshot(safeReadProperty(safePacket, "summary", {})) || {};
  if (safeReadProperty(safePacket, "ok", true) === false || safeReadProperty(summary, "ok", true) === false) return true;
  const blockers = operationalArrayEvidence(safePacket, "blockers");
  const summaryBlockers = operationalArrayEvidence(summary, "blockers");
  if (!blockers.readable || !summaryBlockers.readable) return true;
  if (blockers.values.length > 0) return true;
  if (summaryBlockers.values.length > 0) return true;
  const packetWarnings = operationalArrayEvidence(safePacket, "warnings");
  const summaryWarnings = operationalArrayEvidence(summary, "warnings");
  if (!packetWarnings.readable || !summaryWarnings.readable) return true;
  const warnings = [...packetWarnings.values, ...summaryWarnings.values];
  return warnings.some((warning) => {
    if (typeof warning === "string") {
      return /^(?:critical|error|fatal)(?::|\b)/i.test(warning.trim());
    }
    if (!warning || typeof warning !== "object") return false;
    const warningRecord = safePlainObjectSnapshot(warning) || {};
    const severity = safeString(safeReadProperty(warningRecord, "severity", ""), "").toLowerCase();
    const level = safeString(safeReadProperty(warningRecord, "level", ""), "").toLowerCase();
    const state = safeString(safeReadProperty(warningRecord, "state", ""), "").toLowerCase();
    const status = safeString(safeReadProperty(warningRecord, "status", ""), "").toLowerCase();
    return (
      ["critical", "error", "fatal"].includes(severity) ||
      ["critical", "error", "fatal"].includes(level) ||
      ["blocked", "failed", "unavailable", "critical"].includes(state) ||
      ["blocked", "failed", "unavailable", "critical"].includes(status)
    );
  });
}

function operationalArrayEvidence(record = {}, key = "") {
  try {
    if (!record || typeof record !== "object") return { readable: true, values: [] };
    if (!Object.prototype.hasOwnProperty.call(record, key)) return { readable: true, values: [] };
    const value = record[key];
    if (value === undefined || value === null) return { readable: true, values: [] };
    if (!Array.isArray(value)) return { readable: false, values: [] };
    return { readable: true, values: Array.from(value) };
  } catch {
    return { readable: false, values: [] };
  }
}

function operationalActionCapability(actionId, targetType, capabilityState, authorityState, riskTier, typedReason, expectedResultSummary, evidenceRefs) {
  return {
    actionId,
    targetType,
    targetId: null,
    capabilityState,
    authorityState,
    riskTier,
    typedReason,
    expectedResultSummary,
    correlationRequired: true,
    idempotencyRequired: true,
    evidenceRefs,
    metadataOnly: true,
    rawPayloadRetained: false,
  };
}

function operationalActionEvidenceToken(value, fallback = "unknown", maxLength = 100) {
  const sanitized = sanitizeLedgerField(value, fallback, maxLength);
  const rawValue = safeString(value, "");
  if (
    FORBIDDEN_OPERATIONAL_ACTION_METADATA.test(rawValue) ||
    SECRET_LIKE_OPERATIONAL_ACTION_REF.test(rawValue) ||
    FORBIDDEN_OPERATIONAL_ACTION_METADATA.test(sanitized) ||
    SECRET_LIKE_OPERATIONAL_ACTION_REF.test(sanitized)
  ) {
    return fallback;
  }
  const normalized = sanitized
    .replace(/[^A-Za-z0-9._/@:-]+/g, "-")
    .replace(/-{2,}/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, maxLength);
  return normalized || fallback;
}

function safeProjectionPacket(value) {
  return safePlainObjectSnapshot(value) || {};
}

function summarizeLedgerDispatcherSummary(summary = null) {
  if (!isPlainObject(summary)) return null;
  return {
    stateSource: sanitizeLedgerField(summary.stateSource || "dispatcher_summary_unavailable", "dispatcher_summary_unavailable", 80),
    freshness: sanitizeLedgerField(summary.freshness || "unknown", "unknown", 40),
    currentPhase: sanitizeLedgerField(summary.currentPhase || "unknown", "unknown", 80),
    updatedAt: sanitizeLedgerField(summary.updatedAt || "", "", 80),
    nextAction: sanitizeLedgerField(summary.nextAction || "", "", 180),
    queuedCount: nonNegativeInteger(summary.queuedCount ?? summary.queued ?? summary.counts?.queued),
    activeCount: nonNegativeInteger(summary.activeCount ?? summary.active ?? summary.counts?.active),
    blockedCount: nonNegativeInteger(summary.blockedCount ?? summary.blocked ?? summary.counts?.blocked),
    failedCount: nonNegativeInteger(summary.failedCount ?? summary.failed ?? summary.counts?.failed),
    rawPayloadRetained: false,
  };
}

function runReadOnlyTool(runner, command, args, context = {}) {
  try {
    const result = runner(command, args, { cwd: repoRoot, encoding: "utf8", stdio: "pipe", timeout: context.timeoutMs || 5000 });
    if (!result || typeof result !== "object" || typeof result.status !== "number") {
      return { ok: false, stdout: "", stderr: "", error: `${command} returned malformed result` };
    }
    const status = Number(result.status);
    const stdout = String(result?.stdout || "").trim();
    const stderr = String(result?.stderr || "").trim();
    if (result?.error) return { ok: false, stdout, stderr, error: result.error.message || `${command} unavailable` };
    if (status !== 0) return { ok: false, stdout, stderr, error: stderr || stdout || `${command} exited ${status}` };
    return { ok: true, stdout, stderr };
  } catch (error) {
    return { ok: false, stdout: "", stderr: "", error: error instanceof Error ? error.message : String(error) };
  }
}

export function buildCyclePacket(options = {}, context = {}) {
  options = safePlainObjectSnapshot(options) || {};
  context = safePlainObjectSnapshot(context) || {};
  const runOptions = { ...options, runId: resolveManagerRunId(options, context) };
  const readOnlyRunOptions = { ...runOptions, apply: false };
  const usageContext = safePlainObjectSnapshot(safeReadProperty(context, "usageContext", {})) || {};
  const resourceContext = safePlainObjectSnapshot(safeReadProperty(context, "resourceContext", {})) || {};
  const preflightStatus = safeReadProperty(context, "preflightStatus", null);
  const workerStatus = safeReadProperty(context, "workerStatus", null);
  const dispatchPreviewContext = safeReadProperty(context, "dispatchPreview", null);
  const usageInput = {
    ...usageContext,
    weeklyUsage: safeReadProperty(usageContext, "weeklyUsage", undefined) ?? safeReadProperty(context, "weeklyUsage", undefined),
    weeklyUsageContext: safeReadProperty(usageContext, "weeklyUsageContext", undefined) ?? safeReadProperty(context, "weeklyUsageContext", undefined),
    weeklyUsagePressure: safeReadProperty(usageContext, "weeklyUsagePressure", undefined) ?? safeReadProperty(context, "weeklyUsagePressure", undefined),
  };
  const usage = usageInput && (safeReadProperty(usageInput, "status", null) || safeReadProperty(usageInput, "state", null))
    ? normalizeUsagePacketContext(usageInput, context)
    : buildUsageStatus(usageInput);
  const resources = resourceContext && (safeReadProperty(resourceContext, "status", null) || safeReadProperty(resourceContext, "state", null)) ? normalizePacketContext(resourceContext) : buildResourceStatus(resourceContext || {});
  const preflight = preflightStatus ? normalizePacketContext(preflightStatus) : buildPreflight(readOnlyRunOptions, context);
  const dispatchPreview = dispatchPreviewContext ? normalizeDispatchPreviewContext(dispatchPreviewContext) : buildDispatchPreview(readOnlyRunOptions, context);
  const runway = buildRefillPlan(readOnlyRunOptions, { ...context, dispatchPreview, discoverDefaultSources: true });
  const workers = workerStatus ? normalizePacketContext(workerStatus) : buildWorkerStatus(readOnlyRunOptions, { ...context, usageContext: usage, resourceContext: resources, dispatchPreview, refillPlan: context.refillPlan || runway });
  const workerHandoff = buildWorkerHandoffPlan(readOnlyRunOptions, {
    ...context,
    workerStatus: workers,
    assignmentSummary: context.assignmentSummary,
  });
  const workerProgress = context.workerProgressStatus || buildWorkerProgressStatus(readOnlyRunOptions, {
    ...context,
    workerStatus: workers,
    assignmentSummary: context.assignmentSummary,
  });
  const laneAdvance = context.laneAdvanceStatus || buildLaneAdvancementPlan(readOnlyRunOptions, {
    ...context,
    workerStatus: workers,
    assignmentSummary: context.assignmentSummary,
    checkpoints: context.checkpoints || undefined,
  });
  const friction = buildWorkerFrictionPlan(readOnlyRunOptions, {
    questions: context.workerQuestions || context.questions || [],
    failureSignals: context.failureSignals || [],
    safeWorkers: context.safeWorkers || context.unrelatedWork || context.safeWork,
    taskRisk: context.taskRisk || {},
    usageState: usage.status,
  });
  const steering = buildSteeringPlan(readOnlyRunOptions, context);
  const cleanup = context.cleanupPlan || buildCleanupPlan(readOnlyRunOptions, context);
  const resume = context.resumeState ? normalizePacketContext(context.resumeState) : buildResumeState(readOnlyRunOptions, context);
  const hasRecoverySignals = Boolean(context.stateSignals || context.reconciliationStateSignals);
  const recovery = context.recoveryPlan
    ? normalizePacketContext(context.recoveryPlan)
    : hasRecoverySignals
      ? buildRecoveryPlan(readOnlyRunOptions, { ...context, stateSignals: context.reconciliationStateSignals || context.stateSignals })
      : buildRecoveryNotRequestedPlan(readOnlyRunOptions, context);
  const workspace = getWorkspaceProof(readOnlyRunOptions, context);
  const persistedCapabilityPosture = context.persistedManagerCapabilityPosture
    ? packet({ status: "ready", summary: { managerCapabilityPosture: context.persistedManagerCapabilityPosture } })
    : readManagerCapabilityPosture(readOnlyRunOptions, context);
  const managerCapabilityPosture = buildManagerCapabilityPosture(
    readOnlyRunOptions,
    {
      ...context,
      persistedManagerCapabilityPosture: persistedCapabilityPosture.summary?.managerCapabilityPosture || null,
    },
    {},
  );
  const managerCapabilityStatus = normalizeHeartbeatCapabilityPosture(managerCapabilityPosture.summary);
  const selfRepair = buildManagerSelfRepairSummary(readOnlyRunOptions, context);
  const feedback = buildFeedbackPlan(readOnlyRunOptions, context);
  const delivery = context.deliveryPlan ? normalizePacketContext(context.deliveryPlan) : buildDeliveryPlan(readOnlyRunOptions, { ...context, feedbackPlan: feedback });
  const operationalActions = buildOperationalActionReadinessProjection({
    runOptions: readOnlyRunOptions,
    usage,
    resources,
    preflight,
    workers,
    delivery,
    cleanup,
    context,
  });
  const dispatcherState = buildCycleDispatcherState(dispatchPreview);
  const dispatchTrustProof = bindTrustedOperationalDispatchAuthority(operationalActions, dispatchPreview);
  markTrustedOperationalReadiness(operationalActions, { dispatchApply: dispatchTrustProof });
  const summaryOperationalActions = sanitizeCyclePacketValue(operationalActions);
  markTrustedOperationalReadiness(summaryOperationalActions, { dispatchApply: dispatchTrustProof });
  const queueLeaseSummary = buildCycleQueueLeaseSummary(dispatcherState);
  const signalGaps = buildCycleSignalGaps({ usage, resources, dispatchPreview, workers, cleanup, preflight, context });
  const observations = buildCycleObservations({ dispatchPreview, workers, context });
  const frictionAttention = friction.status === "attention";
  const workerQuestionBlockers = workerQuestionOperatorBlockers(friction.summary?.questionHandling || []);
  const workerQuestionBlockerActions = workerQuestionBlockers.map((blocker) => ({
    code: "worker-question-operator-interruption",
    summary: blocker.message,
    nextAction: blocker.nextAction,
  }));
  const steeringAttention = steering.status === "attention";
  const feedbackAttention = feedback.status === "attention";
  const workerProgressAttention = workerProgress.status === "attention";
  const laneAdvanceAttention = laneAdvance.status === "attention";
  const activeWorkerCount = Number(workers.summary?.workerCounts?.active || 0);
  const preflightBlockers = preflight.blockers || [];
  const blockers = [];
  if (!workspace.ok) {
    blockers.push({ code: "workspace-state-unsafe", message: workspace.error, nextAction: "Choose a safe workspace state root." });
  }
  if (preflightBlockers.length > 0 && !frictionAttention && !workerProgressAttention && !laneAdvanceAttention && activeWorkerCount === 0) {
    blockers.push(...preflightBlockers);
  }
  blockers.push(...safeBlockerArray(signalGaps.blockers, "signal-gap-blocker-unreadable"));
  blockers.push(...safeBlockerArray(usage.blockers, "usage-blockers-unreadable"));
  blockers.push(...safeBlockerArray(resume.blockers, "resume-blockers-unreadable"));
  blockers.push(...safeBlockerArray(recovery.blockers, "recovery-blockers-unreadable"));
  blockers.push(...safeBlockerArray(runway.blockers, "runway-blockers-unreadable"));
  blockers.push(...safeBlockerArray(workers.blockers, "worker-blockers-unreadable"));
  const dispatchPosture = applySteeringToDispatchPosture(buildDispatchPosture(usage.status, resources.status, usage.summary?.weekly), steering.summary);
  const dispatchPostureAllowsNewDispatch = dispatchPosture.summary?.newDispatchAllowed !== false;
  blockers.push(...dispatchPosture.blockers);
  blockers.push(...workerQuestionBlockers);
  blockers.push(...(steering.blockers || []));
  blockers.push(...(feedback.blockers || []));
  blockers.push(...(delivery.blockers || []));
  const baseStatus = blockers.length > 0 ? "blocked" : frictionAttention || steeringAttention || feedbackAttention || workerProgressAttention || laneAdvanceAttention ? "attention" : "ready";
  const continuation = buildContinuationPlan({ status: baseStatus, blockers, runway, usage, resources, workers, resume, dispatchPreview, operationalActions });
  const deliveryOrPrOperationBlocked = blockers.some((blocker) =>
    ["delivery-phase-authority-missing", "delivery-phase-authority-invalid", "pr-stewardship-evidence-missing", "pr-stewardship-high-risk"].includes(blocker.code),
  );
  const status = baseStatus === "blocked" && continuation.canContinue && !deliveryOrPrOperationBlocked ? "attention" : baseStatus;
  const reportedBlockers = suppressSupersededCycleBlockers({ blockers, cleanup });
  const recoveryMutationBlocked = recoveryBlocksManagerMutation(recovery);
  const autoApply = [
    classifyAutoApply("ledger.append", { resourceState: resources.status, usageState: usage.status, weeklyUsage: usage.summary?.weekly }),
    classifyAutoApply("dispatch.apply", { resourceState: resources.status, usageState: usage.status, weeklyUsage: usage.summary?.weekly }),
  ];
  const currentSource = runway.summary.sourceSlice?.label || "none";
  const blockerActions = blockers
    .map((blocker) => ({
      code: blocker.code ? `${blocker.code}-action` : "blocker-action",
      summary: blocker.message || "Manager is blocked.",
      nextAction: blocker.nextAction || "Inspect blocker evidence before resuming manager mutation.",
    }))
    .filter((action) => action.nextAction);
  const takeoverInspectionActions = takeoverInspectionNextActions(resume.summary.takeoverInspection);
  const workerWarmCommand = [
    "node ./scripts/manager-worker-warm.mjs",
    "--summary-json",
    "--run-id",
    shellSingleQuote(runOptions.runId),
    "--limit",
    String(continuation.startWarmCandidates),
    ...(runOptions.stateRoot ? ["--state-root", shellSingleQuote(runOptions.stateRoot)] : []),
  ].join(" ");
  const workerWarmActions =
    continuation.state === "worker_warm_ready"
      ? [
          {
            code: "manager-owned-worker-warm-ready",
            summary: `Warm ${continuation.startWarmCandidates} manager-owned worker(s) through existing gates.`,
            nextAction: workerWarmCommand,
          },
        ]
      : [];
  const workerHandoffActions = workerHandoff.status === "ready" ? (workerHandoff.nextActions || []).map((action) => ({
    ...action,
    code: action.code || "worker-handoff-action",
  })) : [];
  const activeWorkerActions =
    continuation.state === "active_worker_monitoring"
      ? [
          {
            code: "active-worker-monitoring",
            summary: `Monitor ${continuation.activeWorkers} active manager-owned worker(s); keep takeover and dispatch apply blocked.`,
            nextAction: "Poll manager-worker-progress and route only blockers, questions, checkpoints, stale progress signals, and risky decisions.",
          },
        ]
      : [];
  const workerProgressActions = (workerProgress.nextActions || []).map((action) => ({
    ...action,
    code: action.code || "worker-progress-action",
  }));
  const laneAdvanceActions = (laneAdvance.nextActions || []).map((action) => ({
    ...action,
    code: action.code || "manager-lane-advance-ready",
  }));
  const cleanupActions = (cleanup.nextActions || []).map((action) => ({
    ...action,
    code: action.code || "cleanup-action",
  }));
  const supersededActions = supersededCycleActionCodes({ cleanup });
  const dispatchApplyOperationallyAllowed = operationalActionCapabilityAllows(
    { summary: { operationalActions, dispatchPreview: dispatchPreview.summary, dispatcher: dispatcherState.dispatcher } },
    "dispatch_apply",
  );
  const dispatchPreviewActions = continuation.canContinue && dispatchApplyOperationallyAllowed ? (dispatchPreview.nextActions || []) : [];
  const nextActions = uniqueActions([
    ...(recoveryMutationBlocked ? [] : workerQuestionBlockerActions),
    ...(recoveryMutationBlocked ? [] : workerWarmActions),
    ...(recoveryMutationBlocked ? [] : workerHandoffActions),
    ...(recoveryMutationBlocked ? [] : laneAdvanceActions),
    ...(recoveryMutationBlocked ? [] : workerProgressActions),
    ...signalGaps.nextActions,
    ...(recoveryMutationBlocked ? [] : dispatchPostureAllowsNewDispatch ? dispatchPreviewActions : []),
    ...(recoveryMutationBlocked ? [] : runway.nextActions || []),
    ...activeWorkerActions,
    ...(usage.nextActions || []),
    ...(recoveryMutationBlocked ? [] : friction.nextActions || []),
    ...(recoveryMutationBlocked ? [] : steering.nextActions || []),
    ...(recoveryMutationBlocked ? [] : feedback.nextActions || []),
    ...(recoveryMutationBlocked ? [] : cleanupActions),
    ...takeoverInspectionActions,
    ...blockerActions,
  ].filter((action) => !supersededActions.has(action.code)));
  const sourceBackedRefillAction =
    !recoveryMutationBlocked && runway.summary.dispatchableLanes === 0 && runway.summary.sourceSlice ? runway.nextActions?.[0]?.nextAction : null;
  const safeDispatchAction = continuation.canContinue && !recoveryMutationBlocked && dispatchPostureAllowsNewDispatch && dispatchApplyOperationallyAllowed && dispatchPreview.summary?.allowed === true ? dispatchPreview.nextActions?.[0]?.nextAction : null;
  const activeWorkerAction = activeWorkerActions[0]?.nextAction || null;
  const workerWarmAction = recoveryMutationBlocked ? null : workerWarmActions[0]?.nextAction || null;
  const workerHandoffAction = recoveryMutationBlocked ? null : workerHandoffActions[0]?.nextAction || null;
  const laneAdvanceAction = recoveryMutationBlocked ? null : laneAdvanceActions[0]?.nextAction || null;
  const cleanupAction = recoveryMutationBlocked || !continuation.canContinue ? null : cleanupActions[0]?.nextAction || null;
  const actionNeeded =
    (recoveryMutationBlocked ? null : workerQuestionBlockerActions[0]?.nextAction) ||
    (recoveryMutationBlocked ? null : steering.blockers?.[0]?.nextAction) ||
    (recoveryMutationBlocked ? null : steering.nextActions?.[0]?.nextAction) ||
    (recoveryMutationBlocked ? null : feedback.nextActions?.[0]?.nextAction) ||
    workerWarmAction ||
    workerHandoffAction ||
    laneAdvanceAction ||
    (recoveryMutationBlocked ? null : workerProgress.nextActions?.[0]?.nextAction) ||
    (recoveryMutationBlocked ? null : friction.nextActions?.[0]?.nextAction) ||
    safeDispatchAction ||
    sourceBackedRefillAction ||
    activeWorkerAction ||
    cleanupAction ||
    takeoverInspectionActions[0]?.nextAction ||
    resume.blockers?.[0]?.nextAction ||
    runway.blockers?.[0]?.nextAction ||
    (recoveryMutationBlocked ? null : runway.nextActions?.[0]?.nextAction) ||
    (status === "blocked" ? "cycle blocked; inspect blockers before manager mutation." : null) ||
    "none";
  const progress = buildProgressBeaconPlan(runOptions, {
    runState: continuation.progressRunState,
    workerCounts: workers.summary?.workerCounts || {},
    usageState: usage.status,
    resourceState: resources.status,
    currentSource,
    operatorActionState: actionNeeded,
    queueLeaseSummary,
    sourceExhausted: context.sourceExhausted ?? context.source_exhausted ?? runway.summary?.sourceExhausted ?? runway.summary?.source_exhausted,
    cleanupState: context.cleanupState || context.cleanup_state || cleanup.summary?.state || cleanup.status,
    housekeepingCompleted: context.housekeepingCompleted ?? context.housekeeping_complete,
    nextProductDecision: context.nextProductDecision || context.next_product_decision || runway.summary?.nextProductDecision || continuation.nextProductDecision,
    openLanes: context.openLanes || context.open_lanes || cycleOpenLaneSummaries({ workers, dispatchPreview }),
    parkedLanes: context.parkedLanes || context.parked_lanes || cycleParkedLaneSummaries({ recovery }),
    checkpoints: context.checkpoints || [],
    checkpointCandidates: context.checkpointCandidates || [],
    activeLaneEvidence: context.activeLaneEvidence || context.active_lane_evidence || runway.summary.activeLaneEvidence,
    managerCapabilityPosture: managerCapabilityPosture.summary,
    workContinues: continuation.canContinue,
    nextSource: currentSource,
  });
  const report = progress.summary.heartbeat.text;
  const preflightSummary = preflight.summary || {};
  const cycleRecommendedActions = sanitizeCycleActions(nextActions);
  const cyclePacket = packet({
    ok: status !== "blocked",
    status,
    summary: {
      run: { runId: runOptions.runId, stateRoot: runOptions.stateRoot || "", state: status },
      usage: sanitizeCyclePacketValue(usage.summary),
      resources: sanitizeCyclePacketValue(resources.summary),
      dispatcher: sanitizeCyclePacketValue(dispatcherState.dispatcher),
      queue: sanitizeCyclePacketValue(dispatcherState.queue),
      lease: sanitizeCyclePacketValue(dispatcherState.lease),
      workers: sanitizeCyclePacketValue(workers.summary),
      workerProgress: sanitizeCyclePacketValue(workerProgress.summary),
      laneAdvance: sanitizeCyclePacketValue(laneAdvance.summary),
      runway: sanitizeCyclePacketValue(runway.summary),
      preflight: {
        status: preflight.status,
        repo: sanitizeCyclePacketValue(preflightSummary.repo),
        branch: sanitizeCyclePacketValue(preflightSummary.branch),
        githubCli: sanitizeCyclePacketValue(preflightSummary.githubCli),
        workspaceProtocol: sanitizeCyclePacketValue(preflightSummary.workspaceProtocol),
        dispatcher: sanitizeCyclePacketValue(preflightSummary.dispatcher),
        ledgerStatus: preflightSummary.ledger?.status || "unknown",
        blockerCount: preflight.blockers?.length || 0,
        warningCount: preflight.warnings?.length || 0,
        recommendedNextAction: sanitizeLedgerField(preflightSummary.recommendedNextAction || "", "", 180),
        mutation: "none; read-only preflight summary",
        rawPayloadRetained: false,
      },
      continuation: sanitizeCyclePacketValue(continuation),
      managerCapabilityPosture: sanitizeCyclePacketValue(managerCapabilityPosture.summary),
      managerCapabilityStatus: sanitizeCyclePacketValue(managerCapabilityStatus),
      selfRepair: sanitizeCyclePacketValue(selfRepair.summary),
      recovery: sanitizeCyclePacketValue(recovery.summary),
      dispatchPreview: sanitizeCyclePacketValue(dispatchPreview.summary),
      delivery: sanitizeCyclePacketValue(delivery.summary || { mutationMode: "existing-gates-required", source: "codex-workspace existing gates" }),
      dispatchPosture: sanitizeCyclePacketValue(dispatchPosture.summary),
      steering: sanitizeCyclePacketValue(steering.summary),
      modelRouting: sanitizeCyclePacketValue(friction.summary.modelRouting),
      dependencyLoops: sanitizeCyclePacketValue(friction.summary.dependencyLoops),
      questionBlockers: sanitizeCyclePacketValue(workerQuestionBlockers),
      reviewResourcePolicy: sanitizeCyclePacketValue(friction.summary.reviewResourcePolicy),
      cleanup: sanitizeCyclePacketValue(cleanup.summary),
      resume: {
        status: resume.status,
        ledgerStatus: resume.summary?.ledger?.status || "unknown",
        schemaGapCount: resume.summary.schemaGaps.length,
        blockerCount: resume.blockers.length,
        blockedLaneAssignments: sanitizeCyclePacketValue(resume.summary.assignment.blockedLaneAssignments || []),
        blockedWorkspaceAssignments: sanitizeCyclePacketValue(resume.summary.assignment.blockedWorkspaceAssignments || []),
        takeoverInspection: sanitizeCyclePacketValue(resume.summary.takeoverInspection || null),
      },
      progress: sanitizeCyclePacketValue(progress.summary),
      feedback: sanitizeCyclePacketValue(feedback.summary),
      operationalActions: summaryOperationalActions,
      signalGaps: {
        status: signalGaps.status,
        gapCount: signalGaps.gapCount,
        blockerCount: signalGaps.blockerCount,
        gaps: signalGaps.gaps,
        rawPayloadRetained: false,
      },
      observations: {
        authority: observations.authority,
        dispatcherActiveCount: observations.dispatcherActiveCount,
        workerActiveCount: observations.workerActiveCount,
        tmux: observations.tmux,
        logs: observations.logs,
        dashboard: observations.dashboard,
        conflicts: observations.conflicts,
        rawPayloadRetained: false,
      },
      checkpoints: sanitizeCyclePacketValue(progress.summary.checkpointReports),
      finalReport: sanitizeCyclePacketValue(progress.summary.finalReport),
      questions: sanitizeCyclePacketValue(friction.summary.questionHandling),
      failureLoops: sanitizeCyclePacketValue(friction.summary.failureLoops),
      blockers: sanitizeCyclePacketValue(reportedBlockers),
      recommendedActions: cycleRecommendedActions,
      autoApply: sanitizeCyclePacketValue(autoApply),
      report: sanitizeLedgerField(report, "Manager: status unavailable", 600),
    },
    blockers: sanitizeCyclePacketValue(reportedBlockers),
    warnings: sanitizeCyclePacketValue(uniqueWarnings([...(usage.warnings || []), ...(resources.warnings || []), ...(persistedCapabilityPosture.warnings || []), ...(selfRepair.warnings || []), ...(workers.warnings || []), ...(workerProgress.warnings || []), ...(laneAdvance.warnings || []), ...(runway.warnings || []), ...(dispatchPreview.warnings || []), ...(signalGaps.warnings || []), ...(observations.warnings || []), ...(friction.warnings || []), ...(steering.warnings || []), ...(feedback.warnings || [])])),
    nextActions: cycleRecommendedActions,
  });
  return cyclePacket;
}

export function buildContinuousRunPlan(options = {}, context = {}) {
  const cycle = context.cyclePacket || buildCyclePacket(options, context);
  const promptProbe = context.promptProbe || buildWorkerPromptProbePlan({ ...options, limit: 6 }, context);
  const submitPending = context.submitPendingPlan || buildWorkerSubmitPendingPlan({ ...options, limit: 6 }, context);
  const warmWorkerCount = nonNegativeInteger(cycle.summary?.workers?.workerCounts?.warm ?? cycle.summary?.workerCounts?.warm) ?? 0;
  const handoffPlan = context.handoffPlan || (warmWorkerCount > 0 ? buildWorkerHandoffPlan({ ...options, limit: 6 }, context) : null);
  const promptProbeActions = promptProbe.status === "attention" && Array.isArray(promptProbe.nextActions) ? promptProbe.nextActions : [];
  const submitPendingActions = submitPending.status === "ready" && Array.isArray(submitPending.nextActions)
    ? submitPending.nextActions.filter((action) => action.code === "worker-submit-pending-apply-ready")
    : [];
  const idleLoadActions = buildPromptIdleLoadActions(cycle, promptProbe);
  const baseNextActions = [...promptProbeActions, ...submitPendingActions, ...idleLoadActions, ...(Array.isArray(cycle.nextActions) ? cycle.nextActions : [])];
  const needsQuestionAnswerGate = baseNextActions.some((action) => action.code === "worker-progress-blocked_question");
  const questionAnswer = context.questionAnswerPlan || (needsQuestionAnswerGate ? buildWorkerQuestionAnswerPlan({ ...options, limit: 6 }, context) : null);
  const questionAnswerAvailable = !needsQuestionAnswerGate ||
    Number(questionAnswer?.summary?.planned || 0) > 0 ||
    Number(questionAnswer?.summary?.answerableQuestions || 0) > 0;
  const handoffActions = questionAnswerAvailable && handoffPlan?.status === "ready" && Array.isArray(handoffPlan.nextActions)
    ? handoffPlan.nextActions.filter((action) => action.code === "worker-handoff-apply-ready")
    : [];
  const nextActions = [...promptProbeActions, ...submitPendingActions, ...handoffActions, ...idleLoadActions, ...(Array.isArray(cycle.nextActions) ? cycle.nextActions : [])]
    .filter((action) => questionAnswerAvailable || action.code !== "worker-handoff-apply-ready");
  const blockedQuestionRetireActions = buildBlockedQuestionRetireContinuousActions(cycle, questionAnswer, questionAnswerAvailable);
  const dispatchRoutingHold = buildContinuousDispatchRoutingHold(cycle);
  const capabilityPosture = buildManagerCapabilityPosture(options, context, cycle);
  const actionableCandidates = [...nextActions, ...blockedQuestionRetireActions]
    .filter((action) => action.code !== "worker-progress-blocked_question" || questionAnswerAvailable)
    .map((action) => buildContinuousAction(action, cycle, capabilityPosture))
    .filter(Boolean)
    .filter((action) => continuousActionAllowedByContinuation(action, cycle))
    .filter((action) => continuousActionAllowedByOperationalCapability(action, cycle))
    .map((action) => annotateContinuousAction(action));
  const capabilityFiltered = filterActionsByCapabilityPosture(actionableCandidates, capabilityPosture);
  const usefulWorkPolicy = buildContinuousUsefulWorkPolicy(capabilityFiltered.actions, { options, context, cycle });
  const effectiveCapabilityPosture = applyUsefulWorkPolicyCapabilityParks(capabilityPosture, usefulWorkPolicy);
  const effectiveCapabilityFiltered = filterActionsByCapabilityPosture(usefulWorkPolicy.actions, effectiveCapabilityPosture);
  const codexAdvisor = buildContinuousCodexAdvisorRecommendations(usefulWorkPolicy, cycle);
  const actionable = effectiveCapabilityFiltered.actions
    .sort(continuousActionSort);
  const selected = actionable.find((action) => !action.readOnly) || actionable[0] || null;
  const workers = cycle.summary?.workers?.workerCounts || {};
  const usage = cycle.summary?.usage || {};
  const resources = cycle.summary?.resources || {};
  const stopReasons = [];
  if (cycle.status === "blocked") {
    stopReasons.push({ code: "cycle-blocked", message: "Cycle packet is blocked; continuous mode must stop for operator or repair." });
  }
  if (usage.state === "manager_only") {
    stopReasons.push({ code: "usage-manager-only", message: "Usage is manager_only; continuous mode must stop new worker mutation." });
  }
  if (resources.state === "critical") {
    stopReasons.push({ code: "resource-critical", message: "Resources are critical; continuous mode must avoid additional worker mutation." });
  }
  const effectiveSelected = stopReasons.length > 0 ? null : selected;
  const status = stopReasons.length > 0 ? "blocked" : effectiveSelected || cycle.status === "attention" ? "attention" : "ready";
  const selectedAction = sanitizeCyclePacketValue(effectiveSelected);
  const attentionNextAction = continuousAttentionNextAction(cycle, dispatchRoutingHold);
  return packet({
    ok: stopReasons.length === 0,
    status,
    summary: {
      runId: cycle.summary?.run?.runId || resolveManagerRunId(options, context),
      mode: "continuous",
      maxIterations: options.maxIterations ?? 0,
      intervalMs: Math.max(1000, nonNegativeInteger(options.intervalMs) ?? 60000),
      heartbeatEvery: Math.max(1, nonNegativeInteger(options.heartbeatEvery) ?? 1),
      workerCounts: {
        active: workers.active ?? 0,
        warm: workers.warm ?? 0,
        paused: workers.paused ?? 0,
      },
      usageState: usage.state || "unknown",
      resourceState: resources.state || "unknown",
      cycleStatus: cycle.status,
      selectedAction,
      operationalActions: sanitizeCyclePacketValue(cycle.summary?.operationalActions || null),
      managerCapabilityPosture: sanitizeCyclePacketValue(effectiveCapabilityPosture.summary),
      capabilityHolds: sanitizeCyclePacketValue(mergeCapabilityHoldSummaries(capabilityFiltered.summary, effectiveCapabilityFiltered.summary)),
      codexAdvisor: sanitizeCyclePacketValue(codexAdvisor.summary),
      reviewResourcePolicy: sanitizeCyclePacketValue(cycle.summary?.reviewResourcePolicy || null),
      dispatchRouting: sanitizeCyclePacketValue(dispatchRoutingHold?.decision || null),
      allowedActionCount: stopReasons.length > 0 ? 0 : actionable.length,
      usefulWorkPolicy: sanitizeCyclePacketValue(usefulWorkPolicy.summary),
      retention: "metadata_only_continuous_loop_summary",
      stopReasons: sanitizeCyclePacketValue(stopReasons),
    },
    blockers: stopReasons.map((reason) => ({ code: reason.code, message: reason.message, nextAction: "Stop continuous mode and inspect the latest manager-cycle-packet." })),
    warnings: sanitizeCyclePacketValue([...(promptProbe.warnings || []), ...(handoffPlan?.warnings || []), ...(cycle.warnings || []), ...capabilityFiltered.warnings, ...effectiveCapabilityFiltered.warnings, ...usefulWorkPolicy.warnings, ...codexAdvisor.warnings]),
    nextActions: stopReasons.length > 0
      ? [{ code: "continuous-blocked", summary: "Continuous mode is blocked by the latest cycle packet.", nextAction: "Stop continuous mode and inspect the latest manager-cycle-packet." }]
      : effectiveSelected
        ? [{ code: "continuous-apply-ready", summary: sanitizeLedgerField(effectiveSelected.summary, "", 180), nextAction: sanitizeLedgerField(effectiveSelected.applyCommand, "", 260) }]
        : codexAdvisor.nextActions.length > 0
        ? codexAdvisor.nextActions
        : cycle.status === "attention"
        ? [{ code: "continuous-attention-monitor", summary: "Manager attention remains, but no auto-safe action is currently available.", nextAction: attentionNextAction }]
        : [{ code: "continuous-monitor", summary: "No manager-owned auto action is currently needed.", nextAction: "Sleep until the next continuous manager poll." }],
  });
}

function buildContinuousCodexAdvisorRecommendations(usefulWorkPolicy = {}, cycle = {}) {
  const parked = Array.isArray(usefulWorkPolicy.summary?.parkedSelfRepair)
    ? usefulWorkPolicy.summary.parkedSelfRepair
    : [];
  if (parked.length === 0) {
    return {
      summary: {
        status: "not_needed",
        packetCount: 0,
        recommendations: [],
        rawPayloadRetained: false,
      },
      warnings: [],
      nextActions: [],
    };
  }
  const runId = sanitizeLedgerField(cycle.summary?.run?.runId || "manager-run", "manager-run", 120);
  const safeTaskWorkAvailable = Number(usefulWorkPolicy.summary?.usefulWorkActions || 0) > 0;
  const recommendations = parked.slice(0, 4).map((repair) => {
    const actionCode = sanitizeLedgerField(repair.actionCode || "manager-self-repair", "manager-self-repair", 120);
    const capability = sanitizeLedgerField(repair.managerCapability || "manager", "manager", 80);
    const workClass = sanitizeLedgerField(repair.workClass || "manager_improvement", "manager_improvement", 80);
    const condition = `self_fix_churn ${actionCode}`;
    const evidenceRefs = [`self-repair:${actionCode}`, `cycle:${runId}`];
    const sourceRefs = ["manager:continuous-run", `manager:capability:${capability}`];
    const advisor = buildCodexAdvisorPacketPlan(
      {
        runId,
        advisorCondition: condition,
        advisorFailureKind: "self_fix_churn",
        advisorActionCode: actionCode,
        advisorWorkClass: workClass,
        summary: `Manager self-repair action ${actionCode} exceeded budget; classify before adding another handler.`,
        evidenceRefs,
        sourceRefs,
      },
      {
        usefulWorkPolicy: usefulWorkPolicy.summary,
        safeTaskWorkAvailable,
      },
    );
    const request = advisor.summary?.requestPacket || {};
    const command = [
      "node ./scripts/manager-codex-advisor-packet.mjs",
      "--summary-json",
      "--run-id",
      shellSingleQuote(runId),
      "--condition",
      shellSingleQuote(condition),
      "--failure-kind",
      "self_fix_churn",
      "--action-code",
      shellSingleQuote(actionCode),
      "--work-class",
      shellSingleQuote(workClass),
      "--evidence-ref",
      shellSingleQuote(evidenceRefs[0]),
      "--evidence-ref",
      shellSingleQuote(evidenceRefs[1]),
      "--source-ref",
      shellSingleQuote(sourceRefs[0]),
      "--source-ref",
      shellSingleQuote(sourceRefs[1]),
    ].join(" ");
    return {
      status: advisor.status,
      packetId: sanitizeLedgerField(request.packetId || "", "", 160),
      actionCode,
      managerCapability: capability,
      workClass,
      recommendedResponse: sanitizeLedgerField(request.taskContinuity?.recommendedResponse || "", "", 120),
      existingHandler: sanitizeLedgerField(request.condition?.existingHandler?.handler || "", "", 120),
      safeTaskWorkAvailable,
      command,
      warnings: advisor.warnings || [],
      blockers: advisor.blockers || [],
      rawPayloadRetained: false,
    };
  });
  const readyRecommendations = recommendations.filter((recommendation) => recommendation.status === "ready");
  return {
    summary: {
      status: readyRecommendations.length > 0 ? "ready" : "blocked",
      packetCount: recommendations.length,
      recommendations,
      rawPayloadRetained: false,
    },
    warnings: [
      {
        code: "continuous-codex-advisor-recommended",
        message: `${recommendations.length} self-repair churn item(s) should be classified through Codex advisor before adding manager handlers.`,
      },
      ...recommendations.flatMap((recommendation) => recommendation.warnings || []),
    ],
    nextActions: readyRecommendations.length > 0
      ? [{
          code: "continuous-codex-advisor-packet-ready",
          summary: "Self-repair churn is parked; generate a metadata-only Codex advisor packet before adding another manager handler.",
          nextAction: sanitizeLedgerField(readyRecommendations[0].command, "", 420),
        }]
      : [],
  };
}

function annotateContinuousAction(action = {}) {
  const workClass = continuousActionWorkClass(action);
  const managerCapability = continuousActionCapability(action);
  return {
    ...action,
    workClass,
    ...(managerCapability ? { managerCapability } : {}),
    usefulWork: workClass === "task_work",
    selfRepair: ["direct_unblock_repair", "safety_repair", "manager_improvement"].includes(workClass),
  };
}

function continuousActionCapability(action = {}) {
  const code = String(action.code || "");
  if ([
    "continuous-worker-prompt-probe",
    "continuous-worker-submit-pending",
    "continuous-worker-warm",
    "continuous-worker-handoff",
    "continuous-worker-progress-signal",
    "continuous-worker-prompt-idle-progress-signal",
    "continuous-worker-answer-question",
    "continuous-worker-recovery-inspection",
    "continuous-worker-retire",
    "continuous-worker-retire-blocked-question",
  ].includes(code)) {
    return "tmuxWorkerMutation";
  }
  if (code === "continuous-dispatch-apply") return "dispatchApply";
  if (code === "continuous-refill-apply") return "refillApply";
  if ([
    "continuous-worker-code-review-request",
    "continuous-worker-code-review-request-prepared",
    "continuous-worker-code-review-no-reviewer",
  ].includes(code)) {
    return "reviewDelegation";
  }
  return "";
}

function continuousActionWorkClass(action = {}) {
  const code = String(action.code || "");
  if ([
    "continuous-worker-code-review-request",
    "continuous-lane-advance-apply",
    "continuous-worker-warm",
    "continuous-worker-handoff",
    "continuous-worker-progress-signal",
    "continuous-worker-prompt-idle-progress-signal",
    "continuous-worker-answer-question",
    "continuous-refill-apply",
    "continuous-dispatch-apply",
  ].includes(code)) {
    return "task_work";
  }
  if (code === "continuous-worker-code-review-request-prepared") {
    return action.readOnly === true ? "manager_improvement" : "direct_unblock_repair";
  }
  if (["continuous-worker-prompt-probe", "continuous-worker-submit-pending"].includes(code)) {
    return "direct_unblock_repair";
  }
  if (["continuous-worker-recovery-inspection", "continuous-worker-retire", "continuous-worker-retire-blocked-question"].includes(code)) {
    return "safety_repair";
  }
  if (code === "continuous-worker-code-review-no-reviewer") {
    return "manager_improvement";
  }
  return "manager_improvement";
}

function buildContinuousUsefulWorkPolicy(actions = [], { options = {}, context = {}, cycle = {} } = {}) {
  const selfRepairBudget = Math.max(1, nonNegativeInteger(options.selfRepairBudget ?? context.selfRepairBudget ?? cycle.summary?.selfRepair?.budget ?? cycle.summary?.managerHealth?.selfRepairBudget) ?? 2);
  const attemptsByAction = isPlainObject(cycle.summary?.selfRepair?.attemptsByAction)
    ? cycle.summary.selfRepair.attemptsByAction
    : isPlainObject(cycle.summary?.managerHealth?.selfRepairAttemptsByAction)
      ? cycle.summary.managerHealth.selfRepairAttemptsByAction
      : {};
  const usefulWorkCount = actions.filter((action) => action.workClass === "task_work").length;
  const repairCount = actions.filter((action) => action.selfRepair).length;
  const parkedSelfRepair = [];
  const allowedActions = [];
  for (const action of actions) {
    const attemptCount = nonNegativeInteger(
      action.repairAttemptCount ??
      attemptsByAction[action.code] ??
      attemptsByAction[action.mutationClass] ??
      cycle.summary?.selfRepair?.attemptCount ??
      cycle.summary?.managerHealth?.selfRepairAttemptCount,
    ) ?? 0;
    if (action.selfRepair && attemptCount >= selfRepairBudget) {
      parkedSelfRepair.push({
        code: "self_fix_churn",
        actionCode: action.code,
        managerCapability: action.managerCapability || continuousActionCapability(action),
        workClass: action.workClass,
        attemptCount,
        budget: selfRepairBudget,
        nextAction: "Park or degrade this manager capability and continue safe task work through existing gates.",
      });
      continue;
    }
    allowedActions.push({ ...action, repairAttemptCount: action.selfRepair ? attemptCount : undefined, selfRepairBudget: action.selfRepair ? selfRepairBudget : undefined });
  }
  return {
    actions: allowedActions,
    warnings: parkedSelfRepair.length > 0
      ? [{ code: "self_fix_churn", message: `${parkedSelfRepair.length} manager self-repair action(s) exceeded budget and were parked.` }]
      : [],
    summary: {
      usefulWorkActions: usefulWorkCount,
      managerRepairActions: repairCount,
      parkedSelfRepair,
      selfRepairBudget,
      policy: "task_work_before_manager_self_repair",
      rawPayloadRetained: false,
    },
  };
}

export function buildManagerCapabilityPosture(options = {}, context = {}, cycle = {}) {
  const defaults = {
    tmuxWorkerMutation: {
      state: "enabled",
      reasonCodes: [],
      safeFallbacks: ["dispatch_apply_existing_gates", "source_owned_refill_planning", "lane_advance_metadata", "heartbeat_reporting"],
    },
    dispatchApply: {
      state: "enabled",
      reasonCodes: [],
      safeFallbacks: ["active_worker_monitoring", "source_owned_refill_planning", "review_or_lane_advance_gates", "heartbeat_reporting"],
    },
    refillApply: {
      state: "enabled",
      reasonCodes: [],
      safeFallbacks: ["dispatch_apply_existing_gates", "active_worker_monitoring", "heartbeat_reporting"],
    },
    reviewDelegation: {
      state: "enabled",
      reasonCodes: [],
      safeFallbacks: ["lane_advance_to_review_held", "active_worker_monitoring", "dispatch_or_refill_unrelated_lanes", "heartbeat_reporting"],
    },
    cleanupApply: {
      state: "blocked",
      reasonCodes: ["cleanup_apply_requires_separate_gate"],
      safeFallbacks: ["delivery_report", "cleanup_dry_run_only", "heartbeat_reporting"],
    },
  };
  const merged = Object.fromEntries(
    Object.entries(defaults).map(([capability, value]) => [capability, { ...value, reasonCodes: [...value.reasonCodes], safeFallbacks: [...value.safeFallbacks] }]),
  );
  for (const input of [
    cycle.summary?.managerCapabilityPosture,
    context.managerCapabilityPosture,
    options.managerCapabilityPosture,
    context.persistedManagerCapabilityPosture,
    managerCapabilityPostureFromAdvisorClassification(context.codexAdvisorClassification || options.codexAdvisorClassification),
  ]) {
    mergeManagerCapabilityPosture(merged, input);
  }
  return {
    capabilities: merged,
    summary: summarizeManagerCapabilityPosture(merged),
  };
}

function managerCapabilityPostureFromAdvisorClassification(input = null) {
  if (!isPlainObject(input)) return null;
  if (isPlainObject(input.posturePatch)) return input.posturePatch;
  if (isPlainObject(input.summary?.posturePatch)) return input.summary.posturePatch;
  const classification = isPlainObject(input.classification) ? input.classification : isPlainObject(input.summary?.classification) ? input.summary.classification : input;
  const recommendation = normalizeAdvisorRecommendation(classification.recommendation || "");
  if (recommendation !== "park_or_degrade_capability") return null;
  const capability = sanitizeLedgerField(classification.capability || classification.capabilityName || "", "", 80);
  const state = normalizeManagerCapabilityState(classification.requestedState || classification.state || "").state;
  if (!capability || !["parked", "degraded", "blocked"].includes(state)) return null;
  return {
    [capability]: {
      state,
      reasonCodes: uniqueManagerCapabilityValues(classification.reasonCodes || [`codex_advisor_${recommendation}`]),
      safeFallbacks: uniqueManagerCapabilityValues(classification.safeFallbacks || classification.fallbacks || []),
    },
  };
}

function summarizeManagerCapabilityPosture(capabilities = {}) {
  const parkedCapabilities = [];
  const degradedCapabilities = [];
  const blockedCapabilities = [];
  for (const [capability, posture] of Object.entries(capabilities)) {
    if (posture.state === "parked") parkedCapabilities.push(capability);
    if (posture.state === "degraded") degradedCapabilities.push(capability);
    if (posture.state === "blocked") blockedCapabilities.push(capability);
  }
  return {
    policy: "capability_posture",
    capabilities,
    parkedCapabilities,
    degradedCapabilities,
    blockedCapabilities,
    rawPayloadRetained: false,
  };
}

function applyUsefulWorkPolicyCapabilityParks(posture = {}, usefulWorkPolicy = {}) {
  const next = buildManagerCapabilityPosture({}, { managerCapabilityPosture: posture.summary || posture }, {});
  for (const parked of usefulWorkPolicy.summary?.parkedSelfRepair || []) {
    const capability = parked.managerCapability || "";
    if (!capability || !next.capabilities[capability]) continue;
    next.capabilities[capability] = {
      ...next.capabilities[capability],
      state: "parked",
      reasonCodes: uniqueManagerCapabilityValues([
        ...(next.capabilities[capability].reasonCodes || []),
        "self_fix_churn",
        parked.actionCode ? `${parked.actionCode}_over_budget` : "",
      ]),
      safeFallbacks: next.capabilities[capability].safeFallbacks || [],
    };
  }
  return {
    capabilities: next.capabilities,
    summary: summarizeManagerCapabilityPosture(next.capabilities),
  };
}

function mergeManagerCapabilityPosture(target = {}, input = null) {
  if (!isPlainObject(input)) return;
  const source = isPlainObject(input.capabilities) ? input.capabilities : input;
  for (const capability of Object.keys(target)) {
    const update = source[capability];
    if (!update) continue;
    const normalized = normalizeManagerCapabilityState(update);
    target[capability] = {
      state: normalized.state || target[capability].state,
      reasonCodes: normalized.reasonCodes.length > 0 ? normalized.reasonCodes : target[capability].reasonCodes,
      safeFallbacks: normalized.safeFallbacks.length > 0 ? normalized.safeFallbacks : target[capability].safeFallbacks,
    };
  }
  for (const capability of ["tmuxWorkerMutation", "dispatchApply", "refillApply", "reviewDelegation", "cleanupApply"]) {
    const stateFromArray = postureStateFromCapabilityArrays(input, capability);
    if (stateFromArray) {
      target[capability] = {
        ...target[capability],
        state: stateFromArray,
        reasonCodes: target[capability].reasonCodes.length > 0 ? target[capability].reasonCodes : [`${capability}_${stateFromArray}`],
      };
    }
  }
}

function postureStateFromCapabilityArrays(input = {}, capability = "") {
  const parked = Array.isArray(input.parkedCapabilities) ? input.parkedCapabilities.map(String) : [];
  const blocked = Array.isArray(input.blockedCapabilities) ? input.blockedCapabilities.map(String) : [];
  const degraded = Array.isArray(input.degradedCapabilities) ? input.degradedCapabilities.map(String) : [];
  if (blocked.includes(capability)) return "blocked";
  if (parked.includes(capability)) return "parked";
  if (degraded.includes(capability)) return "degraded";
  return "";
}

function normalizeManagerCapabilityState(value = {}) {
  const input = isPlainObject(value) ? value : { state: value };
  const rawState = String(input.state || input.status || "").trim().toLowerCase().replace(/-/g, "_");
  const state = ["enabled", "degraded", "parked", "blocked"].includes(rawState) ? rawState : "";
  return {
    state,
    reasonCodes: normalizeManagerCapabilityList(input.reasonCodes || input.reasons || input.reasonCode),
    safeFallbacks: normalizeManagerCapabilityList(input.safeFallbacks || input.fallbacks || input.safeFallback),
  };
}

function normalizeManagerCapabilityList(value = []) {
  const values = Array.isArray(value) ? value : [value];
  return values
    .map((item) => sanitizeLedgerField(item, "", 120))
    .filter(Boolean)
    .slice(0, 8);
}

function uniqueManagerCapabilityValues(values = []) {
  const seen = new Set();
  const result = [];
  for (const value of normalizeManagerCapabilityList(values)) {
    if (seen.has(value)) continue;
    seen.add(value);
    result.push(value);
  }
  return result;
}

function defaultManagerCapabilityPostureRecord(runId = defaultRunId()) {
  const posture = buildManagerCapabilityPosture({}, {}, {}).summary;
  return {
    schemaVersion: "manager_capability_posture.v1",
    runId: safeRunId(runId),
    updatedAt: new Date().toISOString(),
    ...posture,
  };
}

export function readManagerCapabilityPosture(options = {}, context = {}) {
  const runId = safeRunId(options.runId || defaultRunId());
  const paths = managerRunPaths(runId, options, context);
  if (!paths.proof.ok) {
    return packet({
      ok: false,
      status: "blocked",
      summary: { runId, stateRoot: paths.proof.state.root, managerCapabilityPosture: null },
      blockers: [{ code: "workspace-state-unsafe", message: paths.proof.error, nextAction: "Choose a safe workspace state root." }],
    });
  }
  if (!existsSync(paths.capabilityPosture)) {
    return packet({
      status: "missing",
      summary: {
        runId,
        path: paths.capabilityPosture,
        managerCapabilityPosture: null,
        rawPayloadRetained: false,
      },
    });
  }
  const read = readJsonStrict(paths.capabilityPosture);
  if (read.status !== "ready" || !isPlainObject(read.value)) {
    return packet({
      ok: true,
      status: "warning",
      summary: {
        runId,
        path: paths.capabilityPosture,
        managerCapabilityPosture: null,
        rawPayloadRetained: false,
      },
      warnings: [{
        code: "capability-posture-unreadable",
        message: `Persisted manager capability posture is ${read.status}; ignoring it for this cycle.`,
      }],
    });
  }
  const normalized = buildManagerCapabilityPosture({}, { managerCapabilityPosture: read.value }, {});
  return packet({
    status: "ready",
    summary: {
      runId,
      path: paths.capabilityPosture,
      managerCapabilityPosture: normalized.summary,
      rawPayloadRetained: false,
    },
  });
}

export function writeManagerCapabilityPosture(posture = {}, options = {}, context = {}) {
  const runId = safeRunId(options.runId || defaultRunId());
  const paths = managerRunPaths(runId, options, context);
  if (!paths.proof.ok) {
    return packet({
      ok: false,
      status: "blocked",
      summary: { runId, stateRoot: paths.proof.state.root },
      blockers: [{ code: "workspace-state-unsafe", message: paths.proof.error, nextAction: "Choose a safe workspace state root." }],
    });
  }
  const normalized = buildManagerCapabilityPosture({}, { managerCapabilityPosture: posture }, {});
  const record = {
    schemaVersion: "manager_capability_posture.v1",
    runId,
    updatedAt: new Date().toISOString(),
    ...normalized.summary,
    ...(managerCapabilityPostureLastChange(options) || {}),
  };
  mkdirSync(paths.root, { recursive: true });
  const write = writeJsonAtomic(paths.capabilityPosture, record);
  if (!write.ok) {
    return packet({
      ok: false,
      status: "blocked",
      summary: {
        runId,
        path: paths.capabilityPosture,
        managerCapabilityPosture: null,
        rawPayloadRetained: false,
      },
      blockers: [{
        code: "capability-posture-atomic-write-failed",
        message: "Manager capability posture could not be atomically persisted.",
        nextAction: "Inspect manager runtime state permissions and rerun before applying manager actions.",
      }],
      warnings: write.warning ? [write.warning] : [],
    });
  }
  const verify = readJsonStrict(paths.capabilityPosture);
  if (verify.status !== "ready" || !isPlainObject(verify.value)) {
    return packet({
      ok: false,
      status: "blocked",
      summary: {
        runId,
        path: paths.capabilityPosture,
        managerCapabilityPosture: null,
        rawPayloadRetained: false,
      },
      blockers: [{
        code: "capability-posture-write-verify-failed",
        message: "Manager capability posture write completed but the persisted record was not readable.",
        nextAction: "Inspect manager runtime state storage before applying manager actions.",
      }],
    });
  }
  return packet({
    status: "ready",
    summary: {
      runId,
      path: paths.capabilityPosture,
      managerCapabilityPosture: normalized.summary,
      rawPayloadRetained: false,
    },
  });
}

function writeJsonAtomic(path, value) {
  const tmpPath = `${path}.${process.pid}.${Date.now()}.tmp`;
  try {
    writeFileSync(tmpPath, `${JSON.stringify(value, null, 2)}\n`);
    renameSync(tmpPath, path);
    return { ok: true };
  } catch (error) {
    try {
      if (existsSync(tmpPath)) rmSync(tmpPath, { force: true });
    } catch {
      // Best-effort cleanup only; the caller receives the write failure.
    }
    return {
      ok: false,
      warning: {
        code: "capability-posture-temp-write-cleanup",
        message: `Capability posture atomic write failed before verification: ${sanitizeLedgerField(error?.code || error?.message || "unknown", "unknown", 120)}.`,
      },
    };
  }
}

function managerCapabilityPostureLastChange(options = {}) {
  const command = String(options.command || "").trim();
  const capability = sanitizeLedgerField(options.capabilityName || "", "", 80);
  const state = normalizeManagerCapabilityState(options.capabilityState || "").state;
  const reasonCodes = uniqueManagerCapabilityValues(options.capabilityReasonCodes || []);
  const sourceRefs = sanitizeSourceRefs(options.sourceRefs || []);
  const evidenceRefs = sanitizeSourceRefs(options.evidenceRefs || []);
  if (!command && !capability && !state && reasonCodes.length === 0 && sourceRefs.length === 0 && evidenceRefs.length === 0) return null;
  return {
    lastChange: {
      changedAt: new Date().toISOString(),
      actor: command ? "operator" : "manager",
      command: sanitizeLedgerField(command || "write", "write", 40),
      capability: capability || null,
      state: state || null,
      reasonCodes,
      sourceRefs,
      evidenceRefs,
      rawPayloadRetained: false,
    },
  };
}

export function buildManagerCapabilityPostureControlPlan(options = {}, context = {}) {
  const command = String(options.command || "show").trim() || "show";
  const runId = safeRunId(options.runId || defaultRunId());
  const read = readManagerCapabilityPosture({ ...options, runId }, context);
  if (!["show", "set", "clear"].includes(command)) {
    return packet({
      ok: false,
      status: "blocked",
      summary: { runId, command, mutation: "none" },
      blockers: [{ code: "capability-posture-command-invalid", message: `Unsupported capability posture command: ${command}.`, nextAction: "Use show, set, or clear." }],
    });
  }
  if (command !== "show" && read.ok === false) {
    return packet({
      ok: false,
      status: "blocked",
      summary: {
        runId,
        command,
        path: read.summary?.path || managerRunPaths(runId, options, context).capabilityPosture,
        mutation: "none",
        rawPayloadRetained: false,
      },
      blockers: read.blockers?.length
        ? read.blockers
        : [{ code: "capability-posture-read-blocked", message: "Capability posture mutation requires a readable safe manager state root.", nextAction: "Fix the state root boundary and rerun the capability posture command." }],
      warnings: read.warnings || [],
    });
  }
  if (command !== "show" && read.status === "warning") {
    return packet({
      ok: false,
      status: "blocked",
      summary: {
        runId,
        command,
        path: read.summary?.path || managerRunPaths(runId, options, context).capabilityPosture,
        mutation: "none",
        rawPayloadRetained: false,
      },
      blockers: [{
        code: "capability-posture-read-unverified",
        message: "Capability posture mutation requires the persisted posture file to be readable.",
        nextAction: "Inspect or replace capability-posture.json before changing manager capability posture.",
      }],
      warnings: read.warnings || [],
    });
  }
  const current = read.summary?.managerCapabilityPosture || buildManagerCapabilityPosture({}, {}, {}).summary;
  if (command === "show") {
    return packet({
      status: "ready",
      summary: {
        runId,
        command,
        postureSource: read.status === "ready" ? "persisted" : "default",
        path: read.summary?.path || managerRunPaths(runId, options, context).capabilityPosture,
        managerCapabilityPosture: current,
        mutation: "none; read-only capability posture summary",
        rawPayloadRetained: false,
      },
      warnings: read.warnings || [],
    });
  }

  const validation = validateManagerCapabilityPostureControl(command, options, current);
  if (validation.blockers.length > 0) {
    return packet({
      ok: false,
      status: "blocked",
      summary: {
        runId,
        command,
        capability: sanitizeLedgerField(options.capabilityName || "", "", 80),
        requestedState: command === "clear" ? "enabled" : sanitizeLedgerField(options.capabilityState || "", "", 40),
        mutation: "none",
        rawPayloadRetained: false,
      },
      blockers: validation.blockers,
      warnings: [...(read.warnings || []), ...validation.warnings],
    });
  }

  const capability = validation.capability;
  const requestedState = command === "clear" ? "enabled" : validation.state;
  const nextCapabilities = {
    ...(current.capabilities || {}),
    [capability]: {
      state: requestedState,
      reasonCodes: validation.reasonCodes,
      safeFallbacks: validation.safeFallbacks,
    },
  };
  const planned = summarizeManagerCapabilityPosture(nextCapabilities);
  const resultSummary = {
    runId,
    command,
    capability,
    requestedState,
    path: read.summary?.path || managerRunPaths(runId, options, context).capabilityPosture,
    currentPosture: current,
    plannedPosture: planned,
    mutation: options.apply ? "manager_capability_posture_write" : "none; dry-run capability posture preview",
    applyRequired: !options.apply,
    rawPayloadRetained: false,
  };
  if (!options.apply) {
    return packet({
      status: "ready",
      summary: resultSummary,
      warnings: [...(read.warnings || []), ...validation.warnings],
      nextActions: [{
        code: "capability-posture-apply-ready",
        summary: `Apply ${capability} -> ${requestedState} capability posture change.`,
        nextAction: "Rerun node ./scripts/manager-capability-posture.mjs --summary-json with the same arguments plus --apply after reviewing the dry-run packet.",
      }],
    });
  }
  const write = writeManagerCapabilityPosture(planned, { ...options, runId, capabilityName: capability, capabilityState: requestedState }, context);
  if (!write.ok) return write;
  return packet({
    status: "ready",
    summary: {
      ...resultSummary,
      managerCapabilityPosture: write.summary.managerCapabilityPosture,
      writeStatus: write.status,
    },
    warnings: [...(read.warnings || []), ...validation.warnings, ...(write.warnings || [])],
    nextActions: [{
      code: "capability-posture-updated",
      summary: `${capability} capability posture is now ${requestedState}.`,
      nextAction: "Rerun node ./scripts/manager-capability-posture.mjs --summary-json show or manager continuous mode to inspect the effective posture.",
    }],
  });
}

function validateManagerCapabilityPostureControl(command = "show", options = {}, current = {}) {
  const blockers = [];
  const warnings = [];
  const validCapabilities = Object.keys(current.capabilities || buildManagerCapabilityPosture({}, {}, {}).summary.capabilities || {});
  const capability = sanitizeLedgerField(options.capabilityName || "", "", 80);
  if (!capability || !validCapabilities.includes(capability)) {
    blockers.push({
      code: "capability-posture-capability-invalid",
      message: `Capability must be one of: ${validCapabilities.join(", ")}.`,
      nextAction: "Provide --capability with a known manager capability.",
    });
  }
  const requested = command === "clear" ? "enabled" : normalizeManagerCapabilityState(options.capabilityState || "").state;
  if (!requested || !["enabled", "degraded", "parked", "blocked"].includes(requested)) {
    blockers.push({
      code: "capability-posture-state-invalid",
      message: "Capability posture state must be enabled, degraded, parked, or blocked.",
      nextAction: "Provide --state with a supported state, or use clear to set enabled.",
    });
  }
  const reasonCodes = uniqueManagerCapabilityValues(options.capabilityReasonCodes || []);
  const safeFallbacks = uniqueManagerCapabilityValues(options.capabilitySafeFallbacks || []);
  const evidenceRefs = sanitizeSourceRefs(options.evidenceRefs || []);
  const sourceRefs = sanitizeSourceRefs(options.sourceRefs || []);
  const rejectedRefs = [...sourceRefList(options.evidenceRefs || []), ...sourceRefList(options.sourceRefs || [])].filter(capabilityPostureRefRejected);
  if (rejectedRefs.length > 0) {
    blockers.push({
      code: "capability-posture-raw-ref-rejected",
      message: "Capability posture controls may retain only compact source/evidence refs, not raw payload markers or secrets.",
      nextAction: "Replace raw refs with compact metadata refs such as evidence:manager-observation.",
    });
  }
  if (reasonCodes.length === 0) {
    blockers.push({
      code: "capability-posture-reason-missing",
      message: "Capability posture changes require at least one reason code.",
      nextAction: "Provide --reason-code with a compact reason.",
    });
  }
  if (evidenceRefs.length === 0) {
    blockers.push({
      code: "capability-posture-evidence-missing",
      message: "Capability posture changes require compact evidence refs.",
      nextAction: "Provide --evidence-ref with metadata-only evidence.",
    });
  }
  if (["parked", "blocked", "degraded"].includes(requested) && safeFallbacks.length === 0) {
    blockers.push({
      code: "capability-posture-fallback-missing",
      message: "Reduced capability states require at least one safe fallback.",
      nextAction: "Provide --safe-fallback with the useful work that remains allowed.",
    });
  }
  if (command === "clear" && requested === "enabled" && safeFallbacks.length === 0) {
    warnings.push({ code: "capability-posture-clear-no-fallback", message: "Clear will preserve the existing safe fallback list when present, otherwise restore the default safe fallback list for this capability." });
  }
  const existing = capability ? current.capabilities?.[capability] : null;
  const defaultCapability = buildManagerCapabilityPosture({}, {}, {}).summary.capabilities?.[capability] || {};
  return {
    capability,
    state: requested,
    reasonCodes,
    safeFallbacks: safeFallbacks.length > 0 ? safeFallbacks : existing?.safeFallbacks || defaultCapability.safeFallbacks || [],
    sourceRefs,
    evidenceRefs,
    blockers,
    warnings,
  };
}

function capabilityPostureRefRejected(ref = "") {
  return /\b(raw prompt|completion|reasoning trace|provider payload|raw transcript|transcript|stack dump|source dump|raw log|raw scrollback|OPENAI_API_KEY|password|secret)\b/i.test(String(ref || "")) ||
    /\b(sk-[A-Za-z0-9_-]+|gh[pousr]_[A-Za-z0-9_]+)\b/.test(String(ref || ""));
}

function filterActionsByCapabilityPosture(actions = [], posture = {}) {
  const capabilities = posture.capabilities || {};
  const heldActions = [];
  const allowedActions = [];
  const degradedActions = [];
  for (const action of actions) {
    const capability = action.managerCapability || continuousActionCapability(action);
    const state = capability ? capabilities[capability]?.state || "enabled" : "enabled";
    const annotated = capability ? { ...action, managerCapability: capability, capabilityState: state } : action;
    if (["parked", "blocked"].includes(state)) {
      heldActions.push({
        code: action.code,
        managerCapability: capability,
        state,
        reasonCodes: capabilities[capability]?.reasonCodes || [],
        safeFallbacks: capabilities[capability]?.safeFallbacks || [],
      });
      continue;
    }
    if (state === "degraded") degradedActions.push({ code: action.code, managerCapability: capability });
    allowedActions.push(annotated);
  }
  return {
    actions: allowedActions,
    warnings: heldActions.length > 0
      ? [{ code: "capability_posture_hold", message: `${heldActions.length} continuous action(s) held by parked or blocked manager capability posture.` }]
      : [],
    summary: {
      policy: "capability_posture",
      heldActions,
      degradedActions,
      rawPayloadRetained: false,
    },
  };
}

function mergeCapabilityHoldSummaries(...summaries) {
  const heldActions = [];
  const degradedActions = [];
  const seenHeld = new Set();
  const seenDegraded = new Set();
  for (const summary of summaries) {
    for (const held of Array.isArray(summary?.heldActions) ? summary.heldActions : []) {
      const key = `${held.code || ""}:${held.managerCapability || ""}:${held.state || ""}`;
      if (seenHeld.has(key)) continue;
      seenHeld.add(key);
      heldActions.push(held);
    }
    for (const degraded of Array.isArray(summary?.degradedActions) ? summary.degradedActions : []) {
      const key = `${degraded.code || ""}:${degraded.managerCapability || ""}`;
      if (seenDegraded.has(key)) continue;
      seenDegraded.add(key);
      degradedActions.push(degraded);
    }
  }
  return {
    policy: "capability_posture",
    heldActions,
    degradedActions,
    rawPayloadRetained: false,
  };
}

function continuousActionSort(left = {}, right = {}) {
  const workDelta = continuousWorkClassPriority(left) - continuousWorkClassPriority(right);
  if (workDelta !== 0) return workDelta;
  return continuousActionPriority(left) - continuousActionPriority(right);
}

function continuousWorkClassPriority(action = {}) {
  const priorities = new Map([
    ["task_work", 0],
    ["direct_unblock_repair", 10],
    ["safety_repair", 20],
    ["manager_improvement", 40],
    ["self_fix_churn", 90],
  ]);
  return priorities.get(action.workClass) ?? 80;
}

function continuousAttentionNextAction(cycle = {}, dispatchRoutingHold = null) {
  if (dispatchRoutingHold?.nextAction && !isDispatchApplyCommandText(dispatchRoutingHold.nextAction)) {
    return sanitizeLedgerField(dispatchRoutingHold.nextAction, "Inspect the latest manager-cycle-packet recommended actions.", 260);
  }
  const safeAction = (Array.isArray(cycle.nextActions) ? cycle.nextActions : []).find((action) => {
    if (action?.code === "dispatch-preview-ready") return false;
    return action?.nextAction && !isDispatchApplyCommandText(action.nextAction);
  });
  return sanitizeLedgerField(
    safeAction?.nextAction || "Inspect the latest manager-cycle-packet recommended actions.",
    "Inspect the latest manager-cycle-packet recommended actions.",
    260,
  );
}

function isDispatchApplyCommandText(value = "") {
  const text = safeString(value, "").toLowerCase();
  return /\bdispatch-next\b/.test(text) && /\b--apply\b/.test(text);
}

function safeBlockerArray(value = [], fallbackCode = "blocker-unreadable") {
  if (value === undefined || value === null) return [];
  if (!Array.isArray(value)) {
    return [{ code: fallbackCode, message: "Blocker evidence was not a readable array.", nextAction: "Inspect compact manager packet evidence before continuing." }];
  }
  return value.map((blocker, index) => {
    if (blocker && typeof blocker === "object" && !Array.isArray(blocker)) return blocker;
    return {
      code: fallbackCode,
      message: `Blocker evidence entry ${index} was not a readable object.`,
      nextAction: "Inspect compact manager packet evidence before continuing.",
    };
  });
}

function continuousActionPriority(action = {}) {
  const priorities = new Map([
    ["continuous-worker-answer-question", 10],
    ["continuous-worker-prompt-probe", 15],
    ["continuous-worker-submit-pending", 20],
    ["continuous-worker-code-review-request", 27],
    ["continuous-worker-code-review-request-prepared", 27],
    ["continuous-worker-code-review-no-reviewer", 28],
    ["continuous-lane-advance-apply", 29],
    ["continuous-worker-warm", 30],
    ["continuous-worker-handoff", 31],
    ["continuous-worker-progress-signal", 32],
    ["continuous-dispatch-apply", 33],
    ["continuous-refill-apply", 34],
    ["continuous-worker-prompt-idle-progress-signal", 35],
    ["continuous-worker-recovery-inspection", 55],
    ["continuous-worker-retire", 60],
    ["continuous-worker-retire-blocked-question", 61],
  ]);
  return priorities.get(action.code) ?? 100;
}

function continuousActionAllowedByContinuation(action = {}, cycle = {}) {
  const continuation = cycle.summary?.continuation || {};
  const attentionPolicy = cycle.summary?.reviewResourcePolicy?.managerLoopBinding || {};
  if (Number(attentionPolicy.operatorInterruptionCount || 0) > 0 && action.code === "continuous-worker-answer-question") {
    return false;
  }
  const mutationClass = String(action.mutationClass || "");
  if (continuation.workerMutationAllowed === false && mutationClass.startsWith("manager_owned_worker_")) {
    return false;
  }
  if (continuation.dispatchApplyAllowed === false && action.mutationClass === "assignment_workspace_claim_only") {
    return false;
  }
  return true;
}

function continuousActionAllowedByOperationalCapability(action = {}, cycle = {}) {
  if (action.readOnly === true || !action.mutationClass) return true;
  const readiness = cycle.summary?.operationalActions || null;
  if (!readiness) return true;
  const actionId = operationalActionIdForContinuousMutation(action);
  if (!actionId) return operationalReadinessFreshAndComplete(readiness) && existingGateContinuousMutationAllowed(action);
  return operationalActionCapabilityAllows(cycle, actionId);
}

function operationalActionIdForContinuousMutation(action = {}) {
  switch (action.code) {
    case "continuous-dispatch-apply":
      return "dispatch_apply";
    case "continuous-worker-retire":
      return "kill_worker";
    case "continuous-refill-apply":
      return "mutate_source";
    case "continuous-worker-recovery-inspection":
    case "continuous-lane-advance-apply":
    case "continuous-bmad-code-review-request":
      return "refresh_projection";
    default:
      return null;
  }
}

function existingGateContinuousMutationAllowed(action = {}) {
  return [
    "continuous-worker-answer-question",
    "continuous-worker-prompt-probe",
    "continuous-worker-submit-pending",
    "continuous-worker-warm",
    "continuous-worker-handoff",
    "continuous-worker-progress-signal",
    "continuous-worker-prompt-idle-progress-signal",
  ].includes(action.code);
}

function operationalActionCapabilityAllows(cycle = {}, actionId = "") {
  const readiness = cycle.summary?.operationalActions || null;
  if (!operationalReadinessFreshAndComplete(readiness)) return false;
  if (actionId === "dispatch_apply" && (!isTrustedOperationalReadiness(readiness) || readiness.operationalMode !== "bounded_write")) return false;
  const capabilities = Array.isArray(readiness?.actionCapabilities) ? readiness.actionCapabilities : [];
  const capability = capabilities.find((candidate) => candidate?.actionId === actionId);
  if (!capability) return false;
  if (actionId === "dispatch_apply" && !operationalDispatchCapabilityContractValid(capability)) return false;
  return (
    capability.capabilityState === "available" &&
    capability.authorityState === "allowed" &&
    capability.typedReason === null &&
    capability.metadataOnly === true &&
    capability.rawPayloadRetained === false &&
    Array.isArray(capability.evidenceRefs) &&
    capability.evidenceRefs.length > 0 &&
    operationalCapabilityEvidenceAllows(capability, cycle)
  );
}

function markTrustedOperationalReadiness(readiness = null, proof = {}) {
  if (!readiness || typeof readiness !== "object") return;
  try {
    Object.defineProperty(readiness, TRUSTED_OPERATIONAL_READINESS, {
      value: Object.freeze({ ...(proof || {}) }),
      enumerable: false,
      configurable: false,
      writable: false,
    });
  } catch {
    // Trust marks are best-effort and must never weaken the fail-closed gate.
  }
}

function isTrustedOperationalReadiness(readiness = null) {
  try {
    return Boolean(readiness && typeof readiness === "object" && readiness[TRUSTED_OPERATIONAL_READINESS]);
  } catch {
    return false;
  }
}

function trustedOperationalReadinessProof(readiness = null) {
  try {
    return readiness && typeof readiness === "object" ? readiness[TRUSTED_OPERATIONAL_READINESS] || null : null;
  } catch {
    return null;
  }
}

function markTrustedDispatchPreviewAuthority(dispatchPreview = null) {
  if (!dispatchPreview || typeof dispatchPreview !== "object") return;
  try {
    TRUSTED_DISPATCH_PREVIEW_AUTHORITY_RECORDS.add(dispatchPreview);
  } catch {
    // WeakSet trust marks are best-effort and must fail closed if unavailable.
  }
  try {
    Object.defineProperty(dispatchPreview, TRUSTED_DISPATCH_PREVIEW_AUTHORITY, {
      value: true,
      enumerable: false,
      configurable: false,
      writable: false,
    });
  } catch {
    // Symbol trust marks are best-effort; frozen packets still use WeakSet trust.
  }
}

function isTrustedDispatchPreviewAuthority(dispatchPreview = null) {
  try {
    const producer = safeReadProperty(dispatchPreview?.summary?.operationalDispatchAuthority || {}, "producer", "");
    return Boolean(
      dispatchPreview &&
        typeof dispatchPreview === "object" &&
        (producer === "codex-workspace-dispatch-next-dry-run" ||
          dispatchPreview[TRUSTED_DISPATCH_PREVIEW_AUTHORITY] ||
          TRUSTED_DISPATCH_PREVIEW_AUTHORITY_RECORDS.has(dispatchPreview)),
    );
  } catch {
    return false;
  }
}

function bindTrustedOperationalDispatchAuthority(readiness = null, dispatchPreview = {}) {
  if (!isTrustedDispatchPreviewAuthority(dispatchPreview)) return null;
  const summary = dispatchPreview.summary || {};
  const authority = normalizeOperationalDispatchAuthority(summary?.operationalDispatchAuthority, summary);
  if (!authority || !readiness || typeof readiness !== "object") return null;
  if (readiness.readinessState !== "ready" || readiness.capabilityState !== "available" || readiness.freshnessState !== "live") return null;
  if (readiness.typedReason !== null) return null;
  const capabilities = Array.isArray(readiness.actionCapabilities) ? readiness.actionCapabilities : [];
  const capability = capabilities.find((candidate) => candidate?.actionId === "dispatch_apply");
  if (!capability || typeof capability !== "object") return null;
  capability.targetType = authority.targetType;
  capability.targetId = authority.targetId;
  capability.capabilityState = "available";
  capability.authorityState = "allowed";
  capability.riskTier = "high";
  capability.typedReason = null;
  capability.expectedResultSummary = "Apply dispatch decision for the selected work item through bounded write authority proof.";
  capability.evidenceRefs = uniqueStrings([...(Array.isArray(capability.evidenceRefs) ? capability.evidenceRefs : []), ...authority.evidenceRefs]);
  readiness.operationalMode = "bounded_write";
  readiness.summary = "Bounded-write operational action readiness is available for the selected dispatch work item.";
  return Object.freeze({
    actionId: "dispatch_apply",
    targetId: authority.targetId,
    targetType: authority.targetType,
    approvalEvidenceRef: authority.approvalEvidenceRef,
    evidenceRefs: Object.freeze([...authority.evidenceRefs]),
  });
}

function normalizeOperationalDispatchAuthority(authority = null, dispatchPreview = {}) {
  if (!authority || typeof authority !== "object") return null;
  const record = safePlainObjectSnapshot(authority);
  if (!record) return null;
  const selectedLane = safeDispatchWorkTargetString(dispatchPreview.selectedLane);
  if (dispatchPreview.allowed !== true || !selectedLane) return null;
  const targetId = safeDispatchWorkTargetString(safeReadProperty(record, "targetId", ""));
  if (!targetId || targetId !== selectedLane || !operationalIdentifierCanonical(targetId)) return null;
  const targetType = safeString(safeReadProperty(record, "targetType", "work_item"), "work_item");
  if (!["work_item", "candidate_work"].includes(targetType)) return null;
  const actionId = safeReadProperty(record, "actionId", "dispatch_apply");
  if (actionId && actionId !== "dispatch_apply") return null;
  if (safeReadProperty(record, "capabilityState", "") !== "available" || safeReadProperty(record, "authorityState", "") !== "allowed") return null;
  if (safeReadProperty(record, "riskTier", "") !== "high") return null;
  const approvalEvidenceRef = `evidence:capability-approval-needs_authority_approval:dispatch_apply:${operationalCapabilityContextToken(targetId)}`;
  if (safeReadProperty(record, "approvalEvidenceRef", "") !== approvalEvidenceRef) return null;
  const refs = Array.isArray(record.evidenceRefs) ? record.evidenceRefs : [];
  if (!refs.includes(approvalEvidenceRef)) return null;
  const safeRefs = refs.filter((ref) => typeof ref === "string" && ref.trim() === ref && OPERATIONAL_ACTION_EVIDENCE_REF.test(ref) && safeOperationalMetadataText(ref));
  if (safeRefs.length !== refs.length || safeRefs.length === 0 || safeRefs.length > 24) return null;
  return {
    actionId: "dispatch_apply",
    targetId,
    targetType,
    capabilityState: "available",
    authorityState: "allowed",
    riskTier: "high",
    approvalEvidenceRef,
    evidenceRefs: safeRefs,
    metadataOnly: true,
    rawPayloadRetained: false,
  };
}

function operationalDispatchCapabilityContractValid(capability = {}) {
  if (!capability || typeof capability !== "object" || Array.isArray(capability)) return false;
  const allowedKeys = new Set([
    "actionId",
    "targetType",
    "targetId",
    "capabilityState",
    "authorityState",
    "riskTier",
    "typedReason",
    "expectedResultSummary",
    "correlationRequired",
    "idempotencyRequired",
    "evidenceRefs",
    "metadataOnly",
    "rawPayloadRetained",
  ]);
  const entries = safeObjectEntries(capability);
  if (!entries || entries.some(([key]) => !allowedKeys.has(key))) return false;
  if (capability.actionId !== "dispatch_apply") return false;
  if (!["work_item", "candidate_work"].includes(capability.targetType)) return false;
  if (capability.capabilityState !== "available") return false;
  if (capability.authorityState !== "allowed") return false;
  if (capability.riskTier !== "high" && capability.riskTier !== "extreme") return false;
  if (capability.typedReason !== null) return false;
  if (capability.correlationRequired !== true || capability.idempotencyRequired !== true) return false;
  if (capability.metadataOnly !== true || capability.rawPayloadRetained !== false) return false;
  if (typeof capability.targetId !== "string" || !operationalIdentifierCanonical(capability.targetId)) return false;
  if (typeof capability.expectedResultSummary !== "string" || !safeOperationalMetadataText(capability.expectedResultSummary)) return false;
  const refs = Array.isArray(capability.evidenceRefs) ? capability.evidenceRefs : null;
  if (!refs || refs.length === 0 || refs.length > 24) return false;
  return refs.every((ref) => typeof ref === "string" && ref.trim() === ref && OPERATIONAL_ACTION_EVIDENCE_REF.test(ref) && safeOperationalMetadataText(ref));
}

function safeObjectEntries(value = {}) {
  try {
    return Object.entries(value);
  } catch {
    return null;
  }
}

function operationalIdentifierCanonical(value = "") {
  if (typeof value !== "string") return false;
  if (value.trim() !== value) return false;
  if (value.toLowerCase() !== value) return false;
  if (!OPERATIONAL_ACTION_IDENTIFIER.test(value)) return false;
  if (OPERATIONAL_ACTION_IDENTIFIER_REPEATED_SEPARATOR.test(value)) return false;
  if (OPERATIONAL_ACTION_IDENTIFIER_PATH_SEGMENT.test(value)) return false;
  return safeOperationalMetadataText(value);
}

function safeOperationalMetadataText(value = "") {
  try {
    const text = String(value);
    return (
      text.trim() === text &&
      text.length > 0 &&
      text.length <= 500 &&
      !/[\u0000-\u001f\u007f]/.test(text) &&
      !FORBIDDEN_OPERATIONAL_ACTION_METADATA.test(text) &&
      !SECRET_LIKE_OPERATIONAL_ACTION_REF.test(text)
    );
  } catch {
    return false;
  }
}

function operationalCapabilityEvidenceAllows(capability = {}, cycle = {}) {
  if (capability.actionId !== "dispatch_apply") return true;
  const proof = trustedOperationalReadinessProof(cycle.summary?.operationalActions || null)?.dispatchApply || null;
  if (!proof || proof.actionId !== "dispatch_apply") return false;
  const targetId = safeString(safeReadProperty(capability, "targetId", ""), "");
  if (!targetId || targetId !== proof.targetId || capability.targetType !== proof.targetType) return false;
  if (!operationalCapabilityMatchesSelectedDispatchTarget(targetId, cycle)) return false;
  const targetToken = operationalCapabilityContextToken(targetId);
  if (targetToken === "unknown-0") return false;
  const refs = Array.isArray(capability.evidenceRefs) ? capability.evidenceRefs : [];
  return refs.includes(proof.approvalEvidenceRef) && refs.includes(`evidence:capability-approval-needs_authority_approval:dispatch_apply:${targetToken}`);
}

function operationalCapabilityMatchesSelectedDispatchTarget(targetId = "", cycle = {}) {
  const target = safeDispatchWorkTargetString(targetId);
  if (!target) return false;
  const dispatchPreview = cycle.summary?.dispatchPreview || {};
  const dispatcher = cycle.summary?.dispatcher || {};
  const previewTargets = [
    dispatchPreview.selectedLane,
    dispatchPreview.selectedWorkItem,
    dispatchPreview.selectedWorkItemId,
    dispatchPreview.selectedTarget,
    dispatchPreview.selectedTargetId,
  ].map((value) => safeDispatchWorkTargetString(value)).filter(Boolean);
  const dispatcherTargets = [
    dispatcher.selectedLane,
    dispatcher.selectedWorkItem,
    dispatcher.selectedWorkItemId,
    dispatcher.selectedTarget,
    dispatcher.selectedTargetId,
  ].map((value) => safeDispatchWorkTargetString(value)).filter(Boolean);
  const previewTarget = previewTargets[0] || "";
  const dispatcherTarget = dispatcherTargets[0] || "";
  if (!previewTarget) return false;
  if (dispatcherTarget && dispatcherTarget !== previewTarget) return false;
  return target === previewTarget;
}

function safeDispatchWorkTargetString(value = "") {
  try {
    const text = String(value || "").trim();
    return operationalIdentifierCanonical(text) ? text : "";
  } catch {
    return "";
  }
}

function operationalCapabilityContextToken(value = "") {
  const text = safeString(value, "");
  if (!text || !/^[a-z0-9](?:[a-z0-9._/@:,-]{0,198}[a-z0-9])?$/i.test(text)) return "unknown-0";
  return boundedOperationalEvidenceToken(text);
}

function boundedOperationalEvidenceToken(value = "") {
  let hash = 0x811c9dc5;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193);
  }
  const normalized = value
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/-{2,}/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 24) || "id";
  return `${normalized}-${(hash >>> 0).toString(36).padStart(7, "0").slice(0, 7)}`;
}

function operationalReadinessFreshAndComplete(readiness = null) {
  if (!readiness || typeof readiness !== "object") return false;
  if (!operationalReadinessShapeValid(readiness)) return false;
  if (readiness.schemaVersion !== PIPELINE_OPERATIONAL_RUNTIME_READINESS_SCHEMA_VERSION) return false;
  if (readiness.actionSchemaVersion !== PIPELINE_OPERATIONAL_ACTION_SCHEMA_VERSION) return false;
  if (readiness.readinessState !== "ready") return false;
  if (!["read_only", "bounded_write"].includes(readiness.operationalMode)) return false;
  if (readiness.freshnessState !== "live") return false;
  if (readiness.capabilityState !== "available") return false;
  if (readiness.typedReason !== null) return false;
  if (readiness.metadataOnly !== true || readiness.rawPayloadRetained !== false) return false;
  if (!Array.isArray(readiness.evidenceRefs) || readiness.evidenceRefs.length === 0 || readiness.evidenceRefs.length > 24) return false;
  if (!readiness.evidenceRefs.every((ref) => typeof ref === "string" && ref.trim() === ref && OPERATIONAL_ACTION_EVIDENCE_REF.test(ref) && safeOperationalMetadataText(ref))) return false;
  const checkedAtMs = Date.parse(typeof readiness.checkedAt === "string" ? readiness.checkedAt : "");
  const expiresAtMs = Date.parse(typeof readiness.expiresAt === "string" ? readiness.expiresAt : "");
  const nowMs = Date.now();
  if (!Number.isFinite(checkedAtMs) || !Number.isFinite(expiresAtMs)) return false;
  if (checkedAtMs > expiresAtMs) return false;
  if (checkedAtMs > nowMs + OPERATIONAL_ACTION_READINESS_ALLOWED_FUTURE_SKEW_MS) return false;
  if (expiresAtMs - checkedAtMs > OPERATIONAL_ACTION_READINESS_TTL_MS) return false;
  if (expiresAtMs <= nowMs) return false;
  if (!Array.isArray(readiness.actionCapabilities)) return false;
  if (readiness.actionCapabilities.length !== PIPELINE_OPERATIONAL_ACTION_IDS.length) return false;
  const seen = new Set();
  for (const capability of readiness.actionCapabilities) {
    if (!capability || typeof capability !== "object") return false;
    if (!PIPELINE_OPERATIONAL_ACTION_IDS.includes(capability.actionId)) return false;
    if (seen.has(capability.actionId)) return false;
    seen.add(capability.actionId);
    if (capability.metadataOnly !== true || capability.rawPayloadRetained !== false) return false;
    if (capability.correlationRequired !== true || capability.idempotencyRequired !== true) return false;
    if (!operationalCapabilityShapeValid(capability)) return false;
  }
  const inspect = readiness.actionCapabilities.find((capability) => capability.actionId === "inspect");
  const refresh = readiness.actionCapabilities.find((capability) => capability.actionId === "refresh_projection");
  return (
    inspect?.capabilityState === "available" &&
    inspect?.authorityState === "allowed" &&
    inspect?.typedReason === null &&
    refresh?.capabilityState === "available" &&
    refresh?.authorityState === "allowed" &&
    refresh?.typedReason === null
  );
}

function operationalReadinessShapeValid(readiness = {}) {
  const allowedKeys = new Set([
    "schemaVersion",
    "actionSchemaVersion",
    "readinessState",
    "operationalMode",
    "freshnessState",
    "capabilityState",
    "typedReason",
    "checkedAt",
    "expiresAt",
    "summary",
    "actionCapabilities",
    "evidenceRefs",
    "metadataOnly",
    "rawPayloadRetained",
  ]);
  const entries = safeObjectEntries(readiness);
  if (!entries || entries.some(([key]) => !allowedKeys.has(key))) return false;
  return typeof readiness.summary === "string" && safeOperationalMetadataText(readiness.summary);
}

function operationalCapabilityShapeValid(capability = {}) {
  if (!capability || typeof capability !== "object" || Array.isArray(capability)) return false;
  const allowedKeys = new Set([
    "actionId",
    "targetType",
    "targetId",
    "capabilityState",
    "authorityState",
    "riskTier",
    "typedReason",
    "expectedResultSummary",
    "correlationRequired",
    "idempotencyRequired",
    "evidenceRefs",
    "metadataOnly",
    "rawPayloadRetained",
  ]);
  const entries = safeObjectEntries(capability);
  if (!entries || entries.some(([key]) => !allowedKeys.has(key))) return false;
  if (typeof capability.expectedResultSummary !== "string" || !safeOperationalMetadataText(capability.expectedResultSummary)) return false;
  const refs = Array.isArray(capability.evidenceRefs) ? capability.evidenceRefs : null;
  if (!refs || refs.length === 0 || refs.length > 24) return false;
  if (!refs.every((ref) => typeof ref === "string" && ref.trim() === ref && OPERATIONAL_ACTION_EVIDENCE_REF.test(ref) && safeOperationalMetadataText(ref))) return false;
  const availableAllowed = capability.capabilityState === "available" && capability.authorityState === "allowed";
  if (availableAllowed && capability.typedReason !== null) return false;
  if (["gated", "unavailable", "simulated"].includes(capability.capabilityState) && !capability.typedReason) return false;
  if (availableAllowed && ["medium", "high", "extreme"].includes(capability.riskTier)) {
    if (typeof capability.targetId !== "string" || !operationalIdentifierCanonical(capability.targetId)) return false;
  }
  return true;
}

function buildBlockedQuestionRetireContinuousActions(cycle = {}, questionAnswer = null, questionAnswerAvailable = true) {
  if (questionAnswerAvailable) return [];
  const blockedQuestions = Array.isArray(questionAnswer?.summary?.blockedQuestions) ? questionAnswer.summary.blockedQuestions : [];
  const unsafeBlocked = blockedQuestions.filter((question) =>
    question.decision === "block_unsafe_continuation" &&
    question.operatorInterruption === true &&
    Array.isArray(question.reasonCodes) &&
    question.reasonCodes.includes("unsafe_authority_request")
  );
  if (unsafeBlocked.length === 0) return [];
  return unsafeBlocked
    .slice(0, 6)
    .filter((question) => sanitizeLedgerField(question.workerId || question.worker_id || "", "", 80))
    .map((question) => {
      const workerId = sanitizeLedgerField(question.workerId || question.worker_id || "", "", 80);
      return {
        code: "worker-retire-blocked-question",
        summary: `Retire policy-blocked manager-owned worker ${workerId} after unsafe question classification.`,
        nextAction: appendManagerCommandScope(`node ./scripts/manager-worker-retire.mjs --summary-json --limit 1 --worker-id ${shellSingleQuote(workerId)} --retire-blocked-question`, cycleRunScope(cycle)),
      };
    });
}

function buildPromptIdleLoadActions(cycle = {}, promptProbe = {}) {
  const progressRows = Array.isArray(cycle.summary?.workerProgress?.workerProgress)
    ? cycle.summary.workerProgress.workerProgress
    : [];
  const promptIdleIds = new Set(
    (Array.isArray(promptProbe.summary?.probes) ? promptProbe.summary.probes : [])
      .filter((probe) => probe.promptDetected === true && probe.inputHasManagerPointer !== true)
      .map((probe) => String(probe.workerId || ""))
      .filter(Boolean),
  );
  if (promptIdleIds.size === 0 || progressRows.length === 0) return [];
  const promptIdleRows = progressRows.filter((worker) => promptIdleIds.has(String(worker.workerId || "")));
  const completedRows = promptIdleRows.filter((worker) => ["manager_review_ready", "delivery_gate_ready"].includes(worker.progressState));
  const laneAdvanceReady = Boolean(
    Number(cycle.summary?.laneAdvance?.readyLaneCount || 0) > 0 ||
    (Array.isArray(cycle.nextActions) && cycle.nextActions.some((action) => action.code === "manager-lane-advance-ready")),
  );
  const handoffIdleRows = promptIdleRows.filter((worker) =>
    worker.progressState === "handoff_sent" &&
    Number(worker.checkpointCount || 0) === 0 &&
    Number(worker.ageSeconds || 0) >= 15,
  );
  const checkpointIdleRows = promptIdleRows.filter((worker) =>
    worker.progressState === "checkpoint_seen" &&
    Number(worker.latestCheckpointAgeSeconds || 0) >= PROMPT_IDLE_CHECKPOINT_STALE_SECONDS,
  );
  const answeredQuestionIdleRows = promptIdleRows.filter((worker) =>
    worker.progressState === "question_answer_stale"
  );
  const reviewFeedbackIdleRows = promptIdleRows.filter((worker) =>
    worker.progressState === "review_feedback_stale"
  );
  const actions = [];
  if (completedRows.length > 0 && laneAdvanceReady) {
    actions.push({
    code: "manager-lane-advance-ready",
      summary: `Advance ${completedRows.length} prompt-idle completed worker lane(s) so workers can be reused.`,
      nextAction: appendManagerCommandScope(`node ./scripts/manager-lane-advance.mjs --summary-json --limit ${Math.min(6, completedRows.length)}`, cycleRunScope(cycle)),
    });
  } else if (completedRows.length > 0) {
    actions.push({
      code: "worker-code-review-ready",
      summary: `Delegate review-ready worker lane(s) to manager-owned worker code review.`,
      nextAction: appendManagerCommandScope("node ./scripts/manager-worker-code-review.mjs --summary-json", cycleRunScope(cycle)),
    });
  }
  const signalRows = [...handoffIdleRows, ...checkpointIdleRows, ...answeredQuestionIdleRows, ...reviewFeedbackIdleRows];
  if (signalRows.length > 0) {
    actions.push({
      code: signalRows.length === 1 ? `worker-progress-${signalRows[0].progressState}` : "worker-progress-prompt_idle",
      summary: `Signal ${signalRows.length} prompt-idle worker(s) for compact progress so idle panes do not wait for operator observation.`,
      nextAction: appendManagerCommandScope(`node ./scripts/manager-worker-progress-signal.mjs --summary-json --limit ${Math.min(6, signalRows.length)} --prompt-idle`, cycleRunScope(cycle)),
    });
  }
  return actions;
}

function buildContinuousDispatchRoutingHold(cycle = {}) {
  const dispatchAction = (Array.isArray(cycle.nextActions) ? cycle.nextActions : []).find((action) => action.code === "dispatch-preview-ready");
  if (!dispatchAction) return null;
  const decision = buildContinuousDispatchRoutingDecision(cycle);
  if (decision.allowed) return null;
  return {
    decision,
    nextAction: `Hold dispatch until usage/resource routing is ready: ${decision.blockedReasons.join(", ") || "routing blocked"}. Refresh usage/resource samples and rerun manager-cycle-packet.`,
  };
}

function buildContinuousDispatchRoutingDecision(cycle = {}) {
  const summary = cycle.summary || {};
  const usage = summary.usage || {};
  const resources = summary.resources || {};
  const dispatchPreview = summary.dispatchPreview || {};
  const owner = managerDispatcherOwner(summary.run?.runId || "manager-continuous");
  const readyQueueCount =
    dispatchPreviewCount({ summary: dispatchPreview }, "dispatchable") ??
    (dispatchPreview.selectedLane ? 1 : 0);
  return buildUsageResourceRoutingDecision({
    owner,
    readyQueueCount,
    usageSample: {
      state: mapUsageStateForRouting(usage.state),
      provider: usage.provider || "codex",
      remainingPercent: usage.remainingPercent,
      sampledAt: usage.sampledAt || usage.timestamp,
    },
    resourceSample: {
      state: mapResourceStateForRouting(resources.state),
      cpuLoadPercent: percentMetric(resources.cpuLoadPercent ?? resources.loadPercent, resources.loadRatio),
      memoryUsedPercent: percentMetric(resources.memoryUsedPercent, resources.usedMemoryRatio),
      sampledAt: resources.sampledAt || resources.timestamp,
    },
  });
}

function managerDispatcherOwner(runId = "") {
  const owner = sanitizeLedgerField(runId || "manager-continuous", "manager-continuous", 140);
  return owner.endsWith("/dispatcher") ? owner : `${owner}/dispatcher`;
}

function mapUsageStateForRouting(state = "unknown") {
  if (state === "normal") return "normal";
  if (["low", "conserve", "drain", "manager_only"].includes(state)) return state;
  if (state === "stale") return "stale";
  return "unknown";
}

function mapResourceStateForRouting(state = "unknown") {
  if (state === "normal") return "normal";
  if (["warm", "pressured", "critical", "high"].includes(state)) return state;
  if (state === "stale") return "stale";
  return "unknown";
}

function percentMetric(percentValue, ratioValue) {
  const percent = Number(percentValue);
  if (Number.isFinite(percent)) return percent;
  const ratio = Number(ratioValue);
  return Number.isFinite(ratio) ? Number((ratio * 100).toFixed(2)) : null;
}

function continuousWorkerCodeReviewAction(action = {}, cycle = {}, reviewPlan = {}) {
  const runId = sanitizeLedgerField(cycle.summary?.run?.runId || "", "", 120);
  const stateRoot = sanitizeLedgerField(cycle.summary?.run?.stateRoot || "", "", 260);
  const selectedStory = reviewPlan.summary?.selectedStory || {};
  const assignmentId = assignmentIdForStoryKey(selectedStory.storyKey || "");
  const reviewSummary = assignmentId
    ? `Delegate BMAD code review for ${assignmentId} to a manager-owned worker.`
    : "Delegate BMAD code review to a manager-owned worker.";
  const scopedRun = runId ? ` --run-id ${shellSingleQuote(runId)}` : "";
  const scopedStateRoot = stateRoot ? ` --state-root ${shellSingleQuote(stateRoot)}` : "";
  const scopedAssignment = assignmentId ? ` --assignment-id ${shellSingleQuote(assignmentId)}` : "";
  const workerReviewPlan = buildWorkerCodeReviewPlan(
    { ...(runId ? { runId } : {}), ...(stateRoot ? { stateRoot } : {}), ...(assignmentId ? { assignmentId } : {}) },
    { cyclePacket: cycle, reviewRequestPlan: reviewPlan, progressStatus: { summary: cycle.summary?.workerProgress || {} } },
  );
  const dryRunCommand = `node ./scripts/manager-worker-code-review.mjs --summary-json${scopedRun}${scopedStateRoot}${scopedAssignment}`;
  const request = workerReviewPlan.summary?.requests?.[0] || null;
  if (workerReviewPlan.status === "blocked") {
    return {
      code: "continuous-worker-code-review-no-reviewer",
      summary: "BMAD code review is ready, but no manager-owned reviewer worker is currently available.",
      dryRunCommand,
      applyCommand: "wait_for_or_warm_manager_owned_reviewer",
      authority: "manager-owned-worker-code-review-delegation-required",
      mutationClass: "none",
      readOnly: true,
      blockerCode: workerReviewPlan.blockers?.[0]?.code || "worker-code-review-no-reviewer",
      nextAction: workerReviewPlan.blockers?.[0]?.nextAction || "Wait for another prompt-idle manager-owned worker, warm a reviewer, or run review manually only by explicit operator choice.",
    };
  }
  if (workerReviewPlan.summary?.alreadyPrepared === true) {
    const requestAgeSeconds = Number(workerReviewPlan.summary?.requestAgeSeconds);
    const resultFresh = workerReviewPlan.summary?.resultFresh === true;
    const resendStaleSeconds = Number.isFinite(Number(cycle.summary?.reviewRequestResendStaleSeconds))
      ? Number(cycle.summary.reviewRequestResendStaleSeconds)
      : WORKER_CODE_REVIEW_RESEND_STALE_SECONDS;
    const shouldResend = !resultFresh && Number.isFinite(requestAgeSeconds) && requestAgeSeconds >= resendStaleSeconds;
    const workerFlag = request?.workerId ? ` --worker-id ${shellSingleQuote(request.workerId)}` : "";
    return {
      code: "continuous-worker-code-review-request-prepared",
      summary: shouldResend
        ? "Delegated worker code review request is stale without findings; resend the durable request pointer."
        : "Delegated worker code review request is already prepared.",
      dryRunCommand,
      applyCommand: shouldResend
        ? `${dryRunCommand}${workerFlag} --operator-visible-prompt --apply`
        : "monitor_delegated_worker_code_review",
      authority: "manager-owned-worker-code-review-delegation-existing-gates",
      mutationClass: "manager_owned_worker_code_review_delegation",
      readOnly: !shouldResend,
      reviewResultFresh: resultFresh,
    };
  }
  const workerFlag = request?.workerId ? ` --worker-id ${shellSingleQuote(request.workerId)}` : "";
  return {
    code: "continuous-worker-code-review-request",
    summary: reviewSummary,
    dryRunCommand,
    applyCommand: `${dryRunCommand}${workerFlag} --apply`,
    authority: "manager-owned-worker-code-review-delegation-existing-gates",
    mutationClass: "manager_owned_worker_code_review_delegation",
  };
}

function buildContinuousAction(action = {}, cycle = {}, capabilityPosture = {}) {
  const nextAction = String(action.nextAction || "").trim();
  if (action.code === "worker-prompt-probe-submit-ready" && nextAction.startsWith("node ./scripts/manager-worker-prompt-probe.mjs ")) {
    const dryRunCommand = nextAction.replace(/\s+--apply\b/g, "");
    return {
      code: "continuous-worker-prompt-probe",
      summary: action.summary || "Submit visible manager pointers in worker input regions.",
      dryRunCommand,
      applyCommand: nextAction.includes(" --apply") ? nextAction : `${nextAction} --apply`,
      authority: "manager-owned-worker-enter-only-repair-existing-gates",
      mutationClass: "manager_owned_worker_enter_only_prompt_region_probe",
    };
  }
  if (["worker-submit-pending-progress-signal", "worker-submit-pending-apply-ready"].includes(action.code) && nextAction.startsWith("node ./scripts/manager-worker-submit-pending.mjs ")) {
    const dryRunCommand = nextAction.replace(/\s+--apply\b/, "");
    return {
      code: "continuous-worker-submit-pending",
      summary: action.summary || "Submit pending manager-owned worker prompts.",
      dryRunCommand,
      applyCommand: nextAction.includes(" --apply") ? nextAction : `${nextAction} --apply`,
      authority: "manager-owned-worker-enter-only-repair-existing-gates",
      mutationClass: "manager_owned_worker_enter_only",
    };
  }
  if (action.code === "manager-owned-worker-warm-ready" && nextAction.startsWith("node ./scripts/manager-worker-warm.mjs ")) {
    return {
      code: "continuous-worker-warm",
      summary: action.summary || "Warm manager-owned replacement workers.",
      dryRunCommand: nextAction,
      applyCommand: nextAction.includes(" --apply") ? nextAction : `${nextAction} --apply`,
      authority: "manager-owned-worker-warm-existing-gates",
      mutationClass: "manager_owned_worker_warm",
    };
  }
  if (action.code === "worker-handoff-apply-ready" && nextAction.startsWith("node ./scripts/manager-worker-handoff.mjs ")) {
    const command = appendContinuousPostureFlags(nextAction, cycle);
    return {
      code: "continuous-worker-handoff",
      summary: action.summary || "Hand off work to warm manager-owned workers.",
      dryRunCommand: command.replace(/ --apply\b/g, ""),
      applyCommand: command.includes(" --apply") ? command : `${command} --apply`,
      authority: "manager-owned-worker-handoff-existing-gates",
      mutationClass: "manager_owned_worker_handoff",
    };
  }
  if (String(action.code || "").startsWith("worker-progress-") && nextAction.startsWith("node ./scripts/manager-worker-progress-signal.mjs ")) {
    const promptIdle = /\s--prompt-idle\b/.test(nextAction) || String(action.code || "").includes("prompt_idle");
    return {
      code: promptIdle ? "continuous-worker-prompt-idle-progress-signal" : "continuous-worker-progress-signal",
      summary: action.summary || "Signal stale manager-owned workers for compact progress.",
      dryRunCommand: nextAction,
      applyCommand: nextAction.includes(" --apply") ? nextAction : `${nextAction} --apply`,
      authority: "manager-owned-worker-progress-signal-existing-gates",
      mutationClass: "manager_owned_worker_progress_signal",
    };
  }
  if (action.code === "worker-code-review-ready" && nextAction.startsWith("node ./scripts/manager-worker-code-review.mjs ")) {
    const runId = sanitizeLedgerField(cycle.summary?.run?.runId || "", "", 120);
    const progressStatus = { summary: cycle.summary?.workerProgress || {} };
    const reviewPlan = buildBmadCodeReviewRequestPlan(runId ? { runId } : {}, { cyclePacket: cycle, progressStatus });
    if (reviewPlan.ok !== false && reviewPlan.status === "ready") {
      return continuousWorkerCodeReviewAction(action, cycle, reviewPlan);
    }
    return null;
  }
  if (action.code === "worker-progress-blocked_question" && nextAction.startsWith("node ./scripts/manager-worker-answer-question.mjs ")) {
    return {
      code: "continuous-worker-answer-question",
      summary: action.summary || "Answer compact manager-owned worker questions.",
      dryRunCommand: nextAction.replace(/ --apply\b/g, ""),
      applyCommand: nextAction.includes(" --apply") ? nextAction : `${nextAction} --apply`,
      authority: "manager-owned-worker-question-answer-existing-gates",
      mutationClass: "manager_owned_worker_question_answer",
    };
  }
  if (action.code === "worker-progress-progress_signal_unanswered" && nextAction.startsWith("node ./scripts/manager-worker-recovery-inspection.mjs ")) {
    return {
      code: "continuous-worker-recovery-inspection",
      summary: action.summary || "Inspect unanswered manager-owned worker progress signals.",
      dryRunCommand: nextAction.replace(/ --apply\b/g, ""),
      applyCommand: nextAction.includes(" --apply") ? nextAction : `${nextAction} --apply`,
      authority: "metadata-only-worker-recovery-inspection",
      mutationClass: "metadata_only_worker_recovery_inspection",
    };
  }
  if (action.code === "worker-progress-recovery_submit_unanswered" && nextAction.startsWith("node ./scripts/manager-worker-retire.mjs ")) {
    return {
      code: "continuous-worker-retire",
      summary: action.summary || "Retire recovery-stuck manager-owned worker.",
      dryRunCommand: nextAction,
      applyCommand: nextAction.includes(" --apply") ? nextAction : `${nextAction} --apply`,
      authority: "manager-owned-worker-retire-after-recovery-existing-gates",
      mutationClass: "manager_owned_worker_retire",
    };
  }
  if (action.code === "worker-retire-blocked-question" && nextAction.startsWith("node ./scripts/manager-worker-retire.mjs ")) {
    return {
      code: "continuous-worker-retire-blocked-question",
      summary: action.summary || "Retire policy-blocked manager-owned worker.",
      dryRunCommand: nextAction,
      applyCommand: nextAction.includes(" --apply") ? nextAction : `${nextAction} --apply`,
      authority: "manager-owned-worker-retire-after-policy-blocked-question-existing-gates",
      mutationClass: "manager_owned_worker_retire",
    };
  }
  if (action.code === "manager-lane-advance-ready" && nextAction.startsWith("node ./scripts/manager-lane-advance.mjs ")) {
    const runId = sanitizeLedgerField(cycle.summary?.run?.runId || "", "", 120);
    const progressStatus = { summary: cycle.summary?.workerProgress || {} };
    const reviewPlan = buildBmadCodeReviewRequestPlan(runId ? { runId } : {}, { cyclePacket: cycle, progressStatus });
    const reviewDelegationState = capabilityPosture.capabilities?.reviewDelegation?.state || "enabled";
    const hasWorkerProgressSignal = Array.isArray(cycle.nextActions)
      && cycle.nextActions.some((candidate) =>
        String(candidate?.code || "").startsWith("worker-progress-") &&
        String(candidate?.nextAction || "").startsWith("node ./scripts/manager-worker-progress-signal.mjs "),
      );
    const hasWorkerProgressRows = Array.isArray(cycle.summary?.workerProgress?.workerProgress)
      && cycle.summary.workerProgress.workerProgress.length > 0;
    if (!["parked", "blocked"].includes(reviewDelegationState) && reviewPlan.ok !== false && reviewPlan.status === "ready") {
      const reviewAction = continuousWorkerCodeReviewAction(action, cycle, reviewPlan);
      if (reviewAction?.reviewResultFresh === true) {
        return null;
      }
      if (reviewAction?.readOnly === true && hasWorkerProgressSignal) {
        return null;
      }
      if (reviewAction && reviewAction.readOnly !== true) {
        return reviewAction;
      }
    }
    if (hasWorkerProgressSignal && hasWorkerProgressRows) {
      return null;
    }
    return {
      code: "continuous-lane-advance-apply",
      summary: action.summary || "Advance review-ready lanes into manager review or delivery metadata gates.",
      dryRunCommand: nextAction,
      applyCommand: nextAction.includes(" --apply") ? nextAction : `${nextAction} --apply`,
      authority: "manager-owned-lane-advancement-heartbeat-existing-gates",
      mutationClass: "assignment_heartbeat_metadata_only",
    };
  }
  if (action.code === "safe-backlog-starvation") {
    if (/\bbmad-code-review\b/.test(nextAction)) {
      const runId = sanitizeLedgerField(cycle.summary?.run?.runId || "", "", 120);
      const progressStatus = { summary: cycle.summary?.workerProgress || {} };
      const reviewPlan = buildBmadCodeReviewRequestPlan(runId ? { runId } : {}, { cyclePacket: cycle, progressStatus });
      if (reviewPlan.ok === false) {
        return null;
      }
      return continuousWorkerCodeReviewAction(action, cycle, reviewPlan);
    }
    const gate = action.materializationGate || null;
    const gateReady = gate?.state === "ready" || gate?.mutationMode === "dry_run_required";
    const dryRunCommand = String(gate?.dryRunCommand || "").trim();
    const applyCommand = String(gate?.applyCommand || "").trim();
    if (!gateReady || !dryRunCommand.startsWith("node ./scripts/manager-refill-plan.mjs ") || !applyCommand.startsWith("node ./scripts/manager-refill-plan.mjs ")) {
      return null;
    }
    return {
      code: "continuous-refill-apply",
      summary: action.summary || "Materialize source-owned local refill artifacts through existing BMAD gates.",
      dryRunCommand,
      applyCommand,
      authority: "source-owned-refill-planning-existing-gates",
      mutationClass: "local_bmad_refill_artifacts",
    };
  }
  if (action.code === "dispatch-preview-ready") {
    if (!operationalActionCapabilityAllows(cycle, "dispatch_apply")) {
      return null;
    }
    const dispatcher = cycle.summary?.dispatcher || {};
    const dispatchPreview = cycle.summary?.dispatchPreview || {};
    if (dispatcher.allowed !== true || dispatchPreview.allowed !== true || !(dispatcher.selectedLane || dispatchPreview.selectedLane)) {
      return null;
    }
    const capacityDecision = buildContinuousDispatchCapacityDecision(cycle);
    if (!capacityDecision.allowed) return null;
    const routingDecision = buildContinuousDispatchRoutingDecision(cycle);
    if (!routingDecision.allowed) return null;
    const dryRunCommand = routingDecision.selectedAction.command;
    const applyCommand = `${dryRunCommand.replace(/\s--dry-run\b/g, "")} --apply`;
    return {
      code: "continuous-dispatch-apply",
      summary: action.summary || "Claim the next source-owned safe backlog lane through existing dispatch gates.",
      dryRunCommand,
      applyCommand,
      authority: "codex-workspace-dispatch-existing-gates",
      mutationClass: "assignment_workspace_claim_only",
      routingDecision: { ...routingDecision, capacityDecision },
    };
  }
  return null;
}

function buildContinuousDispatchCapacityDecision(cycle = {}) {
  const workers = cycle.summary?.workers?.workerCounts || {};
  const active = nonNegativeInteger(workers.active) ?? 0;
  const warm = nonNegativeInteger(workers.warm) ?? 0;
  const paused = nonNegativeInteger(workers.paused) ?? 0;
  const maxWorkers = Math.max(1, nonNegativeInteger(cycle.summary?.workers?.targets?.maxTarget) ?? 6);
  const activeCapacity = Math.max(0, maxWorkers - active - paused);
  const allowed = warm > 0 || activeCapacity > 0;
  return {
    allowed,
    active,
    warm,
    paused,
    maxWorkers,
    activeCapacity,
    policy: "dispatch_requires_warm_worker_or_available_active_worker_capacity",
    blockedReasons: allowed ? [] : ["worker_capacity_full"],
  };
}

function appendContinuousPostureFlags(command = "", cycle = {}) {
  const usageState = sanitizeContinuousFlagValue(cycle.summary?.usage?.state);
  const resourceState = sanitizeContinuousFlagValue(cycle.summary?.resources?.state);
  let next = String(command || "");
  if (usageState && !/\s--usage-state(?:=|\s)/.test(next)) {
    next += ` --usage-state ${usageState}`;
  }
  if (resourceState && !/\s--resource-state(?:=|\s)/.test(next)) {
    next += ` --resource-state ${resourceState}`;
  }
  return next;
}

function sanitizeContinuousFlagValue(value = "") {
  const text = String(value || "").trim();
  return /^[A-Za-z0-9_-]+$/.test(text) ? text : "";
}

function buildContinuationPlan({ status, blockers = [], runway = {}, usage = {}, resources = {}, workers = {}, resume = {}, dispatchPreview = {}, operationalActions = null } = {}) {
  const blockerCodes = blockers.map((blocker) => blocker.code).filter(Boolean);
  const usageState = normalizePosture(usage, "unknown");
  const resourceState = normalizePosture(resources, "unknown");
  if (blockerCodes.includes("split-brain-state")) {
    return {
      state: "blocked",
      canContinue: false,
      progressRunState: "blocked",
      workerMutationAllowed: false,
      workerStartAllowed: false,
      dispatchApplyAllowed: false,
      allowedActions: ["status_reporting", "read_only_inspection"],
      blockedActions: ["worker_start", "worker_kill", "worker_answer", "lane_advance", "dispatch_apply", "delivery", "cleanup", "ownership_takeover"],
      reason: "Split-brain reconciliation is blocked; no manager mutation can run until state is parked or reconciled.",
      blockerCodes,
      blockedLaneAssignments: resume.summary?.assignment?.blockedLaneAssignments?.length || 0,
      blockedWorkspaceAssignments: resume.summary?.assignment?.blockedWorkspaceAssignments?.length || 0,
    };
  }
  const hardWorkerMutationBlockers = [
    "tmux-orientation-unavailable",
    "tmux-takeover-required",
    "worker-target-stop-line",
  ];
  const workerMutationBlocked = blockerCodes.some((code) =>
    [
      "assignment-ambiguous-status",
      ...hardWorkerMutationBlockers,
    ].includes(code),
  );
  const hardWorkerMutationBlocked = blockerCodes.some((code) => hardWorkerMutationBlockers.includes(code));
  const sourceBackedRefillAvailable = Boolean(
      runway.summary?.refillNeeded > 0 &&
      runway.summary?.sourceSlice &&
      runway.summary?.workCreationStep?.workCreationPacket &&
      !["manager_only", "unknown"].includes(usageState) &&
      !["critical"].includes(resourceState),
  );
  const blockedDeliveryTargets = new Set(
    blockers
      .filter((blocker) => ["delivery-phase-authority-missing", "delivery-phase-authority-invalid", "pr-stewardship-evidence-missing", "pr-stewardship-high-risk", "feedback-blocking-delivery"].includes(blocker.code))
      .flatMap((blocker) => [blocker.affectedLane, blocker.affectedBranch])
      .map((value) => String(value || "").trim())
      .filter(Boolean),
  );
  const dispatchSelectedTargets = [
    dispatchPreview.summary?.selectedLane,
  ].map((value) => String(value || "").trim()).filter(Boolean);
  const dispatchTargetsDeliveryBlocked = dispatchSelectedTargets.some((target) => blockedDeliveryTargets.has(target));
  const safeDispatchApplyAvailable = Boolean(
    dispatchPreview.summary?.allowed === true &&
    dispatchPreview.summary?.selectedLane &&
    dispatchPreview.summary?.claimMutation &&
    operationalActionCapabilityAllows({ summary: { operationalActions, dispatchPreview: dispatchPreview.summary } }, "dispatch_apply") &&
    !dispatchTargetsDeliveryBlocked &&
    !["manager_only", "drain", "unknown"].includes(usageState) &&
    !["critical", "pressured", "unknown"].includes(resourceState),
  );
  const activeWorkerCount = nonNegativeInteger(workers.summary?.workerCounts?.active) ?? 0;
  const warmWorkerCount = nonNegativeInteger(workers.summary?.workerCounts?.warm) ?? 0;
  const onlyStaleOwnershipBlocked = blockerCodes.length > 0 && blockerCodes.every((code) => code === "assignment-ambiguous-status");
  const onlyRetryParkedLaneBlocked = blockerCodes.length > 0 && blockerCodes.every((code) => code === "retry-route-park-lane");
  const onlyWorkerQuestionBlocked = blockerCodes.length > 0 && blockerCodes.every((code) => code === "worker-question-operator-interruption");
  const deliveryAuthorityBlockerCodes = new Set(["delivery-phase-authority-missing", "delivery-phase-authority-invalid"]);
  const prStewardshipBlockerCodes = new Set(["pr-stewardship-evidence-missing", "pr-stewardship-high-risk"]);
  const feedbackDeliveryBlockerCodes = new Set(["feedback-blocking-delivery"]);
  const onlyDeliveryAuthorityBlocked = blockerCodes.length > 0 && blockerCodes.every((code) => deliveryAuthorityBlockerCodes.has(code));
  const onlyPrStewardshipBlocked = blockerCodes.length > 0 && blockerCodes.every((code) => prStewardshipBlockerCodes.has(code));
  const onlyFeedbackDeliveryBlocked = blockerCodes.length > 0 && blockerCodes.every((code) => feedbackDeliveryBlockerCodes.has(code));
  const onlyDeliveryScopedBlocked = blockerCodes.length > 0 && blockerCodes.every((code) => deliveryAuthorityBlockerCodes.has(code) || prStewardshipBlockerCodes.has(code));
  const managerOwnedWarmStartAvailable = Boolean(
      !hardWorkerMutationBlocked &&
      workers.summary?.lifecyclePlan?.startWarmCandidates?.length > 0 &&
      !["manager_only", "drain", "unknown"].includes(usageState) &&
      !["critical", "unknown"].includes(resourceState),
  );
  if (activeWorkerCount > 0 && onlyStaleOwnershipBlocked && resourceState !== "critical") {
    if (managerOwnedWarmStartAvailable) {
      return {
        state: "worker_warm_ready",
        canContinue: true,
        progressRunState: "worker-warm-ready",
        workerMutationAllowed: true,
        workerStartAllowed: true,
        dispatchApplyAllowed: false,
        allowedActions: ["manager_owned_worker_warm_existing_gates", "active_worker_monitoring", "status_reporting", "read_only_inspection"],
        blockedActions: ["worker_kill", "dispatch_apply", "ownership_takeover"],
        reason: "Active manager-owned workers can continue and retired capacity can be replaced through manager-owned warm gates while stale ownership remains blocked for takeover.",
        startWarmCandidates: workers.summary.lifecyclePlan.startWarmCandidates.length,
        activeWorkers: activeWorkerCount,
        warmWorkers: warmWorkerCount,
        blockerCodes,
        blockedLaneAssignments: resume.summary?.assignment?.blockedLaneAssignments?.length || 0,
        blockedWorkspaceAssignments: resume.summary?.assignment?.blockedWorkspaceAssignments?.length || 0,
      };
    }
    const allowedActions = ["active_worker_monitoring", "feedback_routing", "status_reporting", "read_only_inspection"];
    const blockedActions = ["worker_kill", "ownership_takeover"];
    if (safeDispatchApplyAvailable) {
      allowedActions.unshift("dispatch_apply_existing_gates");
    } else {
      blockedActions.push("dispatch_apply");
    }
    return {
      state: safeDispatchApplyAvailable ? "dispatch_or_active_monitoring" : "active_worker_monitoring",
      canContinue: true,
      progressRunState: safeDispatchApplyAvailable ? "dispatch-ready" : "active",
      workerMutationAllowed: false,
      workerStartAllowed: warmWorkerCount > 0,
      dispatchApplyAllowed: safeDispatchApplyAvailable,
      allowedActions,
      blockedActions,
      reason: safeDispatchApplyAvailable
        ? "Active manager-owned workers can continue, and existing dispatch gates have selected a safe lane for assignment/workspace preparation while takeover and worker kill remain blocked."
        : "Active manager-owned workers can continue while stale ownership inspection remains blocked for takeover, dispatch apply, and worker kill.",
      selectedLane: safeDispatchApplyAvailable ? dispatchPreview.summary?.selectedLane || null : undefined,
      selectedBranch: safeDispatchApplyAvailable ? dispatchPreview.summary?.selectedBranch || null : undefined,
      activeWorkers: activeWorkerCount,
      warmWorkers: warmWorkerCount,
      blockerCodes,
      blockedLaneAssignments: resume.summary?.assignment?.blockedLaneAssignments?.length || 0,
      blockedWorkspaceAssignments: resume.summary?.assignment?.blockedWorkspaceAssignments?.length || 0,
    };
  }
  if (status === "ready" && managerOwnedWarmStartAvailable && !workerMutationBlocked && resourceState !== "critical") {
    return {
      state: "worker_warm_ready",
      canContinue: true,
      progressRunState: "worker-warm-ready",
      workerMutationAllowed: true,
      workerStartAllowed: true,
      dispatchApplyAllowed: false,
      allowedActions: ["manager_owned_worker_warm_existing_gates", "status_reporting", "read_only_inspection"],
      blockedActions: ["worker_kill", "ownership_takeover"],
      reason: "Usage, resource, tmux, and worker target gates allow manager-owned warm starts.",
      startWarmCandidates: workers.summary.lifecyclePlan.startWarmCandidates.length,
      activeWorkers: activeWorkerCount,
      warmWorkers: warmWorkerCount,
      blockerCodes,
      blockedLaneAssignments: resume.summary?.assignment?.blockedLaneAssignments?.length || 0,
      blockedWorkspaceAssignments: resume.summary?.assignment?.blockedWorkspaceAssignments?.length || 0,
    };
  }
  if (managerOwnedWarmStartAvailable && workerMutationBlocked && resourceState !== "critical") {
    return {
      state: "worker_warm_ready",
      canContinue: true,
      progressRunState: "worker-warm-ready",
      workerMutationAllowed: true,
      workerStartAllowed: true,
      dispatchApplyAllowed: false,
      allowedActions: ["manager_owned_worker_warm_existing_gates", "status_reporting", "read_only_inspection"],
      blockedActions: ["worker_kill", "dispatch_apply", "ownership_takeover"],
      reason: "Stale ownership still requires inspection before takeover or dispatch apply, but manager-owned warm starts can proceed through existing worker gates.",
      startWarmCandidates: workers.summary.lifecyclePlan.startWarmCandidates.length,
      blockerCodes,
      blockedLaneAssignments: resume.summary?.assignment?.blockedLaneAssignments?.length || 0,
      blockedWorkspaceAssignments: resume.summary?.assignment?.blockedWorkspaceAssignments?.length || 0,
    };
  }
  if (sourceBackedRefillAvailable && !safeDispatchApplyAvailable && resourceState !== "critical") {
    return {
      state: "planning_only",
      canContinue: true,
      progressRunState: "planning",
      workerMutationAllowed: false,
      dispatchApplyAllowed: false,
      allowedActions: ["source_owned_bmad_refill_planning", "status_reporting", "read_only_inspection"],
      blockedActions: ["worker_start", "worker_kill", "dispatch_apply", "ownership_takeover"],
      reason: "Safe backlog is below target, and source-owned backlog creation can continue from the compact BMAD handoff.",
      blockerCodes,
      blockedLaneAssignments: resume.summary?.assignment?.blockedLaneAssignments?.length || 0,
      blockedWorkspaceAssignments: resume.summary?.assignment?.blockedWorkspaceAssignments?.length || 0,
    };
  }
  if ((sourceBackedRefillAvailable || safeDispatchApplyAvailable) && workerMutationBlocked && resourceState !== "critical") {
    const allowedActions = ["source_owned_bmad_refill_planning", "status_reporting", "read_only_inspection"];
    const blockedActions = ["worker_start", "worker_kill", "ownership_takeover"];
    if (safeDispatchApplyAvailable) {
      allowedActions.unshift("dispatch_apply_existing_gates");
    } else {
      blockedActions.push("dispatch_apply");
    }
    return {
      state: safeDispatchApplyAvailable ? "dispatch_or_planning" : "planning_only",
      canContinue: true,
      progressRunState: safeDispatchApplyAvailable ? "dispatch-ready" : "planning",
      workerMutationAllowed: false,
      dispatchApplyAllowed: safeDispatchApplyAvailable,
      allowedActions,
      blockedActions,
      reason: safeDispatchApplyAvailable
        ? "Worker mutation is blocked, but existing dispatch gates have selected a safe lane for assignment/workspace preparation."
        : "Worker mutation is blocked, but source-owned backlog creation can continue from the compact BMAD handoff.",
      selectedLane: safeDispatchApplyAvailable ? dispatchPreview.summary?.selectedLane || null : undefined,
      selectedBranch: safeDispatchApplyAvailable ? dispatchPreview.summary?.selectedBranch || null : undefined,
      blockerCodes,
      blockedLaneAssignments: resume.summary?.assignment?.blockedLaneAssignments?.length || 0,
      blockedWorkspaceAssignments: resume.summary?.assignment?.blockedWorkspaceAssignments?.length || 0,
    };
  }
  if (onlyWorkerQuestionBlocked && resourceState !== "critical") {
    const allowedActions = ["operator_interruption_for_dependent_worker", "status_reporting", "read_only_inspection"];
    const blockedActions = ["dependent_worker_continuation"];
    if (safeDispatchApplyAvailable) {
      allowedActions.push("dispatch_apply_existing_gates");
    } else {
      blockedActions.push("dispatch_apply");
    }
    if (sourceBackedRefillAvailable) allowedActions.push("source_owned_bmad_refill_planning");
    return {
      state: "worker_question_blocked",
      canContinue: true,
      progressRunState: "worker-question-blocked",
      workerMutationAllowed: false,
      dispatchApplyAllowed: safeDispatchApplyAvailable,
      allowedActions,
      blockedActions,
      reason: "A worker question requires operator authority, but the blocker is scoped to the affected worker or lane and unrelated safe work can continue through existing gates.",
      selectedLane: safeDispatchApplyAvailable ? dispatchPreview.summary?.selectedLane || null : undefined,
      selectedBranch: safeDispatchApplyAvailable ? dispatchPreview.summary?.selectedBranch || null : undefined,
      blockerCodes,
      blockedLaneAssignments: resume.summary?.assignment?.blockedLaneAssignments?.length || 0,
      blockedWorkspaceAssignments: resume.summary?.assignment?.blockedWorkspaceAssignments?.length || 0,
    };
  }
  if (onlyFeedbackDeliveryBlocked && resourceState !== "critical") {
    const allowedActions = ["feedback_routing", "status_reporting", "read_only_inspection"];
    const blockedActions = ["affected_delivery", "affected_pr_merge"];
    if (safeDispatchApplyAvailable) {
      allowedActions.push("dispatch_apply_existing_gates");
    } else {
      blockedActions.push("dispatch_apply");
    }
    if (sourceBackedRefillAvailable) allowedActions.push("source_owned_bmad_refill_planning");
    return {
      state: "feedback_delivery_blocked",
      canContinue: true,
      progressRunState: "feedback-delivery-blocked",
      workerMutationAllowed: false,
      dispatchApplyAllowed: safeDispatchApplyAvailable,
      allowedActions,
      blockedActions,
      reason: "Blocking feedback pauses affected delivery and PR merge, but unrelated safe work can continue through existing gates.",
      selectedLane: safeDispatchApplyAvailable ? dispatchPreview.summary?.selectedLane || null : undefined,
      selectedBranch: safeDispatchApplyAvailable ? dispatchPreview.summary?.selectedBranch || null : undefined,
      blockerCodes,
      blockedLaneAssignments: resume.summary?.assignment?.blockedLaneAssignments?.length || 0,
      blockedWorkspaceAssignments: resume.summary?.assignment?.blockedWorkspaceAssignments?.length || 0,
    };
  }
  if (onlyDeliveryScopedBlocked && !onlyDeliveryAuthorityBlocked && !onlyPrStewardshipBlocked && resourceState !== "critical") {
    const allowedActions = ["delivery_authority_operator_interruption", "pr_stewardship_operator_interruption", "status_reporting", "read_only_inspection"];
    const blockedActions = ["pr_create", "pr_update", "delivery", "cleanup", "dispatch_apply"];
    if (sourceBackedRefillAvailable) allowedActions.push("source_owned_bmad_refill_planning");
    return {
      state: "delivery_scoped_blocked",
      canContinue: false,
      progressRunState: "delivery-scoped-blocked",
      workerMutationAllowed: false,
      dispatchApplyAllowed: false,
      allowedActions,
      blockedActions,
      reason: "Delivery authority or PR stewardship evidence is blocked for the affected lane, but the blocker is scoped to delivery and unrelated safe work can continue through existing gates.",
      blockerCodes,
      blockedLaneAssignments: resume.summary?.assignment?.blockedLaneAssignments?.length || 0,
      blockedWorkspaceAssignments: resume.summary?.assignment?.blockedWorkspaceAssignments?.length || 0,
    };
  }
  if (onlyDeliveryAuthorityBlocked && resourceState !== "critical") {
    const allowedActions = ["delivery_authority_operator_interruption", "status_reporting", "read_only_inspection"];
    const blockedActions = ["delivery", "cleanup", "dispatch_apply"];
    if (sourceBackedRefillAvailable) allowedActions.push("source_owned_bmad_refill_planning");
    return {
      state: "delivery_authority_blocked",
      canContinue: false,
      progressRunState: "delivery-authority-blocked",
      workerMutationAllowed: false,
      dispatchApplyAllowed: false,
      allowedActions,
      blockedActions,
      reason: "Delivery requires an active delivery_phase contract, but the blocker is scoped to delivery and unrelated safe work can continue through existing gates.",
      blockerCodes,
      blockedLaneAssignments: resume.summary?.assignment?.blockedLaneAssignments?.length || 0,
      blockedWorkspaceAssignments: resume.summary?.assignment?.blockedWorkspaceAssignments?.length || 0,
    };
  }
  if (onlyPrStewardshipBlocked && resourceState !== "critical") {
    const allowedActions = ["pr_stewardship_operator_interruption", "status_reporting", "read_only_inspection"];
    const blockedActions = ["pr_create", "pr_update", "delivery", "dispatch_apply"];
    if (sourceBackedRefillAvailable) allowedActions.push("source_owned_bmad_refill_planning");
    return {
      state: "pr_stewardship_blocked",
      canContinue: false,
      progressRunState: "pr-stewardship-blocked",
      workerMutationAllowed: false,
      dispatchApplyAllowed: false,
      allowedActions,
      blockedActions,
      reason: "PR creation or update requires scoped dry-run evidence and delivery authority, but the blocker is scoped to delivery and unrelated safe work can continue through existing gates.",
      blockerCodes,
      blockedLaneAssignments: resume.summary?.assignment?.blockedLaneAssignments?.length || 0,
      blockedWorkspaceAssignments: resume.summary?.assignment?.blockedWorkspaceAssignments?.length || 0,
    };
  }
  if (onlyRetryParkedLaneBlocked && (sourceBackedRefillAvailable || safeDispatchApplyAvailable) && resourceState !== "critical") {
    const allowedActions = ["status_reporting", "read_only_inspection"];
    const blockedActions = ["worker_kill", "ownership_takeover"];
    if (safeDispatchApplyAvailable) {
      allowedActions.unshift("dispatch_apply_existing_gates");
    } else {
      blockedActions.push("dispatch_apply");
    }
    if (sourceBackedRefillAvailable) {
      allowedActions.unshift("source_owned_bmad_refill_planning");
    } else {
      blockedActions.push("worker_start");
    }
    return {
      state: safeDispatchApplyAvailable ? "dispatch_or_planning" : "planning_only",
      canContinue: true,
      progressRunState: safeDispatchApplyAvailable ? "dispatch-ready" : "planning",
      workerMutationAllowed: false,
      dispatchApplyAllowed: safeDispatchApplyAvailable,
      allowedActions,
      blockedActions,
      reason: "A retry lane is parked with visible resume criteria, but unrelated safe work can continue through existing dispatcher/refill gates.",
      selectedLane: safeDispatchApplyAvailable ? dispatchPreview.summary?.selectedLane || null : undefined,
      selectedBranch: safeDispatchApplyAvailable ? dispatchPreview.summary?.selectedBranch || null : undefined,
      blockerCodes,
      blockedLaneAssignments: resume.summary?.assignment?.blockedLaneAssignments?.length || 0,
      blockedWorkspaceAssignments: resume.summary?.assignment?.blockedWorkspaceAssignments?.length || 0,
    };
  }
  return {
    state: status,
    canContinue: status !== "blocked",
    progressRunState: status,
    workerMutationAllowed: status !== "blocked",
    dispatchApplyAllowed: status !== "blocked" && safeDispatchApplyAvailable,
    allowedActions: status === "blocked" ? ["status_reporting", "read_only_inspection"] : ["governed_manager_actions"],
    blockedActions: status === "blocked"
      ? ["worker_start", "worker_kill", "dispatch_apply", "ownership_takeover"]
      : safeDispatchApplyAvailable
        ? []
        : ["dispatch_apply"],
    reason: status === "blocked" ? "Manager mutation is blocked until blockers are resolved." : "Manager can continue under existing governors.",
    blockerCodes,
    blockedLaneAssignments: resume.summary?.assignment?.blockedLaneAssignments?.length || 0,
    blockedWorkspaceAssignments: resume.summary?.assignment?.blockedWorkspaceAssignments?.length || 0,
  };
}

function recoveryBlocksManagerMutation(recovery = {}) {
  if (recovery.summary?.reconciliation?.status === "blocked") return true;
  if (recovery.summary?.autoRepair?.posture === "blocked") return true;
  const retryRoutes = Array.isArray(recovery.summary?.retryRoutes) ? recovery.summary.retryRoutes : [];
  if (retryRoutes.length === 0) return recovery.status === "blocked";
  return retryRoutes.some((route) => {
    const eligibleParallelWork = nonNegativeInteger(route?.unblockedParallelWork?.eligibleCount) ?? 0;
    if (route?.posture === "blocked") return true;
    if (route?.action === "park_lane" && eligibleParallelWork <= 0) return true;
    return false;
  });
}

function applySteeringToDispatchPosture(dispatchPosture, steeringSummary = {}) {
  const futureDispatch = steeringSummary.futureDispatch || {};
  if (!futureDispatch.action || futureDispatch.action === "keep_current_dispatch") return dispatchPosture;
  if (futureDispatch.scope === "report-only" || futureDispatch.scope === "clarification-only") return dispatchPosture;
  const summary = {
    ...dispatchPosture.summary,
    steeringAction: futureDispatch.action,
    steeringScope: futureDispatch.scope,
    steeringReport: steeringSummary.operatorReport,
    reasons: [
      ...(dispatchPosture.summary.reasons || []),
      {
        code: `steering-${futureDispatch.action}`,
        message: "Operator steering changes future dispatch posture.",
      },
    ],
  };
  if (futureDispatch.targetWorkers !== undefined) summary.targetWorkers = futureDispatch.targetWorkers;
  if (futureDispatch.focusSurface) summary.focusSurface = futureDispatch.focusSurface;
  if (futureDispatch.newDispatchAllowed === false) {
    summary.newDispatchAllowed = false;
    summary.state = futureDispatch.action === "drain_and_stop" ? "drain" : "operator_paused";
  } else if (futureDispatch.action === "drain_and_shift_focus") {
    summary.state = dispatchPosture.summary.state === "allowed" ? "focused" : dispatchPosture.summary.state;
  }
  return {
    ...dispatchPosture,
    summary,
  };
}

function buildDispatchPosture(usageState = "unknown", resourceState = "unknown", weeklyUsageInput = null) {
  const reasons = [];
  const blockers = [];
  const weeklyUsage = normalizeWeeklyUsagePressure(weeklyUsageInput);
  let state = "allowed";
  let newDispatchAllowed = true;
  if (usageState === "manager_only" || resourceState === "critical") {
    state = "blocked";
    newDispatchAllowed = false;
    reasons.push({ code: usageState === "manager_only" ? "usage-manager-only" : "resource-critical", message: "Dispatch is blocked by usage or host-resource stop-line posture." });
    blockers.push({ code: "dispatch-posture-blocked", message: "New dispatch is blocked by manager-only usage or critical resource posture.", nextAction: "Do not dispatch new work until usage/resource posture recovers." });
  } else {
    if (usageState === "drain") {
      state = "drain";
      newDispatchAllowed = false;
      reasons.push({ code: "usage-drain", message: "Usage drain posture stops new dispatch." });
    } else if (usageState === "conserve") {
      state = "conservative";
      reasons.push({ code: "usage-conserve", message: "Usage conserve posture allows only necessary source-owned dispatch." });
    }
    if (weeklyUsage.state === "pressured") {
      state = state === "allowed" ? "conservative" : state;
      newDispatchAllowed = false;
      reasons.push({ code: "weekly-usage-pressure", message: "Reliable weekly usage pressure reduces new dispatch or defers optional work before model quality changes." });
    }
    if (resourceState === "pressured") {
      state = state === "allowed" ? "conservative" : state;
      newDispatchAllowed = false;
      reasons.push({ code: "resource-pressured", message: "Resource pressure limits dispatch before model quality changes." });
    } else if (resourceState === "warm" && state === "allowed") {
      state = "conservative";
      reasons.push({ code: "resource-warm", message: "Warm resource posture keeps dispatch conservative." });
    }
  }
  return {
    summary: {
      state,
      newDispatchAllowed,
      usageState,
      weeklyUsage,
      resourceState,
      modelQualityPolicy: "preserve_task_fit_quality",
      leaseIssuancePolicy: resourceState !== "normal" ? resourceLeaseIssuancePolicy(resourceState) : usageLeaseIssuancePolicy(usageState, weeklyUsage),
      usageLeaseIssuancePolicy: usageLeaseIssuancePolicy(usageState, weeklyUsage),
      activeWorkPolicy: usageActiveWorkPolicy(usageState),
      recoveryPath: "wait for usage/resource posture to recover or reduce active worker target",
      reasons,
    },
    blockers,
  };
}

function normalizePacketContext(context = {}) {
  const packetContext = safePlainObjectSnapshot(context) || {};
  const summary = safePlainObjectSnapshot(safeReadProperty(packetContext, "summary", {})) || {};
  const status = safeReadProperty(packetContext, "status", null) || safeReadProperty(packetContext, "state", null) || safeReadProperty(summary, "state", "unknown");
  const blockers = safeArrayValuesWithStatus(safeReadProperty(packetContext, "blockers", []), "blockers");
  const warnings = safeArrayValuesWithStatus(safeReadProperty(packetContext, "warnings", []), "warnings");
  const nextActions = safeArrayValuesWithStatus(safeReadProperty(packetContext, "nextActions", []), "nextActions");
  const unreadableBlockers = [blockers, warnings, nextActions]
    .filter((entry) => !entry.readable)
    .map((entry) => ({ code: `packet-${entry.field}-unreadable`, message: `Packet ${entry.field} evidence could not be read safely.` }));
  return packet({
    ok: safeReadProperty(packetContext, "ok", true),
    status,
    summary: Object.keys(summary).length > 0 ? summary : { state: status },
    blockers: [...blockers.values, ...unreadableBlockers],
    warnings: warnings.values,
    nextActions: nextActions.values,
  });
}

function safeArrayValuesWithStatus(value, field) {
  try {
    if (value === undefined || value === null) return { readable: true, field, values: [] };
    if (!Array.isArray(value)) return { readable: false, field, values: [] };
    return { readable: true, field, values: Array.from(value) };
  } catch {
    return { readable: false, field, values: [] };
  }
}

function normalizeUsagePacketContext(context = {}, outer = {}) {
  const usageContext = safePlainObjectSnapshot(context) || {};
  const outerContext = safePlainObjectSnapshot(outer) || {};
  const base = safePlainObjectSnapshot(safeReadProperty(usageContext, "summary", {})) || {};
  const status = sanitizeLedgerField(safeReadProperty(usageContext, "status", null) || safeReadProperty(usageContext, "state", null) || safeReadProperty(base, "state", "unknown"), "unknown", 80);
  const weekly = selectWeeklyUsagePressure(
    safeReadProperty(base, "weekly", null),
    safeReadProperty(usageContext, "weekly", null),
    safeReadProperty(usageContext, "weeklyUsage", null),
    safeReadProperty(usageContext, "weeklyUsageContext", null),
    safeReadProperty(usageContext, "weeklyUsagePressure", null),
    safeReadProperty(outerContext, "weeklyUsage", null),
    safeReadProperty(outerContext, "weeklyUsageContext", null),
    safeReadProperty(outerContext, "weeklyUsagePressure", null),
  );
  const rawRemaining = Number(safeReadProperty(base, "remainingPercent", undefined) ?? safeReadProperty(usageContext, "remainingPercent", undefined));
  const rawResetSeconds = Number(safeReadProperty(base, "resetInSeconds", undefined) ?? safeReadProperty(usageContext, "resetInSeconds", undefined));
  const resetTime = sanitizeLedgerField(safeReadProperty(base, "resetTime", null) || safeReadProperty(usageContext, "resetTime", null) || "", "", 40) || null;
  const resetInSeconds = Number.isFinite(rawResetSeconds) ? Math.max(0, Math.floor(rawResetSeconds)) : null;
  const parsedForResume = { resetTime, resetInSeconds };
  const managerOnly = status === "manager_only";
  const sampledAt = sanitizeLedgerField(
    safeReadProperty(base, "sampledAt", null) || safeReadProperty(usageContext, "sampledAt", null) || safeReadProperty(base, "timestamp", null) || safeReadProperty(usageContext, "timestamp", null) || safeReadProperty(outerContext, "now", null) || new Date().toISOString(),
    new Date(0).toISOString(),
    80,
  );
  const summary = {
    source: sanitizeLedgerField(safeReadProperty(base, "source", null) || safeReadProperty(usageContext, "source", null) || "injected-usage-context", "injected-usage-context", 80),
    state: status,
    remainingPercent: Number.isFinite(rawRemaining) ? boundedPercent(rawRemaining) : null,
    sampledAt,
    timestamp: sampledAt,
    resetTime,
    resetInSeconds,
    weekly,
    leaseIssuancePolicy: safeReadProperty(base, "leaseIssuancePolicy", null) || usageLeaseIssuancePolicy(status, weekly),
    activeWorkPolicy: safeReadProperty(base, "activeWorkPolicy", null) || usageActiveWorkPolicy(status),
    modelQualityPolicy: "preserve_task_fit_quality",
    managerOnlyReason: managerOnly ? sanitizeLedgerField(safeReadProperty(base, "managerOnlyReason", null) || "five_hour_usage_at_or_below_2_percent", "five_hour_usage_at_or_below_2_percent", 120) : "",
    resumeTrigger: managerOnly ? sanitizeLedgerField(safeReadProperty(base, "resumeTrigger", null) || usageResumeTrigger(parsedForResume), usageResumeTrigger(parsedForResume), 120) : "",
    available: typeof safeReadProperty(base, "available", undefined) === "boolean" ? safeReadProperty(base, "available", undefined) : typeof safeReadProperty(usageContext, "available", undefined) === "boolean" ? safeReadProperty(usageContext, "available", undefined) : undefined,
    fetcherPath: safeReadProperty(base, "fetcherPath", null) || safeReadProperty(usageContext, "fetcherPath", null) ? sanitizeLedgerField(safeReadProperty(base, "fetcherPath", null) || safeReadProperty(usageContext, "fetcherPath", null), "", 240) : undefined,
    rawPayloadRetained: false,
  };
  const blockers = safeArrayValuesWithStatus(safeReadProperty(usageContext, "blockers", []), "blockers");
  const warnings = safeArrayValuesWithStatus(safeReadProperty(usageContext, "warnings", []), "warnings");
  const nextActions = safeArrayValuesWithStatus(safeReadProperty(usageContext, "nextActions", []), "nextActions");
  const unreadableEvidence = [blockers, warnings, nextActions]
    .filter((entry) => !entry.readable)
    .map((entry) => ({ code: `usage-${entry.field}-unreadable`, message: `Usage ${entry.field} evidence could not be read safely.` }));
  return packet({
    ok: safeReadProperty(usageContext, "ok", true),
    status,
    summary,
    blockers: [...blockers.values, ...unreadableEvidence],
    warnings: warnings.readable ? warnings.values : [{ code: "usage-warnings-unreadable", message: "Usage warnings evidence could not be read safely." }],
    nextActions: nextActions.values,
  });
}

function normalizeDispatchPreviewContext(context = {}) {
  if (context.summary) {
    const normalized = normalizePacketContext(context);
    const summary = normalized.summary || {};
    const dispatch = summary.dispatch || {};
    const blockers = [
      ...(Array.isArray(normalized.blockers) ? normalized.blockers : []),
      ...(Array.isArray(summary.blockers) ? summary.blockers : []),
      ...(Array.isArray(dispatch.blockers) ? dispatch.blockers : []),
    ];
    const allowed = context.allowed ?? summary.allowed ?? dispatch.allowed ?? null;
    const selectedLane = summary.selectedLane || dispatch.selectedLane || null;
    const operationalDispatchAuthority = normalizeOperationalDispatchAuthority(
      summary.operationalDispatchAuthority ||
        summary.operational_dispatch_authority ||
        dispatch.operationalDispatchAuthority ||
        dispatch.operational_dispatch_authority,
      { allowed, selectedLane },
    );
    return packet({
      ...normalized,
      ok: normalized.ok && blockers.length === 0 && allowed !== false && normalized.status !== "blocked",
      status: normalized.status === "blocked" || blockers.length > 0 || allowed === false ? "blocked" : normalized.status,
      summary: {
        ...summary,
        allowed,
        operationalDispatchAuthority,
        blockers,
        dispatch: {
          ...dispatch,
          allowed,
          operationalDispatchAuthority,
          blockers,
        },
      },
      blockers,
    });
  }
  const dispatch = context.dispatch || {};
  const status = context.status || (dispatch.allowed === false ? "blocked" : "ready");
  const selectedLane = context.selectedLane || dispatch.selectedLane || context.selected?.itemId || null;
  const allowed = context.allowed ?? dispatch.allowed ?? null;
  const summary = {
    ...context,
    allowed,
    selectedLane,
    selectedBranch: context.selectedBranch || dispatch.branch || context.selected?.branch || null,
    baseBranch: context.baseBranch || context.base_branch || dispatch.baseBranch || dispatch.base_branch || context.selected?.baseBranch || context.selected?.base_branch || null,
    claimMutation: context.claimMutation || dispatch.claimMutation || context.selected?.mutation || null,
    operationalDispatchAuthority: normalizeOperationalDispatchAuthority(
      context.operationalDispatchAuthority ||
        context.operational_dispatch_authority ||
        dispatch.operationalDispatchAuthority ||
        dispatch.operational_dispatch_authority ||
        context.selected?.operationalDispatchAuthority ||
        context.selected?.operational_dispatch_authority,
      { allowed, selectedLane },
    ),
    recoveryPath: context.recoveryPath || context.recovery_path || dispatch.recoveryPath || dispatch.recovery_path || context.selected?.recoveryPath || context.selected?.recovery_path || null,
  };
  return packet({
    ok: context.ok ?? status !== "blocked",
    status,
    summary,
    blockers: context.blockers || [],
    warnings: context.warnings || [],
    nextActions: context.nextActions || (dispatch.allowed === true
      ? [{
          code: "dispatch-preview-ready",
          summary: dispatch.claimAction || context.selected?.action || "Safe dispatch preview is ready.",
          nextAction: dispatch.nextActionGuidance || context.selected?.nextAction || "Review dispatch preview before apply.",
        }]
      : []),
  });
}

function supersededCycleActionCodes({ cleanup = {} } = {}) {
  const staleOwnerCleanup = cleanup.summary?.staleOwnerCleanup || {};
  const hasCleanupEvidence = staleOwnerCleanup.closeoutPreview?.available === true || staleOwnerCleanup.dirtyPreservation?.available === true;
  if (!hasCleanupEvidence) return new Set();
  return new Set(["takeover-inspection-required", "assignment-ambiguous-status-action"]);
}

function suppressSupersededCycleBlockers({ blockers = [], cleanup = {} } = {}) {
  const staleOwnerCleanup = cleanup.summary?.staleOwnerCleanup || {};
  const hasCleanupEvidence = staleOwnerCleanup.closeoutPreview?.available === true || staleOwnerCleanup.dirtyPreservation?.available === true;
  if (!hasCleanupEvidence) return blockers;
  return blockers.filter((blocker) => blocker.code !== "assignment-ambiguous-status");
}

function cycleOpenLaneSummaries({ workers = {}, dispatchPreview = {} } = {}) {
  const workerRows = Array.isArray(workers.summary?.workerProgress)
    ? workers.summary.workerProgress
    : Array.isArray(workers.summary?.workers)
      ? workers.summary.workers
      : [];
  const lanes = workerRows
    .filter(isPlainObject)
    .map((worker) => ({
      assignmentId: worker.assignmentId || worker.assignment_id || worker.laneId || worker.lane_id || worker.id,
      branch: worker.branch || worker.workspaceBranch || "",
      state: worker.progressState || worker.state || worker.status || "",
    }))
    .filter((lane) => lane.assignmentId);
  if (dispatchPreview.summary?.selectedLane) {
    lanes.push({
      assignmentId: dispatchPreview.summary.selectedLane,
      branch: dispatchPreview.summary.selectedBranch || "",
      state: dispatchPreview.summary.allowed ? "dispatch_ready" : "dispatch_blocked",
    });
  }
  return lanes.slice(0, 8);
}

function cycleParkedLaneSummaries({ recovery = {} } = {}) {
  const retryRoutes = Array.isArray(recovery.summary?.retryRoutes) ? recovery.summary.retryRoutes : [];
  return retryRoutes
    .filter((route) => route?.action === "park_lane" || route?.parkedLane)
    .map((route) => {
      const parkedLane = route.parkedLane || {};
      return {
        assignmentId: parkedLane.assignmentId || route.assignmentId || route.laneId || route.id,
        branch: parkedLane.branch || route.branch || "",
        state: "parked",
        reason: parkedLane.resumeCriteria || route.reason || route.summary || "parked lane",
      };
    })
    .filter((lane) => lane.assignmentId)
    .slice(0, 8);
}

function buildCycleDispatcherState(dispatchPreview = {}) {
  const summary = dispatchPreview.summary || {};
  const counts = summary.counts || {};
  const candidateStateCounts = summary.candidateStateCounts || summary.candidate_state_counts || {};
  const queueAvailable = nonNegativeInteger(counts.dispatchable ?? counts.assignable ?? counts.queued ?? candidateStateCounts.assignable ?? candidateStateCounts.queued);
  const activeLeases = dispatchPreviewActiveLeaseCount(summary);
  return {
    dispatcher: {
      status: dispatchPreview.status || "unknown",
      allowed: summary.allowed ?? null,
      selectedLane: sanitizeLedgerField(summary.selectedLane || "", "", 120) || null,
      selectedBranch: sanitizeLedgerField(summary.selectedBranch || "", "", 160) || null,
      baseBranch: sanitizeLedgerField(summary.baseBranch || summary.base_branch || "", "", 120) || null,
      mutation: sanitizeLedgerField(summary.mutation || "none; dispatcher summary only", "none; dispatcher summary only", 120),
      recoveryPath: sanitizeLedgerField(summary.recoveryPath || summary.recovery_path || "", "", 220) || null,
      blockerCount: Array.isArray(dispatchPreview.blockers) ? dispatchPreview.blockers.length : 0,
      warningCount: Array.isArray(dispatchPreview.warnings) ? dispatchPreview.warnings.length : 0,
      rawPayloadRetained: false,
    },
    queue: {
      dispatchableCount: nonNegativeInteger(counts.dispatchable ?? counts.assignable ?? candidateStateCounts.assignable),
      queuedCount: nonNegativeInteger(counts.queued ?? candidateStateCounts.queued),
      blockedCount: nonNegativeInteger(counts.blocked ?? candidateStateCounts.blocked),
      closedCount: nonNegativeInteger(counts.closed ?? candidateStateCounts.closed),
      availableCount: queueAvailable,
      source: "dispatcher_preview",
      rawPayloadRetained: false,
    },
    lease: {
      activeCount: activeLeases,
      expiredCount: nonNegativeInteger(counts.expired ?? candidateStateCounts.expired),
      failedCount: nonNegativeInteger(counts.failed ?? candidateStateCounts.failed),
      source: "dispatcher_preview",
      rawPayloadRetained: false,
    },
  };
}

function buildCycleQueueLeaseSummary(dispatcherState = {}) {
  const dispatcher = isPlainObject(dispatcherState.dispatcher) ? dispatcherState.dispatcher : {};
  const queue = isPlainObject(dispatcherState.queue) ? dispatcherState.queue : {};
  const lease = isPlainObject(dispatcherState.lease) ? dispatcherState.lease : {};
  const queued = nonNegativeInteger(queue.availableCount ?? queue.dispatchableCount ?? queue.queuedCount);
  const leased = nonNegativeInteger(lease.activeCount);
  const blocked = nonNegativeInteger(queue.blockedCount ?? lease.failedCount);
  const dispatcherStatus = sanitizeLedgerField(dispatcher.status || "unknown", "unknown", 80);
  return {
    queued,
    leased,
    blocked,
    refilling: dispatcherStatus === "refilling",
    nextAction: dispatcher.allowed === true ? "dispatch preview ready" : dispatcherStatus,
    freshness: dispatcherStatus === "unknown" ? "unknown" : "dispatcher_preview",
  };
}

function cycleCount(value) {
  return nonNegativeInteger(value);
}

function sanitizeCycleActions(actions = []) {
  return (Array.isArray(actions) ? actions : [])
    .filter(isPlainObject)
    .slice(0, 16)
    .map((action) => ({
      ...sanitizeCyclePacketValue(action, 0, ""),
      code: sanitizeLedgerField(action.code || "cycle-action", "cycle-action", 100),
      summary: sanitizeLedgerField(action.summary || "", "", 180),
      nextAction: sanitizeLedgerField(action.nextAction || "", "", 500),
    }));
}

function sanitizeCyclePacketValue(value, depth = 0, key = "") {
  if (value === null || value === undefined) return value;
  if (typeof value === "number" || typeof value === "boolean") return value;
  if (typeof value === "string") {
    const maxLength = ["nextAction", "dryRunCommand", "applyCommand"].includes(key) ? 4000 : 600;
    return sanitizeLedgerField(shouldRedactCycleKey(key) ? "[redacted-retention-field]" : value, "", maxLength);
  }
  if (Array.isArray(value)) {
    if (depth >= 6) return [];
    return value.slice(0, 24).map((entry) => sanitizeCyclePacketValue(entry, depth + 1, key));
  }
  if (isPlainObject(value)) {
    if (depth >= 6) return {};
    const output = {};
    for (const [entryKey, entryValue] of Object.entries(value).slice(0, 60)) {
      if (typeof entryValue === "number") {
        output[entryKey] = entryValue;
        continue;
      }
      if (entryKey === "rawPayloadRetained" && entryValue === false) {
        output[entryKey] = false;
        continue;
      }
      if (shouldRedactCycleKey(entryKey)) {
        output[entryKey] = typeof entryValue === "boolean" ? false : "[redacted-retention-field]";
        continue;
      }
      output[entryKey] = sanitizeCyclePacketValue(entryValue, depth + 1, entryKey);
    }
    return output;
  }
  return sanitizeLedgerField(value, "", 120);
}

function shouldRedactCycleKey(key = "") {
  const normalized = String(key || "").toLowerCase();
  return ["raw", "scrollback", "prompt", "completion", "reasoning", "provider", "secret", "password", "token", "stack", "stdout", "stderr", "transcript", "sourcedump", "source_dump", "logbody", "log_body"].some((term) => normalized.includes(term));
}

function buildCycleSignalGaps({ usage = {}, resources = {}, dispatchPreview = {}, workers = {}, cleanup = {}, preflight = {}, context = {} } = {}) {
  const gaps = [];
  const addGap = ({ code, source, severity = "warning", reason, nextAction }) => {
    gaps.push({
      code,
      source,
      severity,
      reason: sanitizeLedgerField(reason, "Cycle packet signal is incomplete.", 180),
      nextAction: sanitizeLedgerField(nextAction, "Refresh the missing signal before manager mutation.", 180),
    });
  };
  const dispatchSummary = dispatchPreview.summary || {};
  const counts = dispatchSummary.counts || {};
  const candidateStateCounts = dispatchSummary.candidateStateCounts || dispatchSummary.candidate_state_counts || {};
  const queueCount = cycleCount(counts.dispatchable ?? counts.assignable ?? counts.queued ?? candidateStateCounts.assignable ?? candidateStateCounts.queued);
  const activeLeaseCount = cycleCount(dispatchPreviewActiveLeaseCount(dispatchSummary));
  if (context.dispatchPreview && (queueCount === null || activeLeaseCount === null)) {
    addGap({
      code: "cycle-dispatcher-counts-missing",
      source: "dispatcher",
      severity: dispatchPreview.status === "blocked" || dispatchSummary.allowed === false ? "blocker" : "warning",
      reason: "Dispatcher preview did not include complete queue and lease counts.",
      nextAction: "Refresh dispatcher status before deciding dispatch, worker, or refill action.",
    });
  }
  if (context.dispatchPreview && queueCount === null) {
    addGap({
      code: "cycle-dispatcher-queue-counts-missing",
      source: "dispatcher.queue",
      severity: dispatchPreview.status === "blocked" || dispatchSummary.allowed === false ? "blocker" : "warning",
      reason: "Dispatcher preview did not include queue or dispatchable counts.",
      nextAction: "Refresh dispatcher queue summary before refill or dispatch decisions.",
    });
  }
  if (context.dispatchPreview && activeLeaseCount === null) {
    addGap({
      code: "cycle-dispatcher-lease-counts-missing",
      source: "dispatcher.lease",
      severity: dispatchPreview.status === "blocked" || dispatchSummary.allowed === false ? "blocker" : "warning",
      reason: "Dispatcher preview did not include active lease counts.",
      nextAction: "Refresh dispatcher lease summary before inferring active work.",
    });
  }
  const usageState = usage.status || usage.summary?.state || usage.summary?.usageState || "unknown";
  if (usageState === "unknown") {
    addGap({
      code: "cycle-usage-state-unknown",
      source: "usage",
      reason: "Usage posture is unknown.",
      nextAction: "Refresh Codex usage status before dispatching new work.",
    });
  }
  const resourceState = resources.status || resources.summary?.state || resources.summary?.resourceState || "unknown";
  if (resourceState === "unknown") {
    addGap({
      code: "cycle-resource-state-unknown",
      source: "resources",
      reason: "CPU/RAM posture is unknown.",
      nextAction: "Refresh resource status before changing worker target.",
    });
  }
  if (context.workerStatus && !isPlainObject(workers.summary?.workerCounts)) {
    addGap({
      code: "cycle-worker-counts-missing",
      source: "workers",
      severity: "blocker",
      reason: "Worker status did not include workerCounts.",
      nextAction: "Refresh worker status before inferring active, warm, or paused workers.",
    });
  }
  if (context.cleanupPlan && !cleanup.summary) {
    addGap({
      code: "cycle-cleanup-summary-missing",
      source: "cleanup",
      reason: "Cleanup plan summary is unavailable.",
      nextAction: "Refresh cleanup plan before surfacing cleanup actions.",
    });
  }
  if (!preflight.summary || (context.preflightStatus && !isPlainObject(context.preflightStatus.summary))) {
    addGap({
      code: "cycle-preflight-summary-missing",
      source: "preflight",
      severity: "blocker",
      reason: "Preflight summary is unavailable.",
      nextAction: "Run manager preflight before manager mutation.",
    });
  }
  const blockers = gaps
    .filter((gap) => gap.severity === "blocker")
    .map((gap) => ({
      code: "cycle-signal-gap-blocked",
      gapCode: gap.code,
      message: gap.reason,
      source: gap.source,
      nextAction: gap.nextAction,
    }));
  const warnings = gaps
    .filter((gap) => gap.severity !== "blocker")
    .map((gap) => ({ code: gap.code, message: gap.reason, nextAction: gap.nextAction }));
  const nextActions = gaps.length > 0
    ? [{
        code: "cycle-signal-gap-refresh",
        summary: "Refresh missing or stale Cycle State Packet signals.",
        nextAction: gaps[0].nextAction,
      }]
    : [];
  return {
    status: blockers.length > 0 ? "blocked" : gaps.length > 0 ? "warning" : "ready",
    gapCount: gaps.length,
    blockerCount: blockers.length,
    gaps: gaps.slice(0, 12),
    rawPayloadRetained: false,
    blockers,
    warnings,
    nextActions,
  };
}

function buildCycleObservations({ dispatchPreview = {}, workers = {}, context = {} } = {}) {
  const dispatchSummary = dispatchPreview.summary || {};
  const dispatcherActiveCount = dispatchPreviewActiveLeaseCount(dispatchSummary);
  const workerActiveCount = nonNegativeInteger(workers.summary?.workerCounts?.active);
  const tmuxSummary = context.tmuxSummary || {};
  const tmuxActive = nonNegativeInteger(tmuxSummary.managerOwnedPanes ?? tmuxSummary.activePanes ?? tmuxSummary.paneCount);
  const logObservation = context.logObservation || {};
  const dashboardObservation = context.dashboardObservation || {};
  const logActive = nonNegativeInteger(logObservation.activeWorkers ?? logObservation.activeCount);
  const dashboardActive = nonNegativeInteger(dashboardObservation.activeWorkers ?? dashboardObservation.activeCount);
  const conflicts = [];
  const observationCounts = [
    { source: "tmux", count: tmuxActive },
    { source: "logs", count: logActive },
    { source: "dashboard", count: dashboardActive },
  ].filter((entry) => entry.count !== null && dispatcherActiveCount !== null && entry.count !== dispatcherActiveCount);
  if (dispatcherActiveCount !== null && workerActiveCount !== null && workerActiveCount !== dispatcherActiveCount) {
    conflicts.push({
      code: "cycle-worker-dispatcher-conflict",
      severity: "warning",
      message: "Worker runtime state disagrees with dispatcher/lease active work truth.",
      authoritativeSource: "dispatcher_lease_state",
      observedSources: ["workers"],
      nextAction: "Refresh dispatcher and worker status before changing work activity.",
    });
  }
  if (observationCounts.length > 0) {
    conflicts.push({
      code: "cycle-observation-dispatcher-conflict",
      severity: "warning",
      message: "Observational surfaces disagree with dispatcher/lease worker activity truth.",
      authoritativeSource: "dispatcher_lease_state",
      observedSources: observationCounts.map((entry) => entry.source).slice(0, 6),
      nextAction: "Treat observations as recovery clues and refresh dispatcher or lease state before changing work activity.",
    });
  }
  return {
    authority: "dispatcher_lease_state",
    dispatcherActiveCount,
    workerActiveCount,
    tmux: {
      role: "evidence_only",
      available: tmuxSummary.available === true || tmuxActive !== null,
      paneCount: nonNegativeInteger(tmuxSummary.paneCount),
      managerOwnedPanes: tmuxActive,
    },
    logs: {
      role: "recovery_clue_only",
      available: Object.keys(logObservation).length > 0,
      activeWorkers: logActive,
    },
    dashboard: {
      role: "read_only_projection_only",
      available: Object.keys(dashboardObservation).length > 0,
      activeWorkers: dashboardActive,
    },
    conflicts,
    rawPayloadRetained: false,
    warnings: conflicts.map((conflict) => ({
      code: conflict.code,
      message: conflict.message,
      nextAction: conflict.nextAction,
    })),
  };
}

function uniqueActions(actions = []) {
  const seen = new Set();
  const result = [];
  for (const action of actions) {
    const key = `${action.code || ""}:${action.nextAction || action.summary || ""}`;
    if (seen.has(key)) continue;
    seen.add(key);
    result.push(action);
  }
  return result;
}

function uniqueWarnings(warnings = []) {
  const seen = new Set();
  const result = [];
  for (const warning of warnings) {
    if (typeof warning === "string") {
      const key = `string:${warning}`;
      if (seen.has(key)) continue;
      seen.add(key);
      result.push(warning);
      continue;
    }
    const warningRecord = safePlainObjectSnapshot(warning) || {};
    const key = `${safeString(safeReadProperty(warningRecord, "code", ""), "")}:${safeString(safeReadProperty(warningRecord, "message", ""), "")}`;
    if (seen.has(key)) continue;
    seen.add(key);
    result.push(warningRecord);
  }
  return result;
}

export function ledgerCommand(options = {}, context = {}) {
  const runId = safeRunId(options.runId || defaultRunId());
  const paths = managerRunPaths(runId, options, context);
  if (!paths.proof.ok) {
    return packet({
      ok: false,
      status: "blocked",
      summary: { runId, stateRoot: paths.proof.state.root },
      blockers: [{ code: "workspace-state-unsafe", message: paths.proof.error, nextAction: "Choose a safe workspace state root." }],
    });
  }
  if (options.command === "init") {
    mkdirSync(paths.root, { recursive: true });
    writeJsonIfMissing(paths.mission, {
      runId,
      objective: "Complete Kendall_Nxt PRDs end to end",
      authorityProfile: "backend_proof",
      authorityStage: "backend_proof",
      runState: "starting",
      controlState: "starting",
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    });
    writeJsonIfMissing(paths.workers, []);
    writeJsonIfMissing(paths.dispatcherSummary, {
      stateSource: "dispatcher_summary_unavailable",
      freshness: "unknown",
      currentPhase: "unknown",
      nextAction: "reconstruct from dispatcher summary when available",
      updatedAt: new Date().toISOString(),
    });
    writeJsonIfMissing(paths.capabilityPosture, defaultManagerCapabilityPostureRecord(runId));
    writeJsonIfMissing(paths.checkpoints, []);
    for (const ndjson of [paths.events, paths.questions, paths.resourceSnapshots, paths.usageSnapshots]) {
      if (!existsSync(ndjson)) writeFileSync(ndjson, "");
    }
    const readiness = buildLedgerReadiness(options, context);
    if (!readiness.ok) return readiness;
    return packet({ status: "ready", summary: { runId, root: paths.root, initialized: true } });
  }
  if (options.command === "append-event") {
    const blocked = ensureLedgerAppendReady(paths, options, context, { requireEvidence: true });
    if (blocked) return blocked;
    const normalizedEventName = normalizeLedgerEventName(options.eventType || "manager.ledger.appended");
    if (!normalizedEventName) return unknownLedgerEvent(paths, options.eventType || "");
    const appended = appendLedgerEvent(paths, runId, {
      idPrefix: "evt",
      idName: "eventId",
      actor: "manager",
      typeName: "eventType",
      typeValue: options.eventType || normalizedEventName,
      options,
      fallbackSummary: "manager event",
      eventName: normalizedEventName,
      extra: ledgerEventExtra(normalizedEventName, options),
    });
    if (appended.packet) return appended.packet;
    return packet({ status: "ready", summary: { runId, event: appended.record } });
  }
  if (options.command === "append-question") {
    const blocked = ensureLedgerAppendReady(paths, options, context, { requireEvidence: true });
    if (blocked) return blocked;
    if (!isMaterialQuestionRecord(options)) {
      return packet({
        ok: false,
        status: "blocked",
        summary: { runId, recordPolicy: "material_decision_only" },
        blockers: [
          {
            code: "ledger-question-not-material",
            message: "Worker question ledger records require a material decision marker.",
            nextAction: "Answer non-material worker friction without persisting it, or mark the compact decision as material.",
          },
        ],
      });
    }
    const appended = withLedgerAppendLock(paths, () => {
      const questionsRead = readNdjsonStrict(paths.questions);
      if (questionsRead.status !== "ready") {
        return { packet: malformedLedgerFile(paths, "questions", paths.questions, questionsRead.message) };
      }
      const identity = ledgerRecordIdentity(options, {
        normalizedEventName: "manager.question.recorded",
        typeValue: options.eventType || "worker_question",
        actor: options.workerId || "worker",
      });
      const duplicate = hasExplicitLedgerIdempotencyKey(options) ? findDuplicateLedgerRecordFromArray(questionsRead.value, identity.idempotencyKey) : null;
      if (duplicate) {
        const conflict = duplicateLedgerConflict(runId, duplicate, identity, "question");
        if (conflict) return { packet: conflict };
        return { packet: duplicateLedgerPacket(runId, "question", duplicate) };
      }
      const question = ledgerRecord({
        idPrefix: "question",
        idName: "questionId",
        actor: options.workerId || "worker",
        typeName: "questionType",
        typeValue: options.eventType || "worker_question",
        options,
        fallbackSummary: "worker question",
        eventName: "manager.question.recorded",
        uniqueAutoIdempotency: !hasExplicitLedgerIdempotencyKey(options),
      });
      appendFileSync(paths.questions, `${JSON.stringify(question)}\n`);
      return { record: question };
    });
    if (appended.packet) return appended.packet;
    return packet({ status: "ready", summary: { runId, question: appended.record } });
  }
  if (options.command === "append-checkpoint") {
    const blocked = ensureLedgerAppendReady(paths, options, context, { requireEvidence: true });
    if (blocked) return blocked;
    const appended = withLedgerAppendLock(paths, () => {
      const checkpointRead = readJsonStrict(paths.checkpoints);
      if (checkpointRead.status !== "ready" || !Array.isArray(checkpointRead.value)) {
        return { packet: malformedLedgerFile(paths, "checkpoints", paths.checkpoints, "checkpoints.json must contain an array.") };
      }
      const checkpoints = checkpointRead.value;
      const identity = ledgerRecordIdentity(options, {
        normalizedEventName: "manager.checkpoint.recorded",
        typeValue: options.eventType || "manager_checkpoint",
        actor: "manager",
      });
      const duplicate = hasExplicitLedgerIdempotencyKey(options) ? findDuplicateLedgerRecordFromArray(checkpoints, identity.idempotencyKey) : null;
      if (duplicate) {
        const conflict = duplicateLedgerConflict(runId, duplicate, identity, "checkpoint");
        if (conflict) return { packet: conflict };
        return { packet: duplicateLedgerPacket(runId, "checkpoint", duplicate) };
      }
      const checkpoint = ledgerRecord({
        idPrefix: "checkpoint",
        idName: "checkpointId",
        actor: "manager",
        typeName: "checkpointType",
        typeValue: options.eventType || "manager_checkpoint",
        options,
        fallbackSummary: "manager checkpoint",
        eventName: "manager.checkpoint.recorded",
        uniqueAutoIdempotency: !hasExplicitLedgerIdempotencyKey(options),
      });
      checkpoints.push(checkpoint);
      writeFileSync(paths.checkpoints, `${JSON.stringify(checkpoints, null, 2)}\n`);
      return { record: checkpoint };
    });
    if (appended.packet) return appended.packet;
    return packet({ status: "ready", summary: { runId, checkpoint: appended.record } });
  }
  if (options.command === "append-resource-snapshot") {
    const blocked = ensureLedgerAppendReady(paths, options, context, { requireEvidence: false });
    if (blocked) return blocked;
    const appended = withLedgerAppendLock(paths, () => {
      const snapshotsRead = readNdjsonStrict(paths.resourceSnapshots);
      if (snapshotsRead.status !== "ready") {
        return { packet: malformedLedgerFile(paths, "resourceSnapshots", paths.resourceSnapshots, snapshotsRead.message) };
      }
      const extra = { resourceState: sanitizeLedgerField(options.resourceState || "unknown", "unknown", 40) };
      const identity = ledgerRecordIdentity(options, {
        normalizedEventName: "manager.resource.snapshot",
        typeValue: "resource",
        actor: "manager",
        extraParts: Object.values(extra),
      });
      const duplicate = hasExplicitLedgerIdempotencyKey(options) ? findDuplicateLedgerRecordFromArray(snapshotsRead.value, identity.idempotencyKey) : null;
      if (duplicate) {
        const conflict = duplicateLedgerConflict(runId, duplicate, identity, "snapshot");
        if (conflict) return { packet: conflict };
        return { packet: duplicateLedgerPacket(runId, "snapshot", duplicate) };
      }
      const snapshot = ledgerRecord({
        idPrefix: "resource",
        idName: "snapshotId",
        actor: "manager",
        typeName: "snapshotType",
        typeValue: "resource",
        options,
        fallbackSummary: "resource snapshot",
        eventName: "manager.resource.snapshot",
        extra,
        uniqueAutoIdempotency: true,
      });
      appendFileSync(paths.resourceSnapshots, `${JSON.stringify(snapshot)}\n`);
      return { record: snapshot };
    });
    if (appended.packet) return appended.packet;
    return packet({ status: "ready", summary: { runId, snapshot: appended.record } });
  }
  if (options.command === "append-usage-snapshot") {
    const blocked = ensureLedgerAppendReady(paths, options, context, { requireEvidence: false });
    if (blocked) return blocked;
    const appended = withLedgerAppendLock(paths, () => {
      const snapshotsRead = readNdjsonStrict(paths.usageSnapshots);
      if (snapshotsRead.status !== "ready") {
        return { packet: malformedLedgerFile(paths, "usageSnapshots", paths.usageSnapshots, snapshotsRead.message) };
      }
      const extra = { usageState: sanitizeLedgerField(options.usageState || "unknown", "unknown", 40) };
      const identity = ledgerRecordIdentity(options, {
        normalizedEventName: "manager.usage.snapshot",
        typeValue: "usage",
        actor: "manager",
        extraParts: Object.values(extra),
      });
      const duplicate = hasExplicitLedgerIdempotencyKey(options) ? findDuplicateLedgerRecordFromArray(snapshotsRead.value, identity.idempotencyKey) : null;
      if (duplicate) {
        const conflict = duplicateLedgerConflict(runId, duplicate, identity, "snapshot");
        if (conflict) return { packet: conflict };
        return { packet: duplicateLedgerPacket(runId, "snapshot", duplicate) };
      }
      const snapshot = ledgerRecord({
        idPrefix: "usage",
        idName: "snapshotId",
        actor: "manager",
        typeName: "snapshotType",
        typeValue: "usage",
        options,
        fallbackSummary: "usage snapshot",
        eventName: "manager.usage.snapshot",
        extra,
        uniqueAutoIdempotency: true,
      });
      appendFileSync(paths.usageSnapshots, `${JSON.stringify(snapshot)}\n`);
      return { record: snapshot };
    });
    if (appended.packet) return appended.packet;
    return packet({ status: "ready", summary: { runId, snapshot: appended.record } });
  }
  if (options.command === "read") {
    const readiness = buildLedgerReadiness(options, context);
    if (!readiness.ok) return readiness;
    return packet({
      status: existsSync(paths.root) ? "ready" : "missing",
      summary: {
        runId,
        root: paths.root,
        mission: readJson(paths.mission, null),
        workers: readJson(paths.workers, []),
        checkpoints: readJson(paths.checkpoints, []),
        capabilityPosture: readJson(paths.capabilityPosture, null),
        events: readNdjsonStrict(paths.events).value.slice(-10),
        questions: readNdjsonStrict(paths.questions).value.slice(-10),
        resourceSnapshots: readNdjsonStrict(paths.resourceSnapshots).value.slice(-10),
        usageSnapshots: readNdjsonStrict(paths.usageSnapshots).value.slice(-10),
        replaySummary: buildLedgerReplaySummary(paths),
        counts: {
          events: readiness.summary.eventCount,
          questions: readiness.summary.questionCount,
          resourceSnapshots: readiness.summary.resourceSnapshotCount,
          usageSnapshots: readiness.summary.usageSnapshotCount,
        },
      },
    });
  }
  return packet({
    ok: false,
    status: "blocked",
    blockers: [{ code: "unknown-ledger-command", message: `Unknown manager-ledger command: ${options.command || "(missing)"}`, nextAction: "Use init, append-event, append-question, append-checkpoint, append-resource-snapshot, append-usage-snapshot, or read." }],
  });
}

function isMaterialQuestionRecord(options = {}) {
  return options.materialDecision === true || options.materialDecision === "true" || options.recordPolicy === "material_decision_only";
}

function workspaceJsonArgs(args = [], options = {}) {
  const nextArgs = [...args];
  if (options.stateRoot) nextArgs.push("--state-root", options.stateRoot);
  if (managerWorkspaceCommandUsesOwner(nextArgs[0]) && !nextArgs.includes("--owner")) {
    const owner = options.workspaceOwner || options.owner || (options.runId ? `${options.runId}/dispatcher` : "");
    if (owner) nextArgs.push("--owner", owner);
  }
  return nextArgs;
}

function managerWorkspaceCommandUsesOwner(command) {
  return ["assignment-report", "dispatch-next", "claim-next"].includes(command);
}

function runWorkspaceJson(args, context = {}) {
  if (context.workspaceRunner) return context.workspaceRunner(args);
  const result = spawnSync(process.execPath, [join(repoRoot, "scripts/codex-workspace.mjs"), ...args], {
    cwd: repoRoot,
    encoding: "utf8",
    stdio: "pipe",
    timeout: context.timeoutMs || 5000,
  });
  if (result.error) {
    return { ok: false, error: result.error.message || "workspace command failed" };
  }
  if ((result.status ?? 1) !== 0) {
    return { ok: false, error: (result.stderr || result.stdout || result.error?.message || "workspace command failed").trim() };
  }
  if (!String(result.stdout || "").trim()) {
    return { ok: false, error: "workspace command produced no JSON output" };
  }
  try {
    return JSON.parse(result.stdout);
  } catch (error) {
    return { ok: false, error: error instanceof Error ? error.message : String(error) };
  }
}

function readAssignmentSummaryFile(path) {
  if (!path) return null;
  try {
    return JSON.parse(readFileSync(path, "utf8"));
  } catch (error) {
    return { ok: false, error: error instanceof Error ? error.message : String(error) };
  }
}

function readJson(path, fallback) {
  try {
    return JSON.parse(readFileSync(path, "utf8"));
  } catch {
    return fallback;
  }
}

function readJsonStrict(path) {
  if (!existsSync(path)) {
    return { status: "missing", value: null, message: "file is missing" };
  }
  try {
    return { status: "ready", value: JSON.parse(readFileSync(path, "utf8")), message: "" };
  } catch (error) {
    return { status: "malformed", value: null, message: error instanceof Error ? error.message : String(error) };
  }
}

function readNdjsonStrict(path) {
  if (!existsSync(path)) {
    return { status: "missing", value: [], message: "file is missing" };
  }
  const text = readFileSync(path, "utf8");
  const records = [];
  const lines = text.split(/\r?\n/).filter(Boolean);
  for (let index = 0; index < lines.length; index += 1) {
    try {
      records.push(JSON.parse(lines[index]));
    } catch (error) {
      return {
        status: "malformed",
        value: [],
        message: `line ${index + 1}: ${error instanceof Error ? error.message : String(error)}`,
      };
    }
  }
  return { status: "ready", value: records, message: "" };
}

function readJsonArray(path) {
  if (!existsSync(path)) {
    return { value: [], warning: null };
  }
  try {
    const parsed = JSON.parse(readFileSync(path, "utf8"));
    if (Array.isArray(parsed)) {
      return { value: parsed, warning: null };
    }
    return {
      value: [],
      warning: { code: "worker-state-malformed", message: "Manager workers.json must contain an array." },
    };
  } catch (error) {
    return {
      value: [],
      warning: { code: "worker-state-unreadable", message: error instanceof Error ? error.message : String(error) },
    };
  }
}

function writeJsonIfMissing(path, value) {
  if (!existsSync(path)) {
    writeFileSync(path, `${JSON.stringify(value, null, 2)}\n`);
  }
}

function isPlainObject(value) {
  return Boolean(value) && typeof value === "object" && !safeIsArray(value);
}

function safePlainObjectSnapshot(value) {
  if (!value || typeof value !== "object" || safeIsArray(value)) return null;
  try {
    return Object.fromEntries(Object.entries(value));
  } catch {
    return null;
  }
}

function safeReadProperty(value, key, fallback = undefined) {
  try {
    if (!value || typeof value !== "object") return fallback;
    const record = value;
    return record[key] ?? fallback;
  } catch {
    return fallback;
  }
}

function safeString(value, fallback = "") {
  try {
    return String(value || fallback || "");
  } catch {
    return String(fallback || "");
  }
}

function safeIsArray(value) {
  try {
    return Array.isArray(value);
  } catch {
    return false;
  }
}

function safeArrayValues(value) {
  try {
    if (!Array.isArray(value)) return [];
    return Array.from(value);
  } catch {
    return [];
  }
}

function projectWorker(worker) {
  return {
    workerId: sanitizeLedgerField(worker.workerId || worker.id || "unknown-worker", "unknown-worker", 80),
    owner: sanitizeLedgerField(worker.owner || "unknown", "unknown", 120),
    runId: sanitizeLedgerField(worker.runId || worker.run_id || "", "", 80),
    sessionName: sanitizeLedgerField(worker.sessionName || worker.session || "", "", 80),
    provider: sanitizeLedgerField(worker.provider || "unknown", "unknown", 40),
    modelPolicy: sanitizeLedgerField(worker.modelPolicy || "unknown", "unknown", 80),
    modelRoute: isPlainObject(worker.modelRoute) ? {
      policy: sanitizeLedgerField(worker.modelRoute.policy || worker.modelPolicy || "task-fit", "task-fit", 80),
      source: sanitizeLedgerField(worker.modelRoute.source || "worker_record", "worker_record", 80),
    } : null,
    state: sanitizeLedgerField(worker.state || "unknown", "unknown", 40),
    assignmentState: sanitizeLedgerField(worker.assignmentState || worker.assignment_state || worker.state || "unknown", "unknown", 40),
    assignmentId: worker.assignmentId || worker.assignment_id || null,
    taskId: worker.taskId || worker.task_id || null,
    leaseId: sanitizeLedgerField(worker.leaseId || worker.lease_id || "", "", 140) || null,
    leaseState: sanitizeLedgerField(worker.leaseState || worker.lease_state || "", "", 80) || null,
    currentLease: isPlainObject(worker.currentLease || worker.current_lease) ? {
      assignmentId: sanitizeIdentifierField((worker.currentLease || worker.current_lease).assignmentId || (worker.currentLease || worker.current_lease).assignment_id || "", "", 140),
      taskId: sanitizeIdentifierField((worker.currentLease || worker.current_lease).taskId || (worker.currentLease || worker.current_lease).task_id || "", "", 140) || null,
      leaseId: sanitizeIdentifierField((worker.currentLease || worker.current_lease).leaseId || (worker.currentLease || worker.current_lease).lease_id || worker.leaseId || worker.lease_id || "", "", 140) || null,
      state: sanitizeLedgerField((worker.currentLease || worker.current_lease).state || worker.leaseState || worker.lease_state || "", "", 80) || null,
      source: sanitizeLedgerField((worker.currentLease || worker.current_lease).source || "dispatcher_lease_state", "dispatcher_lease_state", 80),
    } : null,
    laneOwner: sanitizeLedgerField(worker.laneOwner || worker.lane_owner || "", "", 160),
    worktreePath: worker.worktreePath || worker.worktree_path || null,
    lastHeartbeatAt: worker.lastHeartbeatAt || worker.last_heartbeat_at || null,
    heartbeat: isPlainObject(worker.heartbeat) ? {
      status: sanitizeLedgerField(worker.heartbeat.status || "recorded", "recorded", 80),
      source: sanitizeLedgerField(worker.heartbeat.source || "manager-worker-heartbeat", "manager-worker-heartbeat", 80),
      lastHeartbeatAt: sanitizeLedgerField(worker.heartbeat.lastHeartbeatAt || worker.heartbeat.last_heartbeat_at || worker.lastHeartbeatAt || worker.last_heartbeat_at || "", "", 80),
    } : null,
    lastPreflight: isPlainObject(worker.lastPreflight || worker.last_preflight) ? {
      status: sanitizeLedgerField((worker.lastPreflight || worker.last_preflight).status || "unknown", "unknown", 80),
      source: sanitizeLedgerField((worker.lastPreflight || worker.last_preflight).source || "worker_record", "worker_record", 80),
    } : null,
    failureCount: Number.isFinite(Number(worker.failureCount)) ? Number(worker.failureCount) : 0,
    recoveryState: sanitizeLedgerField(worker.recoveryState || "none", "none", 40),
    recoveryAction: sanitizeLedgerField(worker.recoveryAction || worker.recovery_action || "", "", 120),
    rawPayloadRetained: false,
  };
}

function ambiguousAssignmentStatusCounts(statusCounts = {}) {
  const ambiguous = [];
  const ambiguousPattern = /(ambiguous|blocked|stale|takeover|unknown|missing|dirty|conflict|error|orphan|unsafe|failed)/i;
  for (const [bucket, counts] of Object.entries(statusCounts)) {
    for (const [status, count] of Object.entries(counts || {})) {
      if (ambiguousPattern.test(status) && Number(count) > 0) {
        ambiguous.push({ bucket, status, count: Number(count) });
      }
    }
  }
  return ambiguous;
}

function tmuxOrientationBlockers(summary = {}) {
  const checks = [
    ["tmux-workspace-errors", summary.workspaceErrorCount, "workspace orientation errors"],
    ["tmux-takeover-required", summary.takeoverRequiredPanes, "takeover-required pane(s)"],
    ["tmux-missing-worktrees", summary.missingWorktrees, "missing worktree pane(s)"],
    ["tmux-unknown-dirty", summary.unknownDirtyPanes, "pane(s) with unknown dirty state"],
    ["tmux-malformed-pane-metadata", summary.malformedPaneMetadata, "malformed tmux pane metadata row(s)"],
  ];
  return checks
    .filter(([, count]) => Number(count) > 0)
    .map(([code, count, label]) => ({
      code,
      message: `${count} ${label}.`,
      nextAction: "Resolve tmux/workspace orientation ambiguity before resuming manager mutation.",
    }));
}

function ensureManagerRunExists(paths) {
  if (existsSync(paths.root)) {
    return null;
  }
  return packet({
    ok: false,
    status: "blocked",
    summary: { runId: paths.runId, root: paths.root },
    blockers: [{ code: "manager-run-missing", message: "Manager run is not initialized.", nextAction: "Run manager-ledger init first." }],
  });
}

function ensureLedgerAppendReady(paths, options = {}, context = {}, policy = {}) {
  const missing = ensureManagerRunExists(paths);
  if (missing) return missing;
  const readiness = buildLedgerReadiness(options, context);
  if (!readiness.ok) return readiness;
  if (policy.requireEvidence) {
    const missingFields = [];
    if (!String(options.summary || "").trim()) missingFields.push("summary");
    if (!String(options.authorityBasis || "").trim()) missingFields.push("authorityBasis");
    if (!String(options.recoveryPath || "").trim()) missingFields.push("recoveryPath");
    if (sanitizeSourceRefs(options.sourceRefs || []).length === 0) missingFields.push("sourceRefs");
    if (sanitizeSourceRefs(options.evidenceRefs || options.evidenceRef || []).length === 0) missingFields.push("evidenceRefs");
    if (missingFields.length > 0) {
      return packet({
        ok: false,
        status: "blocked",
        summary: { runId: paths.runId, missingFields },
        blockers: [
          {
            code: "ledger-evidence-missing",
            message: `Ledger record is missing required evidence: ${missingFields.join(", ")}.`,
            nextAction: "Provide compact summary, source refs, authority basis, and recovery path.",
          },
        ],
      });
    }
  }
  return null;
}

function malformedLedgerFile(paths, file, path, message) {
  return packet({
    ok: false,
    status: "blocked",
    summary: { runId: paths.runId, file, path },
    blockers: [{ code: "ledger-file-malformed", message: `${file}: ${message}`, nextAction: "Repair manager ledger before appending new evidence." }],
  });
}

function readLedgerEventsStrict(paths) {
  const eventsRead = readNdjsonStrict(paths.events);
  if (eventsRead.status !== "ready") return eventsRead;
  for (let index = 0; index < eventsRead.value.length; index += 1) {
    const message = validateRuntimeLedgerEventRecord(eventsRead.value[index]);
    if (message) {
      return {
        status: "malformed",
        value: [],
        message: `line ${index + 1}: ${message}`,
      };
    }
  }
  return eventsRead;
}

function appendLedgerEvent(paths, runId, recordArgs) {
  return withLedgerAppendLock(paths, () => {
    const eventsRead = readLedgerEventsStrict(paths);
    if (eventsRead.status !== "ready") {
      return { packet: malformedLedgerFile(paths, "events", paths.events, eventsRead.message) };
    }
    const identity = ledgerRecordIdentity(recordArgs.options || {}, {
      normalizedEventName: normalizeLedgerEventName(recordArgs.eventName || recordArgs.typeValue) || "manager.ledger.appended",
      typeValue: recordArgs.typeValue,
      actor: recordArgs.actor,
      extraParts: Object.values(recordArgs.extra || {}),
    });
    const duplicate = hasExplicitLedgerIdempotencyKey(recordArgs.options) ? findDuplicateLedgerRecordFromArray(eventsRead.value, identity.idempotencyKey) : null;
    if (duplicate) {
      const conflict = duplicateLedgerConflict(runId, duplicate, identity, "event");
      if (conflict) return { packet: conflict };
      return { packet: duplicateLedgerPacket(runId, "event", duplicate) };
    }
    const record = ledgerRecord({
      ...recordArgs,
      uniqueAutoIdempotency: !hasExplicitLedgerIdempotencyKey(recordArgs.options),
    });
    appendFileSync(paths.events, `${JSON.stringify(record)}\n`);
    return { record };
  });
}

function reserveLedgerAction(paths, runId, recordArgs, { duplicateReconciler = null } = {}) {
  return withLedgerAppendLock(paths, () => {
    const eventsRead = readLedgerEventsStrict(paths);
    if (eventsRead.status !== "ready") {
      return { packet: malformedLedgerFile(paths, "events", paths.events, eventsRead.message) };
    }
    const identity = ledgerRecordIdentity(recordArgs.options || {}, {
      normalizedEventName: normalizeLedgerEventName(recordArgs.eventName || recordArgs.typeValue) || "manager.ledger.appended",
      typeValue: recordArgs.typeValue,
      actor: recordArgs.actor,
      extraParts: Object.values(recordArgs.extra || {}),
    });
    const duplicate = hasExplicitLedgerIdempotencyKey(recordArgs.options) ? findDuplicateLedgerRecordFromArray(eventsRead.value, identity.idempotencyKey) : null;
    if (duplicate) {
      if (duplicate.actionState === "reserved") {
        const conflict = duplicateLedgerConflict(runId, duplicate, identity, "event", { skipResult: true });
        if (conflict) return { packet: conflict };
        return { packet: blockedLedgerActionState(runId, duplicate, "ledger-action-reserved", "Existing ledger action reservation has not been finalized.") };
      }
      if (duplicate.result && duplicate.result !== "ready") {
        const conflict = partialLedgerActionConflictEvidence(duplicate, identity, recordArgs);
        return {
          packet: blockedLedgerActionState(runId, duplicate, "ledger-action-partial-side-effects", "Existing ledger action did not complete cleanly.", {
            conflictFields: conflict.conflictFields,
            fingerprintDrift: conflict.fingerprintDrift,
            idempotencyConflict: conflict.conflictFields.length > 0,
          }),
        };
      }
      const conflict = duplicateLedgerConflict(runId, duplicate, identity, "event");
      if (conflict) return { packet: conflict };
      const reconciled = duplicateReconciler ? duplicateReconciler(duplicate) : null;
      if (reconciled?.packet) return reconciled;
      return { packet: duplicateLedgerPacket(runId, "event", duplicate) };
    }
    const record = ledgerRecord({
      ...recordArgs,
      options: { ...(recordArgs.options || {}), result: "reserved" },
    });
    record.result = "reserved";
    record.actionState = "reserved";
    record.reservationId = record.eventId;
    record.reservedAt = record.createdAt;
    record.actionPlan = safeLedgerStructuredMetadata(recordArgs.actionPlan || {});
    appendFileSync(paths.events, `${JSON.stringify(record)}\n`);
    return { record };
  });
}

function finalizeLedgerAction(paths, runId, reservation, recordArgs) {
  return withLedgerAppendLock(paths, () => {
    const eventsRead = readLedgerEventsStrict(paths);
    if (eventsRead.status !== "ready") {
      return { packet: malformedLedgerFile(paths, "events", paths.events, eventsRead.message) };
    }
    const index = eventsRead.value.findIndex((event) => event?.eventId === reservation?.eventId && event?.idempotencyKey === reservation?.idempotencyKey);
    if (index < 0) {
      return { packet: blockedLedgerActionState(runId, reservation, "ledger-action-reservation-missing", "Ledger action reservation disappeared before finalization.") };
    }
    const existing = eventsRead.value[index];
    const next = ledgerRecord(recordArgs);
    const finalized = {
      ...existing,
      summary: next.summary,
      sourceRefs: next.sourceRefs,
      evidenceRefs: next.evidenceRefs,
      recoveryPath: next.recoveryPath,
      result: next.result,
      authorityBasis: next.authorityBasis,
      correlationId: next.correlationId,
      causationId: next.causationId,
      orderingKey: next.orderingKey,
      actionFingerprint: next.actionFingerprint,
      actionFingerprintVersion: next.actionFingerprintVersion,
      projectionBehavior: next.projectionBehavior,
      actionState: "finalized",
      finalizedAt: new Date().toISOString(),
      actionPlan: safeLedgerStructuredMetadata(recordArgs.actionPlan || existing.actionPlan || {}),
    };
    eventsRead.value[index] = finalized;
    writeNdjson(paths.events, eventsRead.value);
    return { record: finalized };
  });
}

function blockedLedgerActionState(runId, record = {}, code, message, actionResultExtras = {}) {
  return packet({
    ok: false,
    status: "blocked",
    summary: { runId, actionResult: { ...ledgerActionResult("blocked", record, "event"), ...actionResultExtras } },
    blockers: [
      {
        code,
        message,
        nextAction: "Inspect and reconcile the existing ledger action side effects before retrying.",
      },
    ],
  });
}

function blockedLedgerReconciliation(runId, record = {}, blockers = []) {
  return {
    packet: packet({
      ok: false,
      status: "blocked",
      summary: { runId, actionResult: ledgerActionResult("reconciliation_blocked", record, "event") },
      blockers: blockers.length > 0
        ? blockers
        : [{ code: "ledger-action-side-effects-missing", message: "Existing ledger action side effects could not be reconciled.", nextAction: "Inspect worker state and ledger action before retrying." }],
    }),
  };
}

function reconcileWarmLedgerDuplicate(paths, runId, planned = [], record = {}, context = {}) {
  const workerRead = readJsonArray(paths.workers);
  if (workerRead.warning) {
    return blockedLedgerReconciliation(runId, record, [{ code: workerRead.warning.code, message: workerRead.warning.message, nextAction: "Repair manager workers.json before retrying warm apply." }]);
  }
  const workers = workerRead.value.filter(isPlainObject).map(projectWorker);
  const blockers = [];
  const runner = context.tmuxRunner || spawnSync;
  for (const action of planned) {
    const worker = workers.find((candidate) => candidate.workerId === action.workerId && candidate.owner === action.owner);
    if (!worker) {
      blockers.push({ code: "ledger-action-worker-missing", message: `Warm worker record is missing for ${action.workerId}.`, nextAction: "Reconcile workers.json before retrying warm apply." });
      continue;
    }
    if (worker.sessionName !== action.sessionName || worker.runId !== runId || worker.assignmentState !== "warm") {
      blockers.push({ code: "ledger-action-worker-diverged", message: `Warm worker record diverged for ${action.workerId}.`, nextAction: "Inspect worker record before retrying warm apply." });
    }
    const session = runner("tmux", ["has-session", "-t", action.sessionName], { cwd: repoRoot, encoding: "utf8", stdio: "pipe", timeout: context.timeoutMs || 10000 });
    if ((session?.status ?? 1) !== 0) {
      blockers.push({ code: "ledger-action-worker-session-missing", message: `Warm tmux session is missing for ${action.sessionName}.`, nextAction: "Repair or retire the worker before retrying warm apply." });
    }
  }
  return blockers.length > 0 ? blockedLedgerReconciliation(runId, record, blockers) : null;
}

function reconcileHandoffLedgerDuplicate(paths, runId, pairings = [], record = {}, context = {}) {
  const workerRead = readJsonArray(paths.workers);
  if (workerRead.warning) {
    return blockedLedgerReconciliation(runId, record, [{ code: workerRead.warning.code, message: workerRead.warning.message, nextAction: "Repair manager workers.json before retrying handoff apply." }]);
  }
  const workers = workerRead.value.filter(isPlainObject).map(projectWorker);
  const blockers = [];
  for (const pairing of pairings) {
    const worker = workers.find((candidate) => candidate.workerId === pairing.workerId && candidate.owner === pairing.owner);
    if (!worker) {
      blockers.push({ code: "ledger-action-handoff-worker-missing", message: `Handoff worker record is missing for ${pairing.workerId}.`, nextAction: "Reconcile workers.json before retrying handoff apply." });
      continue;
    }
    if (worker.assignmentId !== pairing.assignmentId || worker.taskId !== pairing.taskId || worker.assignmentState !== "active") {
      blockers.push({ code: "ledger-action-handoff-worker-diverged", message: `Handoff worker assignment diverged for ${pairing.workerId}.`, nextAction: "Inspect worker assignment before retrying handoff apply." });
    }
    if (!existsSync(pairing.handoffPath)) {
      blockers.push({ code: "ledger-action-handoff-file-missing", message: `Handoff file is missing for ${pairing.workerId}.`, nextAction: "Regenerate or reconcile handoff evidence before retrying." });
    } else {
      const expectedDigest = ledgerValueDigest(renderWorkerHandoffFile(pairing));
      const actualDigest = ledgerValueDigest(readFileSync(pairing.handoffPath, "utf8"));
      if (expectedDigest !== actualDigest) {
        blockers.push({ code: "ledger-action-handoff-file-diverged", message: `Handoff file content diverged for ${pairing.workerId}.`, nextAction: "Inspect handoff file before retrying." });
      }
    }
    if (!existsSync(pairing.pastePath)) {
      blockers.push({ code: "ledger-action-handoff-pointer-missing", message: `Handoff paste pointer is missing for ${pairing.workerId}.`, nextAction: "Regenerate or reconcile handoff pointer before retrying." });
    }
  }
  return blockers.length > 0 ? blockedLedgerReconciliation(runId, record, blockers) : null;
}

function writeNdjson(path, records = []) {
  writeFileSync(path, records.map((record) => JSON.stringify(record)).join("\n") + (records.length > 0 ? "\n" : ""));
}

function withLedgerAppendLock(paths, fn) {
  const lockDir = join(paths.root, ".ledger-append.lock");
  const ownerPath = join(lockDir, "owner.json");
  const owner = {
    runId: paths.runId,
    pid: process.pid,
    process: currentLedgerLockProcessMetadata(),
    token: `${paths.runId}:${process.pid}:${Date.now()}:${process.hrtime.bigint().toString(36)}`,
    createdAt: new Date().toISOString(),
  };
  const started = Date.now();
  while (true) {
    try {
      mkdirSync(lockDir);
      writeFileSync(ownerPath, `${JSON.stringify(owner, null, 2)}\n`);
      break;
    } catch (error) {
      if (error?.code !== "EEXIST") throw error;
      if (recoverStaleLedgerAppendLock(lockDir, ownerPath)) continue;
      if (Date.now() - started > 5000) {
        const existingOwner = readJson(ownerPath, null);
        return {
          packet: packet({
            ok: false,
            status: "blocked",
            summary: { runId: paths.runId, lock: lockDir, owner: existingOwner },
            blockers: [
              {
                code: "ledger-append-lock-timeout",
                message: "Timed out waiting for manager runtime ledger append lock.",
                nextAction: "Inspect the manager ledger lock before retrying append.",
              },
            ],
          }),
        };
      }
      Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, 25);
    }
  }
  try {
    return fn();
  } finally {
    const currentOwner = readJson(ownerPath, null);
    if (currentOwner?.token === owner.token && currentOwner?.pid === owner.pid && currentOwner?.runId === owner.runId) {
      rmSync(lockDir, { recursive: true, force: true });
    }
  }
}

function recoverStaleLedgerAppendLock(lockDir, ownerPath) {
  const owner = readJson(ownerPath, null);
  const ageMs = Date.now() - (parseTimeMs(owner?.createdAt) || safeMtimeMs(lockDir) || 0);
  const pid = Number(owner?.pid);
  const pidAlive = Number.isInteger(pid) && pid > 0 ? processAlive(pid) : false;
  if (ageMs < 30000) return false;
  if (pidAlive && !ledgerLockOwnerProcessDiverged(owner)) return false;
  rmSync(lockDir, { recursive: true, force: true });
  return true;
}

function currentLedgerLockProcessMetadata() {
  const metadata = readProcessMetadata(process.pid) || {};
  return {
    execPath: process.execPath,
    argv0: process.argv[0] || "",
    cwd: process.cwd(),
    commandLineDigest: metadata.commandLineDigest || ledgerValueDigest(process.argv.join("\u0000")),
    startTime: metadata.startTime || "",
  };
}

function ledgerLockOwnerProcessDiverged(owner = {}) {
  const pid = Number(owner?.pid);
  if (!Number.isInteger(pid) || pid <= 0) return true;
  const current = readProcessMetadata(pid);
  if (!current) return false;
  const recorded = owner.process || {};
  if (recorded.startTime && current.startTime && recorded.startTime !== current.startTime) return true;
  if (recorded.commandLineDigest && current.commandLineDigest && recorded.commandLineDigest !== current.commandLineDigest) return true;
  return false;
}

function readProcessMetadata(pid) {
  try {
    const stat = readFileSync(`/proc/${pid}/stat`, "utf8");
    const afterName = stat.slice(stat.lastIndexOf(")") + 2).trim().split(/\s+/);
    const startTime = afterName[19] || "";
    const cmdline = readFileSync(`/proc/${pid}/cmdline`, "utf8");
    return {
      startTime,
      commandLineDigest: ledgerValueDigest(cmdline),
    };
  } catch {
    return null;
  }
}

function safeMtimeMs(path) {
  try {
    return statSync(path).mtimeMs;
  } catch {
    return 0;
  }
}

function processAlive(pid) {
  try {
    process.kill(pid, 0);
    return true;
  } catch (error) {
    return error?.code === "EPERM";
  }
}

function ledgerRecord({ idPrefix, idName, actor, typeName, typeValue, options = {}, fallbackSummary, eventName = "", extra = {}, uniqueAutoIdempotency = false }) {
  const recordId = `${idPrefix}-${Date.now()}-${process.hrtime.bigint().toString(36)}`;
  const createdAt = new Date().toISOString();
  const normalizedEventName = normalizeLedgerEventName(eventName || typeValue) || "manager.ledger.appended";
  const sanitizedSourceRefs = sanitizeSourceRefs(options.sourceRefs || defaultLedgerSourceRefs(normalizedEventName));
  const sanitizedEvidenceRefs = sanitizeSourceRefs(options.evidenceRefs || options.evidenceRef || defaultLedgerEvidenceRefs(normalizedEventName, recordId));
  const identity = ledgerRecordIdentity(options, {
    normalizedEventName,
    typeValue,
    actor,
    extraParts: Object.values(extra || {}),
    uniqueAutoPart: uniqueAutoIdempotency ? recordId : "",
  });
  const correlationId = sanitizeLedgerField(options.correlationId || options.correlationID || identity.idempotencyKey, identity.idempotencyKey, 120);
  return {
    [idName]: recordId,
    ...safeLedgerExtra(extra),
    eventId: recordId,
    schemaVersion: "manager_runtime_ledger_event.v1",
    eventName: normalizedEventName,
    timestamp: createdAt,
    createdAt,
    actor: sanitizeLedgerField(actor, "manager", 80),
    actorType: actor === "manager" ? "manager" : actor === "operator" ? "operator" : "worker",
    actorId: sanitizeLedgerField(actor, "manager", 80),
    [typeName]: sanitizeLedgerField(typeValue, "manager_record", 80),
    authorityBasis: sanitizeLedgerField(options.authorityBasis || "manager-owned-ledger-append", "manager-owned-ledger-append", 120),
    summary: sanitizeLedgerField(options.summary || fallbackSummary, fallbackSummary, 240),
    sourceRefs: sanitizedSourceRefs,
    recoveryPath: sanitizeLedgerField(options.recoveryPath || "inspect manager ledger and rerun resume state", "inspect manager ledger and rerun resume state", 240),
    result: sanitizeLedgerField(options.result || "recorded", "recorded", 40),
    evidenceRefs: sanitizedEvidenceRefs,
    correlationId,
    causationId: sanitizeLedgerField(options.causationId || options.causationID || correlationId, correlationId, 120),
    orderingKey: sanitizeLedgerField(options.orderingKey || identity.idempotencyKey, identity.idempotencyKey, 120),
    idempotencyKey: identity.idempotencyKey,
    actionFingerprint: identity.actionFingerprint,
    actionFingerprintVersion: identity.actionFingerprintVersion,
    redactionBoundary: sanitizeLedgerField(options.redactionBoundary || "metadata_only", "metadata_only", 40),
    projectionBehavior: sanitizeLedgerField(options.projectionBehavior || defaultLedgerProjectionBehavior(normalizedEventName), "records_evidence", 80),
    rawPayloadRetained: false,
  };
}

function ledgerRecordIdentity(options = {}, { normalizedEventName, typeValue, actor, sourceRefs = null, evidenceRefs = null, extraParts = [], uniqueAutoPart = "" } = {}) {
  const fingerprintSource = ledgerActionFingerprintSource(options, { normalizedEventName, typeValue, actor, sourceRefs, evidenceRefs, extraParts });
  const actionFingerprint = createHash("sha256").update(JSON.stringify(fingerprintSource)).digest("hex");
  const idempotencyKey = ledgerIdempotencyKey(options, {
    normalizedEventName: fingerprintSource.eventName,
    actionFingerprint,
    uniqueAutoPart,
  });
  return {
    idempotencyKey,
    actionFingerprint,
    actionFingerprintVersion: LEDGER_ACTION_FINGERPRINT_VERSION,
    eventName: fingerprintSource.eventName,
    retryMetadata: {
      authorityBasis: sanitizeLedgerField(options.authorityBasis || "manager-owned-ledger-append", "manager-owned-ledger-append", 120),
      summary: sanitizeLedgerField(options.summary || "", "", 240),
      result: sanitizeLedgerField(options.result || "recorded", "recorded", 40),
      recoveryPath: sanitizeLedgerField(options.recoveryPath || "inspect manager ledger and rerun resume state", "inspect manager ledger and rerun resume state", 240),
      correlationId: sanitizeLedgerField(options.correlationId || options.correlationID || idempotencyKey, idempotencyKey, 120),
      causationId: sanitizeLedgerField(options.causationId || options.causationID || options.correlationId || options.correlationID || idempotencyKey, idempotencyKey, 120),
      orderingKey: sanitizeLedgerField(options.orderingKey || idempotencyKey, idempotencyKey, 120),
    },
    canonical: fingerprintSource,
  };
}

function ledgerIdempotencyKey(options = {}, { normalizedEventName, actionFingerprint, uniqueAutoPart = "" } = {}) {
  const explicit = explicitLedgerIdempotencyKey(options);
  if (explicit) return explicit;
  const safeEventName = normalizeLedgerEventName(normalizedEventName) || "manager.ledger.appended";
  const uniquePart = uniqueAutoPart ? `:${hashLedgerValue(uniqueAutoPart).slice(0, 12)}` : "";
  return `auto:${safeEventName}:${String(actionFingerprint || hashLedgerValue(safeEventName)).slice(0, 24)}${uniquePart}`;
}

function ledgerActionFingerprintSource(options = {}, { normalizedEventName, typeValue, actor, sourceRefs = null, evidenceRefs = null, extraParts = [] } = {}) {
  const safeEventName = normalizeLedgerEventName(normalizedEventName || typeValue) || "manager.ledger.appended";
  return {
    schemaVersion: LEDGER_ACTION_FINGERPRINT_VERSION,
    eventName: safeEventName,
    actorDigest: ledgerValueDigest(actor || "manager"),
    typeValueDigest: ledgerValueDigest(typeValue || safeEventName),
    sourceRefDigests: canonicalLedgerDigests(sourceRefs || options.sourceRefs || defaultLedgerSourceRefs(safeEventName)),
    evidenceRefDigests: canonicalLedgerDigests(evidenceRefs || options.evidenceRefs || options.evidenceRef || defaultLedgerEvidenceRefs(safeEventName, "pending")),
    actionMaterialDigests: canonicalLedgerDigests(options.actionMaterial || []),
    extraPartDigests: canonicalLedgerDigests(extraParts),
  };
}

function canonicalLedgerRefs(refs = []) {
  const list = Array.isArray(refs) ? refs : [refs];
  return [...new Set(list.map((ref) => ledgerFingerprintField(ref)).filter(Boolean))].sort();
}

function canonicalLedgerDigests(values = []) {
  const list = Array.isArray(values) ? values : [values];
  return [...new Set(list.map((value) => ledgerValueDigest(value)).filter(Boolean))].sort();
}

function ledgerValueDigest(value) {
  return createHash("sha256").update(stableLedgerValue(value)).digest("hex");
}

function stableLedgerValue(value) {
  if (value === null || value === undefined) return "";
  if (Array.isArray(value)) return `[${value.map((entry) => stableLedgerValue(entry)).join(",")}]`;
  if (typeof value === "object") {
    return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${stableLedgerValue(value[key])}`).join(",")}}`;
  }
  return String(value)
    .replace(/[\u0000-\u001f\u007f]/g, " ")
    .replace(/\b(sk-[A-Za-z0-9_-]+|gh[pousr]_[A-Za-z0-9_]+)\b/g, (match) => `[protected-token:${hashLedgerValue(match).slice(0, 24)}]`)
    .replace(/\b(raw prompt|completion|reasoning trace|provider payload|raw transcript|transcript|stack dump|source dump|raw log|raw scrollback|OPENAI_API_KEY|password|secret)\b/gi, "[redacted-retention-term]")
    .replace(/([_-])completion(?=$|[_-])/gi, "$1[redacted-retention-term]")
    .replace(/\s+/g, " ")
    .trim();
}

function ledgerFingerprintField(value) {
  return String(value || "")
    .replace(/[\u0000-\u001f\u007f]/g, " ")
    .replace(/\b(sk-[A-Za-z0-9_-]+|gh[pousr]_[A-Za-z0-9_]+)\b/g, (match) => `[protected-token:${hashLedgerValue(match).slice(0, 24)}]`)
    .replace(/\b(raw prompt|completion|reasoning trace|provider payload|raw transcript|transcript|stack dump|source dump|raw log|raw scrollback|OPENAI_API_KEY|password|secret)\b/gi, "[redacted-retention-term]")
    .replace(/([_-])completion(?=$|[_-])/gi, "$1[redacted-retention-term]")
    .replace(/\s+/g, " ")
    .trim();
}

function hashLedgerValue(value) {
  return createHash("sha256").update(String(value || "")).digest("hex");
}

function hasExplicitLedgerIdempotencyKey(options = {}) {
  return Boolean(explicitLedgerIdempotencyKey(options));
}

function explicitLedgerIdempotencyKey(options = {}) {
  const raw = String(options.idempotencyKey || options.idempotency_key || "").trim();
  if (!raw) return "";
  const normalized = raw.replace(/[\u0000-\u001f\u007f]/g, " ").replace(/\s+/g, " ").trim();
  if (normalized.length > 160 || ledgerValueContainsProtectedMaterial(normalized)) return `explicit:${ledgerValueDigest(normalized).slice(0, 48)}`;
  const sanitized = sanitizeLedgerField(normalized, "", 160);
  if (sanitized) return sanitized;
  return `explicit:${ledgerValueDigest(raw).slice(0, 48)}`;
}

function ledgerValueContainsProtectedMaterial(value = "") {
  return /\b(sk-[A-Za-z0-9_-]+|gh[pousr]_[A-Za-z0-9_]+|OPENAI_API_KEY|password|secret)\b/i.test(String(value || ""));
}

function duplicateLedgerPacket(runId, recordName, record) {
  const existingRecordId = ledgerRecordId(record, recordName);
  const actionResult = ledgerActionResult("duplicate_ignored", record, recordName);
  return packet({
    status: "ready",
    summary: {
      runId,
      [recordName]: record,
      duplicateIgnored: true,
      actionResult: { ...actionResult, existingRecordId },
    },
  });
}

function duplicateLedgerConflict(runId, duplicate, identity = {}, recordName = "event", options = {}) {
  const conflictReasons = [];
  if (identity.eventName && duplicate.eventName && duplicate.eventName !== identity.eventName) {
    conflictReasons.push("eventName");
  }
  if (!duplicate.actionFingerprint || !duplicate.actionFingerprintVersion) {
    conflictReasons.push("legacyActionFingerprint");
  } else if (duplicate.actionFingerprintVersion !== identity.actionFingerprintVersion) {
    conflictReasons.push("actionFingerprintVersion");
  } else if (identity.actionFingerprint && duplicate.actionFingerprint !== identity.actionFingerprint) {
    conflictReasons.push("actionFingerprint");
  }
  const retryMetadata = identity.retryMetadata || {};
  if (retryMetadata.authorityBasis && duplicate.authorityBasis && duplicate.authorityBasis !== retryMetadata.authorityBasis) {
    conflictReasons.push("authorityBasis");
  }
  if (retryMetadata.summary && duplicate.summary && duplicate.summary !== retryMetadata.summary) {
    conflictReasons.push("summary");
  }
  if (!options.skipResult && retryMetadata.result && duplicate.result && duplicate.result !== retryMetadata.result) {
    conflictReasons.push("result");
  }
  if (retryMetadata.recoveryPath && duplicate.recoveryPath && duplicate.recoveryPath !== retryMetadata.recoveryPath) {
    conflictReasons.push("recoveryPath");
  }
  if (retryMetadata.correlationId && duplicate.correlationId && duplicate.correlationId !== retryMetadata.correlationId) {
    conflictReasons.push("correlationId");
  }
  if (retryMetadata.causationId && duplicate.causationId && duplicate.causationId !== retryMetadata.causationId) {
    conflictReasons.push("causationId");
  }
  if (retryMetadata.orderingKey && duplicate.orderingKey && duplicate.orderingKey !== retryMetadata.orderingKey) {
    conflictReasons.push("orderingKey");
  }
  if (conflictReasons.length === 0) return null;
  const existingRecordId = ledgerRecordId(duplicate, recordName);
  const actionResult = ledgerActionResult("conflict", duplicate, recordName);
  return packet({
    ok: false,
    status: "blocked",
    summary: {
      runId,
      actionResult: {
        ...actionResult,
        conflictFields: conflictReasons,
        existingRecordId,
        existingEventId: duplicate.eventId || existingRecordId,
      },
    },
    blockers: [
      {
        code: "ledger-idempotency-conflict",
        message: `Ledger idempotency key conflicts with existing record fields: ${conflictReasons.join(", ")}.`,
        nextAction: `Resolve ${conflictReasons[0]} for the existing ledger record or submit a new idempotency key.`,
      },
    ],
  });
}

function partialLedgerActionConflictEvidence(duplicate = {}, identity = {}, recordArgs = {}) {
  const conflictReasons = [];
  const fingerprintDrift = Boolean(
    duplicate.actionFingerprint &&
    identity.actionFingerprint &&
    duplicate.actionFingerprint !== identity.actionFingerprint,
  );
  if (identity.eventName && duplicate.eventName && duplicate.eventName !== identity.eventName) {
    conflictReasons.push("eventName");
  }
  if (!duplicate.actionFingerprint || !duplicate.actionFingerprintVersion) {
    conflictReasons.push("legacyActionFingerprint");
  } else if (duplicate.actionFingerprintVersion !== identity.actionFingerprintVersion) {
    conflictReasons.push("actionFingerprintVersion");
  } else if (partialLedgerActionMaterialChanged(duplicate.actionPlan, recordArgs.actionPlan)) {
    conflictReasons.push("actionFingerprint");
  }
  const retryMetadata = identity.retryMetadata || {};
  if (retryMetadata.authorityBasis && duplicate.authorityBasis && duplicate.authorityBasis !== retryMetadata.authorityBasis) {
    conflictReasons.push("authorityBasis");
  }
  if (retryMetadata.recoveryPath && duplicate.recoveryPath && duplicate.recoveryPath !== retryMetadata.recoveryPath) {
    conflictReasons.push("recoveryPath");
  }
  if (retryMetadata.correlationId && duplicate.correlationId && duplicate.correlationId !== retryMetadata.correlationId) {
    conflictReasons.push("correlationId");
  }
  if (retryMetadata.causationId && duplicate.causationId && duplicate.causationId !== retryMetadata.causationId) {
    conflictReasons.push("causationId");
  }
  if (retryMetadata.orderingKey && duplicate.orderingKey && duplicate.orderingKey !== retryMetadata.orderingKey) {
    conflictReasons.push("orderingKey");
  }
  return { conflictFields: conflictReasons, fingerprintDrift };
}

function partialLedgerActionMaterialChanged(existingActionPlan = {}, retryActionPlan = {}) {
  const safeRetryActionPlan = safeLedgerStructuredMetadata(retryActionPlan || {});
  const existingMaterial = isPlainObject(existingActionPlan)
    ? existingActionPlan.handoffs || existingActionPlan.workers || existingActionPlan.requests || existingActionPlan.answers || existingActionPlan.signals || null
    : null;
  const retryMaterial = isPlainObject(safeRetryActionPlan)
    ? safeRetryActionPlan.handoffs || safeRetryActionPlan.workers || safeRetryActionPlan.requests || safeRetryActionPlan.answers || safeRetryActionPlan.signals || null
    : null;
  if (existingMaterial === null || retryMaterial === null) return false;
  return stableLedgerValue(existingMaterial) !== stableLedgerValue(retryMaterial);
}

function ledgerActionResult(status, record = {}, recordName = "event") {
  return {
    status,
    existingRecordId: ledgerRecordId(record, recordName),
    eventId: record.eventId || "",
    questionId: record.questionId || "",
    checkpointId: record.checkpointId || "",
    snapshotId: record.snapshotId || "",
    eventName: record.eventName || "",
    authorityBasis: record.authorityBasis || "",
    result: record.result || "",
    sourceRefs: Array.isArray(record.sourceRefs) ? record.sourceRefs : [],
    evidenceRefs: Array.isArray(record.evidenceRefs) ? record.evidenceRefs : [],
    recoveryPath: record.recoveryPath || "",
    projectionBehavior: record.projectionBehavior || "",
    idempotencyKey: record.idempotencyKey || "",
    correlationId: record.correlationId || "",
    causationId: record.causationId || "",
    orderingKey: record.orderingKey || "",
    actionFingerprintVersion: record.actionFingerprintVersion || "",
  };
}

function ledgerRecordId(record = {}, recordName = "event") {
  const field = {
    event: "eventId",
    question: "questionId",
    checkpoint: "checkpointId",
    snapshot: "snapshotId",
  }[recordName] || "eventId";
  return record[field] || record.eventId || record.questionId || record.checkpointId || record.snapshotId || "";
}

function safeLedgerExtra(extra = {}) {
  const safe = {};
  if (Object.prototype.hasOwnProperty.call(extra, "resourceState")) {
    safe.resourceState = sanitizeLedgerField(extra.resourceState, "unknown", 40);
  }
  if (Object.prototype.hasOwnProperty.call(extra, "usageState")) {
    safe.usageState = sanitizeLedgerField(extra.usageState, "unknown", 40);
  }
  if (Object.prototype.hasOwnProperty.call(extra, "actionCode")) {
    safe.actionCode = sanitizeLedgerField(extra.actionCode, "manager-self-repair", 120);
  }
  if (Object.prototype.hasOwnProperty.call(extra, "workClass")) {
    safe.workClass = sanitizeLedgerField(extra.workClass, "manager_improvement", 80);
  }
  if (Object.prototype.hasOwnProperty.call(extra, "managerCapability")) {
    safe.managerCapability = sanitizeLedgerField(extra.managerCapability, "manager", 80);
  }
  return safe;
}

function ledgerEventExtra(eventName = "", options = {}) {
  if (eventName !== "manager.self_repair.attempted") return {};
  return {
    actionCode: options.advisorActionCode || options.actionCode || "manager-self-repair",
    workClass: options.advisorWorkClass || options.workClass || "manager_improvement",
    managerCapability: options.capabilityName || options.managerCapability || "manager",
  };
}

function safeLedgerStructuredMetadata(value, depth = 0) {
  if (depth > 4) return "[depth-limit]";
  if (value === null || value === undefined) return null;
  if (Array.isArray(value)) return value.slice(0, 24).map((entry) => safeLedgerStructuredMetadata(entry, depth + 1));
  if (typeof value === "object") {
    const safe = {};
    for (const key of Object.keys(value).sort().slice(0, 32)) {
      safe[sanitizeLedgerField(key, "field", 80)] = safeLedgerStructuredMetadata(value[key], depth + 1);
    }
    return safe;
  }
  if (typeof value === "number" || typeof value === "boolean") return value;
  return sanitizeLedgerField(stableLedgerValue(value), "", 240);
}

function defaultLedgerSourceRefs(eventName) {
  if (eventName === "manager.resource.snapshot") return ["resource:local-host"];
  if (eventName === "manager.usage.snapshot") return ["usage:codex-window"];
  return [];
}

function defaultLedgerEvidenceRefs(eventName, recordId) {
  if (eventName === "manager.resource.snapshot") return [`resource-snapshot:${recordId}`];
  if (eventName === "manager.usage.snapshot") return [`usage-snapshot:${recordId}`];
  return [];
}

function normalizeLedgerEventName(eventType = "") {
  const raw = String(eventType || "").trim();
  const direct = LEDGER_EVENT_NAMES.has(raw) ? raw : "";
  if (direct) return direct;
  return LEDGER_EVENT_ALIASES.get(raw) || "";
}

function unknownLedgerEvent(paths, eventType) {
  const label = sanitizeLedgerField(eventType || "(missing)", "(missing)", 120);
  return packet({
    ok: false,
    status: "blocked",
    summary: { runId: paths.runId, eventType: label },
    blockers: [
      {
        code: "ledger-event-unknown",
        message: `Unknown manager runtime ledger event: ${label}.`,
        nextAction: "Use a manager-control-plane event registry name before appending runtime ledger evidence.",
      },
    ],
  });
}

const LEDGER_EVENT_NAMES = new Set([
  "dispatcher.work.queued",
  "dispatcher.lease.claimed",
  "dispatcher.lease.heartbeat",
  "dispatcher.lease.expired",
  "dispatcher.attempt.completed",
  "dispatcher.attempt.failed",
  "dispatcher.refill.started",
  "dispatcher.refill.completed",
  "dispatcher.authority.blocked",
  "dispatcher.summary.updated",
  "dispatcher.summary.stale",
  "dispatcher.progress.observed",
  "dispatcher.policy.blocked_action",
  "dispatcher.recovery.attempted",
  "dispatcher.work_supply.empty",
  "manager.run.started",
  "manager.run.steered",
  "manager.ledger.appended",
  "manager.question.recorded",
  "manager.checkpoint.recorded",
  "manager.resource.snapshot",
  "manager.usage.snapshot",
  "manager.self_repair.attempted",
  "manager.blocker.recorded",
  "manager.recovery.blocked",
  "manager.replay.summarized",
]);

const LEDGER_EVENT_ALIASES = new Map([
  ["manager.event", "manager.ledger.appended"],
  ["manager.raw", "manager.ledger.appended"],
  ["manager.steering", "manager.run.steered"],
  ["manager_self_repair_attempt", "manager.self_repair.attempted"],
  ["self_repair_attempt", "manager.self_repair.attempted"],
  ["worker_target_changed", "manager.run.steered"],
  ["worker_question", "manager.question.recorded"],
  ["manager_checkpoint", "manager.checkpoint.recorded"],
  ["worker_progress_signal", "manager.ledger.appended"],
  ["worker_warm_apply", "manager.ledger.appended"],
  ["worker_handoff_apply", "manager.ledger.appended"],
  ["worker_recovery_inspection", "manager.recovery.blocked"],
  ["worker_progress_signal_apply", "manager.ledger.appended"],
  ["worker_code_review_request_apply", "manager.ledger.appended"],
  ["worker_review_feedback_apply", "manager.ledger.appended"],
  ["worker_submit_pending_apply", "manager.ledger.appended"],
  ["worker_prompt_region_submit_apply", "manager.ledger.appended"],
  ["worker_retire_apply", "manager.recovery.blocked"],
  ["worker_question_answer_apply", "manager.question.recorded"],
  ["worker_owner_delegation_apply", "manager.ledger.appended"],
  ["worker_pointer_receipt_unverified", "manager.recovery.blocked"],
]);

function findDuplicateLedgerEvent(eventsPath, idempotencyKey) {
  return findDuplicateLedgerRecord(eventsPath, idempotencyKey);
}

function findDuplicateLedgerRecord(recordsPath, idempotencyKey) {
  const key = sanitizeLedgerField(idempotencyKey || "", "", 160);
  if (!key) return null;
  const recordsRead = readNdjsonStrict(recordsPath);
  if (recordsRead.status !== "ready") return null;
  return recordsRead.value.find((event) => event?.idempotencyKey === key) || null;
}

function findDuplicateLedgerRecordFromArray(records = [], idempotencyKey) {
  const key = sanitizeLedgerField(idempotencyKey || "", "", 160);
  if (!key || !Array.isArray(records)) return null;
  return records.find((event) => event?.idempotencyKey === key) || null;
}

function validateRuntimeLedgerEventRecord(record) {
  const requiredStringFields = [
    "eventId",
    "schemaVersion",
    "eventName",
    "actorType",
    "actorId",
    "authorityBasis",
    "result",
    "correlationId",
    "causationId",
    "orderingKey",
    "idempotencyKey",
    "redactionBoundary",
    "projectionBehavior",
    "summary",
    "createdAt",
  ];
  for (const field of requiredStringFields) {
    if (!String(record?.[field] || "").trim()) return `runtime ledger event is missing required field: ${field}.`;
  }
  if (record.schemaVersion !== "manager_runtime_ledger_event.v1") {
    return "runtime ledger event has an unsupported schemaVersion.";
  }
  if (!LEDGER_EVENT_NAMES.has(record.eventName)) {
    return `runtime ledger event has unknown eventName: ${sanitizeLedgerField(record.eventName || "(missing)", "(missing)", 120)}.`;
  }
  if (!Array.isArray(record.sourceRefs) || record.sourceRefs.length === 0) {
    return "runtime ledger event is missing sourceRefs.";
  }
  if (!Array.isArray(record.evidenceRefs) || record.evidenceRefs.length === 0) {
    return "runtime ledger event is missing evidenceRefs.";
  }
  if (record.rawPayloadRetained !== false) {
    return "runtime ledger event must retain metadata only.";
  }
  return null;
}

function defaultLedgerProjectionBehavior(eventName) {
  if (eventName === "manager.recovery.blocked" || eventName === "manager.blocker.recorded") return "blocks_action";
  if (eventName === "manager.run.started" || eventName === "manager.run.steered" || eventName === "manager.replay.summarized") return "updates_summary";
  return "records_evidence";
}

function buildLedgerReplaySummary(paths) {
  const mission = readJson(paths.mission, {});
  const dispatcherSummary = readJson(paths.dispatcherSummary, {});
  const events = readNdjsonStrict(paths.events).value;
  const questions = readNdjsonStrict(paths.questions).value;
  const checkpoints = readJson(paths.checkpoints, []);
  const resourceSnapshots = readNdjsonStrict(paths.resourceSnapshots).value;
  const usageSnapshots = readNdjsonStrict(paths.usageSnapshots).value;
  const latestEvent = events.at(-1) || null;
  const selfRepair = summarizeSelfRepairAttempts(events);
  const outstandingBlockers = events
    .filter((event) => event.eventName === "manager.blocker.recorded" || event.eventName === "manager.recovery.blocked" || event.result === "blocked")
    .slice(-10)
    .map((event) => ({
      code: sanitizeLedgerField(event.eventName || event.eventType || "ledger-blocker", "ledger-blocker", 100),
      reason: sanitizeLedgerField(event.summary || "ledger blocker", "ledger blocker", 200),
      safeRepairAction: sanitizeLedgerField(event.recoveryPath || "inspect manager ledger and rerun resume state", "inspect manager ledger and rerun resume state", 220),
      evidenceRefs: Array.isArray(event.evidenceRefs) ? event.evidenceRefs : [],
    }));
  const dispatcherUnavailable =
    !isPlainObject(dispatcherSummary) ||
    dispatcherSummary.stateSource === "dispatcher_summary_unavailable" ||
    dispatcherSummary.freshness === "unknown";
  return {
    runId: paths.runId,
    mission: sanitizeLedgerField(mission.objective || "Complete Kendall_Nxt PRDs end to end", "Complete Kendall_Nxt PRDs end to end", 220),
    authorityStage: sanitizeLedgerField(mission.authorityStage || mission.authorityProfile || "backend_proof", "backend_proof", 80),
    controlState: replayControlState(mission, latestEvent),
    eventWatermark: sanitizeLedgerField(latestEvent?.eventId || latestEvent?.eventId || "", "", 140),
    outstandingBlockers,
    openQuestions: questions.slice(-10).map((question) => sanitizeLedgerField(question.summary || question.questionType || "question", "question", 180)),
    latestCheckpoints: Array.isArray(checkpoints) ? checkpoints.slice(-10).map((checkpoint) => sanitizeLedgerField(checkpoint.summary || checkpoint.checkpointType || "checkpoint", "checkpoint", 180)) : [],
    latestResourceState: sanitizeLedgerField(resourceSnapshots.at(-1)?.resourceState || "unknown", "unknown", 60),
    latestUsageState: sanitizeLedgerField(usageSnapshots.at(-1)?.usageState || "unknown", "unknown", 60),
    selfRepair,
    nextSafeAction: outstandingBlockers.length > 0
      ? "inspect_recovery_blockers"
      : dispatcherUnavailable
        ? "reconcile_dispatcher_summary"
        : "continue_monitoring",
    recoveryBlockers: outstandingBlockers,
    rawPayloadRetained: false,
    evidenceRefs: latestEvent?.evidenceRefs || [],
  };
}

function summarizeSelfRepairAttempts(events = [], options = {}) {
  const budget = Math.max(1, nonNegativeInteger(options.selfRepairBudget) ?? 2);
  const attemptsByAction = {};
  const latestAttempts = [];
  for (const event of Array.isArray(events) ? events : []) {
    if (event?.eventName !== "manager.self_repair.attempted") continue;
    const actionCode = sanitizeLedgerField(event.actionCode || "manager-self-repair", "manager-self-repair", 120);
    attemptsByAction[actionCode] = (attemptsByAction[actionCode] || 0) + 1;
    latestAttempts.push({
      actionCode,
      workClass: sanitizeLedgerField(event.workClass || "", "", 80),
      managerCapability: sanitizeLedgerField(event.managerCapability || "", "", 80),
      eventId: sanitizeLedgerField(event.eventId || "", "", 120),
      evidenceRefs: Array.isArray(event.evidenceRefs) ? event.evidenceRefs.slice(0, 6) : [],
    });
  }
  return {
    budget,
    attemptsByAction,
    attemptCount: Object.values(attemptsByAction).reduce((total, count) => total + count, 0),
    latestAttempts: latestAttempts.slice(-8),
    source: "manager_ledger_events",
    rawPayloadRetained: false,
  };
}

export function buildManagerSelfRepairSummary(options = {}, context = {}) {
  if (isPlainObject(context.selfRepairSummary || context.selfRepair)) {
    return packet({
      status: "ready",
      summary: {
        ...sanitizeCyclePacketValue(context.selfRepairSummary || context.selfRepair),
        source: "context",
        rawPayloadRetained: false,
      },
    });
  }
  const runId = safeRunId(options.runId || defaultRunId());
  const paths = managerRunPaths(runId, options, context);
  const budget = Math.max(1, nonNegativeInteger(options.selfRepairBudget ?? context.selfRepairBudget) ?? 2);
  if (!paths.proof.ok) {
    return packet({
      ok: false,
      status: "blocked",
      summary: { runId, budget, attemptsByAction: {}, attemptCount: 0, source: "workspace_state_blocked", rawPayloadRetained: false },
      blockers: [{ code: "workspace-state-unsafe", message: paths.proof.error, nextAction: "Choose a safe workspace state root." }],
    });
  }
  const read = readNdjsonStrict(paths.events);
  if (read.status !== "ready") {
    return packet({
      status: read.status === "missing" ? "missing" : "warning",
      summary: { runId, budget, attemptsByAction: {}, attemptCount: 0, source: "manager_ledger_events", rawPayloadRetained: false },
      warnings: read.status === "malformed"
        ? [{ code: "self-repair-events-unreadable", message: "Manager self-repair attempt summary could not read events.ndjson." }]
        : [],
    });
  }
  return packet({
    status: "ready",
    summary: {
      runId,
      ...summarizeSelfRepairAttempts(read.value, { selfRepairBudget: budget }),
    },
  });
}

function replayControlState(mission = {}, latestEvent = null) {
  if (latestEvent?.eventName === "manager.run.steered") return "active";
  if (latestEvent?.eventName === "manager.recovery.blocked" || latestEvent?.eventName === "manager.blocker.recorded") return "blocked";
  return sanitizeLedgerField(mission.controlState || mission.runState || "active", "active", 80);
}

function sanitizeSourceRefs(refs) {
  const list = Array.isArray(refs) ? refs : [refs];
  return list
    .map((ref) => sanitizeLedgerField(ref, "", 160))
    .filter(Boolean)
    .slice(0, 12);
}

function sanitizeLedgerField(value, fallback, maxLength) {
  const text = safeString(value, fallback)
    .replace(/[\u0000-\u001f\u007f]/g, " ")
    .replace(/\b(sk-[A-Za-z0-9_-]+|gh[pousr]_[A-Za-z0-9_]+)\b/g, "[redacted-token]")
    .replace(/\b(raw prompt|completion|reasoning trace|provider payload|raw transcript|transcript|stack dump|source dump|source copy|raw source|console log|raw log|raw scrollback|OPENAI_API_KEY|password|secret)\b/gi, "[redacted-retention-term]")
    .replace(/([_-])completion(?=$|[_-])/gi, "$1[redacted-retention-term]")
    .replace(/\s+/g, " ")
    .trim();
  return (text || fallback).slice(0, maxLength);
}

function sanitizeIdentifierField(value, fallback = "", maxLength = 140) {
  const text = safeString(value, fallback)
    .replace(/[\u0000-\u001f\u007f]/g, " ")
    .replace(/\b(sk-[A-Za-z0-9_-]+|gh[pousr]_[A-Za-z0-9_]+)\b/g, "[redacted-token]")
    .replace(/\s+/g, " ")
    .trim();
  return (text || fallback).slice(0, maxLength);
}

function isSafeCommandIdentifier(value = "") {
  const text = String(value || "");
  return Boolean(text.trim()) && !/\[redacted/i.test(text) && !/[\u0000-\u001f\u007f]/.test(text);
}

function shellQuote(value) {
  return `'${String(value).replaceAll("'", "'\\''")}'`;
}
